begin;

-- Idempotent core case/answer-key seed. Never set DA_DUYET.
insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-cap-cuu-008',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-008","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Khó thở nhanh, SpO2 thấp dù thở oxy sau viêm phổi nặng nhiều ngày","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":54,"sex":"nam","patient_label":"Ông K. N. V."},"presentation":{"intro":"Phòng cấp cứu. Người đàn ông viêm phổi 5 ngày, ho sốt, nay khó thở tăng nhanh trong vài giờ, thở oxy qua mặt nạ vẫn tím.","place":null,"clock":null,"night":false},"vitals":{"hr":124,"sbp":108,"dbp":64,"rr":36,"temperature_c":38.9,"spo2":82},"history":[{"question":"Khó thở xuất hiện và nặng lên thế nào?","response":"Ho sốt 5 ngày, khó thở tăng nhanh trong 12 giờ qua, thở như hụt hơi."},{"question":"Có bệnh tim, suy tim, tiền sử phù phổi?","response":"Không bệnh tim, chưa từng suy tim."},{"question":"Ho đờm, ho máu, đau ngực kiểu màng phổi?","response":"Ho đờm vàng, không ho máu, đau ngực nhẹ."},{"question":"Tiếp xúc nhiễm, hút thuốc, bệnh phổi nền?","response":"Hút thuốc 20 năm, không bệnh phổi mạn đã biết."},{"question":"Uống rượu, sặc thức ăn, chấn thương ngực?","response":"Không sặc, không chấn thương."},{"question":"Dị ứng thuốc?","response":"Không."},{"question":"Dùng thuốc kéo dài, truyền máu gần đây?","response":"Không."}],"examination":[{"group":"K","item":"Hô hấp","finding":"Thở nhanh nông, co kéo cơ hô hấp phụ, tím môi."},{"group":"K","item":"Phổi","finding":"Ran nổ, ran ẩm lan tỏa hai phổi."},{"group":"K","item":"Tim và tuần hoàn","finding":"Tim nhanh đều, không tiếng thổi, tĩnh mạch cổ không nổi, không phù chi."},{"group":"K","item":"Tri giác","finding":"Còn tỉnh, bứt rứt."},{"group":"K","item":"Bụng và da","finding":"Bụng mềm, không phát ban."}],"investigations":[{"name":"Khí máu động mạch (thở oxy qua mặt nạ)","duration_minutes":10,"result":"PaO2 54 mmHg với FiO2 0,6, PaO2/FiO2 khoảng 90; PaCO2 33; pH 7,46."},{"name":"X quang ngực thẳng","duration_minutes":10,"result":"Đông đặc, mờ lan tỏa hai phế trường, bóng tim bình thường."},{"name":"Siêu âm tim và phổi tại giường","duration_minutes":15,"result":"Phân suất tống máu 62%, không dấu hiệu tăng áp lực đổ đầy; nhiều đường B hai phổi."},{"name":"Công thức máu, CRP, procalcitonin, cấy đờm, cấy máu","duration_minutes":10,"result":"Bạch cầu 18 G/L; procalcitonin tăng; cấy đã lấy."},{"name":"NT-proBNP","duration_minutes":10,"result":"Giá trị thấp, không ủng hộ phù phổi do tim."},{"name":"Nội soi phế quản khẩn trước khi ổn định","duration_minutes":20,"result":"Nguy cơ tụt SpO2 thêm, không ưu tiên lúc này."},{"name":"Chụp CT ngực có cản quang khi đang thiếu oxy nặng chưa ổn định","duration_minutes":40,"result":"Nên ổn định hô hấp trước khi vận chuyển."}],"choices":{"diagnosis":{"ydx":["Thuyên tắc phổi đơn thuần","Cơn hen phế quản nặng","Hội chứng suy hô hấp cấp tiến triển (ARDS) nặng do viêm phổi, phù phổi không do tim","Phù phổi cấp huyết động do suy tim"]},"actions":["Cho corticoid liều cao kéo dài không cân nhắc","Kháng sinh phổ rộng đường tĩnh mạch sớm sau lấy cấy","Thuốc giãn cơ ngắn ngày nếu bất đồng bộ thở nặng, cân nhắc ECMO ở trung tâm chuyên sâu khi kháng trị","Chờ đến khi SpO2 dưới 70% mới đặt nội khí quản","Nằm sấp 16 giờ mỗi ngày khi PaO2/FiO2 dưới 150 mmHg","Cân bằng dịch thận trọng, tránh quá tải sau ổn định huyết động","Đặt nội khí quản kịp thời và thở máy bảo vệ phổi: thể tích khí lưu thông 6 mL/kg cân nặng lý tưởng, PEEP phù hợp","Dự phòng huyết khối, loét stress, chăm sóc dinh dưỡng sớm","Cho lợi tiểu liều cao và truyền nitrat như phù phổi huyết động","Đánh giá ABC, thở oxy cao lưu lượng hoặc oxy dòng cao qua mũi, gắn monitor, khí máu động mạch","Thông khí với thể tích khí lưu thông lớn 10 đến 12 mL/kg"]}}'::jsonb,
  '7c582098de7092847de7b67aafdfad6ad42a1262ed10a106a91d3bd537ec8fec'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-cap-cuu-008',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-008","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-008-1","resource_type":"other","source":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị hội chứng suy hô hấp cấp tiến triển (ARDS); Hướng dẫn quy trình thông khí cơ học trong hồi sức tích cực.","title":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị hội chứng suy hô hấp cấp tiến triển (ARDS); Hướng dẫn quy trình thông khí cơ học trong hồi sức tích cực.","organization":null,"year_version":null,"citation":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị hội chứng suy hô hấp cấp tiến triển (ARDS); Hướng dẫn quy trình thông khí cơ học trong hồi sức tích cực.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ards-berlin-2012","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/22797452/","title":"ARDS Definition Task Force. Acute respiratory distress syndrome: the Berlin Definition. JAMA 2012;307:2526-2533. DOI: 10.1001/jama.2012.5669.","organization":null,"year_version":null,"citation":"ARDS Definition Task Force. Acute respiratory distress syndrome: the Berlin Definition. JAMA 2012;307:2526-2533. DOI: 10.1001/jama.2012.5669.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ards-ats-2024","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/38032683/","title":"Guidelines on the management of ARDS (ATS, ESICM, SCCM). Am J Respir Crit Care Med 2024; thông khí bảo vệ phổi, nằm sấp.","organization":null,"year_version":null,"citation":"Guidelines on the management of ARDS (ATS, ESICM, SCCM). Am J Respir Crit Care Med 2024; thông khí bảo vệ phổi, nằm sấp.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"essential"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Hội chứng suy hô hấp cấp tiến triển (ARDS) nặng do viêm phổi, phù phổi không do tim","credit":"full"},{"text":"Thuyên tắc phổi đơn thuần","credit":"none"},{"text":"Phù phổi cấp huyết động do suy tim","credit":"none"},{"text":"Cơn hen phế quản nặng","credit":"none"}]},"action_options":[{"text":"Đánh giá ABC, thở oxy cao lưu lượng hoặc oxy dòng cao qua mũi, gắn monitor, khí máu động mạch","time_minutes":2,"grade":"critical","rationale":"Thiếu oxy nặng SpO2 82%."},{"text":"Đặt nội khí quản kịp thời và thở máy bảo vệ phổi: thể tích khí lưu thông 6 mL/kg cân nặng lý tưởng, PEEP phù hợp","time_minutes":10,"grade":"critical","rationale":"PaO2/FiO2 khoảng 90, kiệt sức hô hấp."},{"text":"Kháng sinh phổ rộng đường tĩnh mạch sớm sau lấy cấy","time_minutes":5,"grade":"critical","rationale":"Viêm phổi là nguyên nhân, cần điều trị căn nguyên."},{"text":"Nằm sấp 16 giờ mỗi ngày khi PaO2/FiO2 dưới 150 mmHg","time_minutes":20,"grade":"critical","rationale":"Cải thiện oxy hóa và tỉ lệ sống."},{"text":"Cân bằng dịch thận trọng, tránh quá tải sau ổn định huyết động","time_minutes":15,"grade":"critical","rationale":"Chiến lược dịch bảo thủ trong ARDS."},{"text":"Thuốc giãn cơ ngắn ngày nếu bất đồng bộ thở nặng, cân nhắc ECMO ở trung tâm chuyên sâu khi kháng trị","time_minutes":20,"grade":"recommended","rationale":"Tiêu chuẩn cứu vãn khi thiếu oxy kháng trị."},{"text":"Dự phòng huyết khối, loét stress, chăm sóc dinh dưỡng sớm","time_minutes":20,"grade":"recommended","rationale":"Chăm sóc thông thường tại hồi sức."},{"text":"Cho corticoid liều cao kéo dài không cân nhắc","time_minutes":5,"grade":"waste","rationale":"Chỉ cân nhắc theo khuyến cáo, không dùng thường quy."},{"text":"Cho lợi tiểu liều cao và truyền nitrat như phù phổi huyết động","time_minutes":0,"grade":"harmful","rationale":"Nguyên nhân không do tim, nguy cơ tụt huyết áp."},{"text":"Thông khí với thể tích khí lưu thông lớn 10 đến 12 mL/kg","time_minutes":0,"grade":"harmful","rationale":"Gây tổn thương phổi do thở máy."},{"text":"Chờ đến khi SpO2 dưới 70% mới đặt nội khí quản","time_minutes":0,"grade":"harmful","rationale":"Nguy cơ ngừng tim do thiếu oxy."}],"teaching_explanation":"ARDS: thiếu oxy nặng, X quang đông đặc hai bên, EF bình thường. Điều trị là thông khí bảo vệ phổi, nằm sấp khi nặng, điều trị căn nguyên; không phải lợi tiểu như phù phổi do tim."}'::jsonb,
  '020b3c9ff6d502485238c2935e097c54cf95c5c2a961be52352a5b2e19915be0'
)
