insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-cap-cuu-101',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-101","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Uống nhiều viên thuốc hạ sốt sau cãi vã, nôn và đau hạ sườn phải","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":19,"sex":"nữ","patient_label":"Cô T. M. A."},"presentation":{"intro":"Phòng cấp cứu. Bạn của cô A. đưa vào vì cô uống nhiều viên thuốc hạ sốt sau một cuộc cãi vã, nay buồn nôn và đau âm ỉ hạ sườn phải. Cô tỉnh, nói chuyện được, cân nặng 50 kg.","place":null,"clock":null,"night":false},"vitals":{"hr":98,"sbp":118,"dbp":72,"rr":18,"temperature_c":37,"spo2":99},"history":[{"question":"Uống thuốc gì, bao nhiêu viên, lúc mấy giờ?","response":"Khoảng 30 viên paracetamol 500 mg lấy trong tủ thuốc nhà, uống một lần lúc 8 giờ tối; bây giờ là 2 giờ sáng, cách chừng 6 giờ."},{"question":"Có uống thêm thuốc, rượu hay chất nào khác không?","response":"Không uống thuốc nào khác, không uống rượu."},{"question":"Việc uống thuốc là cố ý hay vô tình?","response":"Cô thừa nhận uống vì buồn bực, muốn tự làm hại bản thân, nay thấy hối hận."},{"question":"Sau khi uống có triệu chứng gì?","response":"Buồn nôn, nôn hai lần, đau âm ỉ dưới sườn phải, mệt."},{"question":"Có đã tự gây nôn hoặc uống than hoạt, thuốc nào trước khi đến không?","response":"Không làm gì thêm."},{"question":"Tiền sử bệnh gan, dùng rượu thường xuyên, bệnh nền khác?","response":"Không bệnh gan, không uống rượu, không bệnh mạn tính."},{"question":"Có dị ứng thuốc không, cân nặng bao nhiêu?","response":"Chưa ghi nhận dị ứng; cân nặng 50 kg."}],"examination":[{"group":"K","item":"Tri giác và dấu hiệu sinh tồn","finding":"Tỉnh táo, Glasgow 15, da niêm hồng, không vàng da."},{"group":"K","item":"Khám bụng","finding":"Ấn đau nhẹ hạ sườn phải, không phản ứng thành bụng, gan không to."},{"group":"K","item":"Tim phổi","finding":"Tim đều, phổi trong."},{"group":"K","item":"Dấu thần kinh và thở","finding":"Không run vẩy, không dấu thần kinh khu trú, nhịp thở bình thường."},{"group":"K","item":"Dấu xuất huyết","finding":"Không bầm máu hay xuất huyết dưới da."}],"investigations":[{"name":"Nồng độ paracetamol huyết thanh (lấy mẫu ở thời điểm 4 giờ trở đi, đối chiếu giản đồ Rumack-Matthew)","duration_minutes":10,"result":"Paracetamol 180 mg/L tại giờ thứ 6 sau uống, nằm trên đường điều trị (khoảng 105 mg/L ở giờ thứ 6)."},{"name":"AST, ALT, bilirubin, INR, creatinin, đường huyết, điện giải đồ","duration_minutes":10,"result":"AST 38 U/L, ALT 40 U/L, bilirubin bình thường, INR 1,0, creatinin 62 µmol/L, đường huyết 5,1 mmol/L."},{"name":"Khí máu động mạch và lactate","duration_minutes":10,"result":"pH 7,40, lactate 1,2 mmol/L."},{"name":"Định lượng salicylate và ethanol máu để tìm phối hợp độc chất","duration_minutes":10,"result":"Salicylate và ethanol không phát hiện."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Nhịp xoang 98 lần/phút, khoảng QT bình thường."},{"name":"CT sọ não không cản quang khẩn","duration_minutes":40,"result":"Không có chỉ định: tỉnh táo, không dấu thần kinh, không chấn thương."},{"name":"Siêu âm bụng khẩn trước khi quyết định dùng thuốc giải độc","duration_minutes":15,"result":"Không thay đổi quyết định điều trị; không nên trì hoãn giải độc."}],"choices":{"diagnosis":{"ydx":["Viêm dạ dày cấp do thuốc giảm đau, chưa cần giải độc","Viêm gan virus cấp","Ngộ độc paracetamol cấp có chủ ý, mức nồng độ vượt đường điều trị, chưa có tổn thương gan","Viêm túi mật cấp"]},"actions":["Theo dõi men gan, INR, creatinin, pH, lactate sau khi kết thúc NAC; tiếp tục NAC nếu men gan còn tăng","Dùng thuốc hạ sốt paracetamol khi đau hạ sườn và buồn nôn","Dùng thuốc chống nôn (ondansetron) nếu nôn nhiều","Chờ men gan tăng rồi mới cho N-acetylcystein","Gây nôn bằng ipecac hoặc ép lưỡi","Đánh giá ABC, gắn monitor, lập đường truyền tĩnh mạch, lấy máu làm xét nghiệm","Hội chẩn tâm thần, đánh giá nguy cơ tự sát trước khi xuất viện","Cho về nhà ngay vì người bệnh tỉnh táo, men gan bình thường","Lấy mẫu định lượng paracetamol ở giờ thứ 4 trở đi và đối chiếu giản đồ Rumack-Matthew","Bắt đầu N-acetylcystein tĩnh mạch: 150 mg/kg pha trong 200 mL glucose 5% truyền 60 phút, sau đó 50 mg/kg trong 4 giờ, rồi 100 mg/kg trong 16 giờ (phác đồ 3 túi theo nhãn thuốc; hướng dẫn ANZ 2020 dùng 2 túi: 200 mg/kg trong 4 giờ rồi 100 mg/kg trong 16 giờ)","Cho than hoạt 1 g/kg ngay lúc này"]}}'::jsonb,
  '5f3c674711140b88efec6754ba27f27e9e46877b4617bf3fc600ab5b258b2643'
)
on conflict (case_id) do update set
