  'noi-cap-cuu-101',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-101","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-rumack-1975","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/1134886/","title":"Rumack BH, Matthew H. Acetaminophen poisoning and toxicity. Pediatrics 1975;55:871-876 (giản đồ Rumack-Matthew).","organization":null,"year_version":null,"citation":"Rumack BH, Matthew H. Acetaminophen poisoning and toxicity. Pediatrics 1975;55:871-876 (giản đồ Rumack-Matthew).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-paracetamol-anzctg-2020","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/31786822/","title":"Chiew AL et al. Updated guidelines for the management of paracetamol poisoning in Australia and New Zealand. Med J Aust 2020;212:175-183.","organization":null,"year_version":null,"citation":"Chiew AL et al. Updated guidelines for the management of paracetamol poisoning in Australia and New Zealand. Med J Aust 2020;212:175-183.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-101-3","resource_type":"other","source":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí ngộ độc cấp (ngộ độc paracetamol); số quyết định và năm ban hành xin đối chiếu.","title":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí ngộ độc cấp (ngộ độc paracetamol); số quyết định và năm ban hành xin đối chiếu.","organization":null,"year_version":null,"citation":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí ngộ độc cấp (ngộ độc paracetamol); số quyết định và năm ban hành xin đối chiếu.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-101-4","resource_type":"other","source":"UK TOXBASE. Paracetamol poisoning (hướng dẫn xử trí, bản cập nhật gần nhất).","title":"UK TOXBASE. Paracetamol poisoning (hướng dẫn xử trí, bản cập nhật gần nhất).","organization":null,"year_version":null,"citation":"UK TOXBASE. Paracetamol poisoning (hướng dẫn xử trí, bản cập nhật gần nhất).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,5,6],"examination_essential_indices":[0,1,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm dạ dày cấp do thuốc giảm đau, chưa cần giải độc","credit":"none"},{"text":"Ngộ độc paracetamol cấp có chủ ý, mức nồng độ vượt đường điều trị, chưa có tổn thương gan","credit":"full"},{"text":"Viêm gan virus cấp","credit":"none"},{"text":"Viêm túi mật cấp","credit":"none"}]},"action_options":[{"text":"Đánh giá ABC, gắn monitor, lập đường truyền tĩnh mạch, lấy máu làm xét nghiệm","time_minutes":2,"grade":"critical","rationale":"Người bệnh đang ổn định nhưng cần đường truyền và dữ liệu nền (men gan, INR, creatinin, đường huyết)."},{"text":"Lấy mẫu định lượng paracetamol ở giờ thứ 4 trở đi và đối chiếu giản đồ Rumack-Matthew","time_minutes":3,"grade":"critical","rationale":"Quyết định điều trị dựa vào nồng độ theo thời gian kể từ lúc uống."},{"text":"Bắt đầu N-acetylcystein tĩnh mạch: 150 mg/kg pha trong 200 mL glucose 5% truyền 60 phút, sau đó 50 mg/kg trong 4 giờ, rồi 100 mg/kg trong 16 giờ (phác đồ 3 túi theo nhãn thuốc; hướng dẫn ANZ 2020 dùng 2 túi: 200 mg/kg trong 4 giờ rồi 100 mg/kg trong 16 giờ)","time_minutes":5,"grade":"critical","rationale":"NAC hiệu quả nhất trong 8 giờ đầu; nồng độ vượt đường điều trị là chỉ định."},{"text":"Dùng thuốc chống nôn (ondansetron) nếu nôn nhiều","time_minutes":3,"grade":"critical","rationale":"Nôn kéo dài làm giảm dung nạp và gây mất nước."},{"text":"Theo dõi men gan, INR, creatinin, pH, lactate sau khi kết thúc NAC; tiếp tục NAC nếu men gan còn tăng","time_minutes":10,"grade":"critical","rationale":"Quyết định ngừng NAC dựa vào ALT, INR và nồng độ paracetamol còn đo được."},{"text":"Hội chẩn tâm thần, đánh giá nguy cơ tự sát trước khi xuất viện","time_minutes":10,"grade":"recommended","rationale":"Uống thuốc có chủ ý là bệnh cảnh nguy cơ tự sát; không cho về ngay."},{"text":"Cho than hoạt 1 g/kg ngay lúc này","time_minutes":3,"grade":"waste","rationale":"Đã quá cửa sổ khoảng 2 giờ (đến 4 giờ nếu liều rất lớn), không còn lợi ích rõ trừ khi nghi uống phối hợp thuốc khác; không phải ưu tiên."},{"text":"Chờ men gan tăng rồi mới cho N-acetylcystein","time_minutes":0,"grade":"harmful","rationale":"Trì hoãn giải độc làm tăng nguy cơ suy gan; men gan tăng muộn sau 24 đến 36 giờ."},{"text":"Gây nôn bằng ipecac hoặc ép lưỡi","time_minutes":0,"grade":"harmful","rationale":"Đã quá thời gian có lợi, nguy cơ hít sặc; không được khuyến cáo."},{"text":"Dùng thuốc hạ sốt paracetamol khi đau hạ sườn và buồn nôn","time_minutes":0,"grade":"harmful","rationale":"Làm tăng thêm gánh nặng độc chất cho gan."},{"text":"Cho về nhà ngay vì người bệnh tỉnh táo, men gan bình thường","time_minutes":0,"grade":"harmful","rationale":"Giai đoạn đầu thường ít triệu chứng; nguy cơ suy gan và nguy cơ tự sát vẫn còn."}],"teaching_explanation":"Trong ngộ độc paracetamol cấp, men gan bình thường ở giờ đầu không loại trừ độc tính. Định lượng nồng độ đúng thời điểm, đối chiếu giản đồ Rumack-Matthew và dùng N-acetylcystein sớm là then chốt; luôn đánh giá yếu tố tự sát."}'::jsonb,
  'e6e4c49eafb30e72350d2cba8121ba80da24ee03f4b27cc98e0331d55d49dbc4'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-cap-cuu-102',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-102","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau đầu, lú lẫn sau đêm ngủ trong phòng kín chạy máy phát điện","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":45,"sex":"nam","patient_label":"Ông N. V. H."},"presentation":{"intro":"Phòng cấp cứu. Người nhà đưa ông H. vào lúc sáng sớm vì ông đau đầu dữ dội, nôn, lú lẫn. Đêm qua mất điện, gia đình cho máy phát điện chạy xăng đặt cạnh phòng ngủ đóng kín cửa; vợ ông cũng chóng mặt nhưng nhẹ hơn.","place":null,"clock":null,"night":false},"vitals":{"hr":124,"sbp":98,"dbp":60,"rr":28,"temperature_c":37.4,"spo2":99},"history":[{"question":"Ông ngủ ở đâu, có nguồn đốt nào trong phòng không?","response":"Ngủ trong phòng kín cửa, máy phát điện xăng đặt ở hành lang sát cửa phòng, chạy suốt đêm."},{"question":"Có ai khác trong nhà cùng triệu chứng không?","response":"Vợ bị đau đầu, chóng mặt nhẹ; hai con ngủ phòng khác thì khỏe."},{"question":"Ông có đau ngực, hồi hộp, khó thở không?","response":"Đau tức ngực trái và hồi hộp từ sáng."},{"question":"Triệu chứng bắt đầu thế nào?","response":"Thức dậy đau đầu như búa bổ, nôn hai lần, đứng không vững, lú lẫn."},{"question":"Có mất ý thức, co giật không?","response":"Ngất ngắn một lần khi đi vệ sinh, không co giật."},{"question":"Bệnh nền, thuốc đang dùng, hút thuốc?","response":"Hút thuốc 10 điếu mỗi ngày, chưa biết bệnh tim; không uống rượu đêm qua."},{"question":"Có uống thuốc ngủ hoặc chất độc nào khác không?","response":"Không."}],"examination":[{"group":"K","item":"Tri giác và thần kinh","finding":"Lơ mơ nhưng gọi mở mắt, Glasgow 13, đi loạng choạng, không liệt khu trú."},{"group":"K","item":"Da niêm","finding":"Da hồng, không tím tái."},{"group":"K","item":"Tim phổi","finding":"Tim nhanh đều, phổi thông khí đều hai bên, không ran."},{"group":"K","item":"Dấu hiệu tuần hoàn","finding":"Chi ấm, thời gian làm đầy mao mạch 2 giây, huyết áp thấp ranh giới."},{"group":"K","item":"Khám đồng tử và cổ","finding":"Đồng tử đều 3 mm, phản xạ ánh sáng bình thường, không cứng gáy."}],"investigations":[{"name":"Đo carboxyhemoglobin (COHb) bằng co-oximeter trên khí máu","duration_minutes":10,"result":"COHb 38%; pH 7,31, PaCO2 30 mmHg, PaO2 112 mmHg, HCO3 15 mmol/L."},{"name":"Lactate máu và điện giải","duration_minutes":10,"result":"Lactate 5,2 mmol/L; natri, kali bình thường."},{"name":"Điện tâm đồ 12 chuyển đạo","duration_minutes":10,"result":"Nhịp xoang nhanh 124 lần/phút, ST chênh xuống 1 đến 2 mm V4 đến V6."},{"name":"Troponin tim","duration_minutes":10,"result":"Troponin I 0,9 ng/mL (tăng)."},{"name":"Đường huyết mao mạch","duration_minutes":10,"result":"6,2 mmol/L."},{"name":"Chụp MRI sọ não khẩn trước khi thở oxy","duration_minutes":10,"result":"Không có chỉ định trước khi điều trị; làm chậm xử trí."},{"name":"Cấy máu hai bộ thường quy","duration_minutes":10,"result":"Không có dấu hiệu nhiễm trùng, không có chỉ định."}],"choices":{"diagnosis":{"ydx":["Ngộ độc khí CO cấp mức nặng, có tổn thương cơ tim và thần kinh","Ngộ độc cyanide do hít khói cháy","Ngộ độc rượu cấp","Đột quỵ thiếu máu não cấp"]},"actions":["Cho về sớm vì tỉnh táo và da hồng","Cho truyền Ringer lactate liều lớn để pha loãng","Dùng SpO2 99% trên máy đo ngón tay để kết luận không thiếu oxy và cho thở khí phòng","Đưa người bệnh ra khỏi nguồn khí CO, cho thở oxy 100% qua mặt nạ có túi dự trữ lưu lượng 15 L/phút","Làm điện tâm đồ và troponin, theo dõi liên tục","Tiếp tục thở oxy 100% đến khi hết triệu chứng (thường khoảng 4 đến 5 giờ; COHb dưới 5% không phải tiêu chí duy nhất); dặn hẹn khám lại tìm di chứng thần kinh muộn","Kiểm soát đường thở, đặt nội khí quản nếu Glasgow dưới 9 hoặc suy hô hấp","Hội chẩn hoặc chuyển trung tâm có buồng oxy cao áp nếu có ngất, dấu thần kinh, thiếu máu cơ tim hoặc COHb cao","Khám những người cùng phòng (vợ), kiểm tra nguồn rò khí","Cho thở oxy lưu lượng thấp qua ống thông mũi 2 L/phút","Gắn monitor tim, lập đường truyền, lấy khí máu có đo COHb và lactate"]}}'::jsonb,
  'efc4720b4bfe9cc990e12fc09681bdc901722e1e9251db97f3fff3b71626641d'
)
