insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-cap-cuu-102',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-102","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-102-1","resource_type":"other","source":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí ngộ độc cấp (ngộ độc khí CO); số quyết định và năm xin đối chiếu.","title":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí ngộ độc cấp (ngộ độc khí CO); số quyết định và năm xin đối chiếu.","organization":null,"year_version":null,"citation":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí ngộ độc cấp (ngộ độc khí CO); số quyết định và năm xin đối chiếu.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-co-weaver-2009","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/19297574/","title":"Weaver LK. Carbon monoxide poisoning. N Engl J Med 2009;360:1217-1225.","organization":null,"year_version":null,"citation":"Weaver LK. Carbon monoxide poisoning. N Engl J Med 2009;360:1217-1225.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-co-acep-2017","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/27993310/","title":"American College of Emergency Physicians. Clinical policy: critical issues in the management of adult patients presenting to the ED with acute carbon monoxide poisoning. Ann Emerg Med 2017.","organization":null,"year_version":null,"citation":"American College of Emergency Physicians. Clinical policy: critical issues in the management of adult patients presenting to the ED with acute carbon monoxide poisoning. Ann Emerg Med 2017.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-102-4","resource_type":"other","source":"UK TOXBASE. Carbon monoxide poisoning (hướng dẫn xử trí).","title":"UK TOXBASE. Carbon monoxide poisoning (hướng dẫn xử trí).","organization":null,"year_version":null,"citation":"UK TOXBASE. Carbon monoxide poisoning (hướng dẫn xử trí).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Đột quỵ thiếu máu não cấp","credit":"none"},{"text":"Ngộ độc rượu cấp","credit":"none"},{"text":"Ngộ độc khí CO cấp mức nặng, có tổn thương cơ tim và thần kinh","credit":"full"},{"text":"Ngộ độc cyanide do hít khói cháy","credit":"none"}]},"action_options":[{"text":"Đưa người bệnh ra khỏi nguồn khí CO, cho thở oxy 100% qua mặt nạ có túi dự trữ lưu lượng 15 L/phút","time_minutes":1,"grade":"critical","rationale":"Oxy rút ngắn bán thải COHb từ khoảng 4 đến 6 giờ xuống khoảng 60 đến 90 phút; SpO2 sai lệch nên không dựa vào."},{"text":"Gắn monitor tim, lập đường truyền, lấy khí máu có đo COHb và lactate","time_minutes":3,"grade":"critical","rationale":"COHb xác định chẩn đoán; lactate phản ánh mức độ thiếu oxy mô."},{"text":"Làm điện tâm đồ và troponin, theo dõi liên tục","time_minutes":5,"grade":"critical","rationale":"Ngộ độc CO nặng gây thiếu máu cơ tim, loạn nhịp."},{"text":"Hội chẩn hoặc chuyển trung tâm có buồng oxy cao áp nếu có ngất, dấu thần kinh, thiếu máu cơ tim hoặc COHb cao","time_minutes":10,"grade":"critical","rationale":"Oxy cao áp rút ngắn thời gian bán thải xuống khoảng 20 đến 30 phút và có thể giảm di chứng thần kinh muộn."},{"text":"Kiểm soát đường thở, đặt nội khí quản nếu Glasgow dưới 9 hoặc suy hô hấp","time_minutes":3,"grade":"recommended","rationale":"Bảo vệ đường thở khi tri giác xấu đi."},{"text":"Khám những người cùng phòng (vợ), kiểm tra nguồn rò khí","time_minutes":10,"grade":"recommended","rationale":"Có nhiều nạn nhân tiềm ẩn; cần loại bỏ nguồn gây độc."},{"text":"Tiếp tục thở oxy 100% đến khi hết triệu chứng (thường khoảng 4 đến 5 giờ; COHb dưới 5% không phải tiêu chí duy nhất); dặn hẹn khám lại tìm di chứng thần kinh muộn","time_minutes":20,"grade":"recommended","rationale":"Di chứng có thể xuất hiện sau 2 đến 40 ngày."},{"text":"Cho truyền Ringer lactate liều lớn để pha loãng","time_minutes":3,"grade":"waste","rationale":"Không có lợi ích đặc hiệu trong thải CO."},{"text":"Dùng SpO2 99% trên máy đo ngón tay để kết luận không thiếu oxy và cho thở khí phòng","time_minutes":0,"grade":"harmful","rationale":"Máy đo SpO2 thông thường không phân biệt COHb với oxyhemoglobin nên đọc cao giả."},{"text":"Cho thở oxy lưu lượng thấp qua ống thông mũi 2 L/phút","time_minutes":0,"grade":"harmful","rationale":"Không đủ để rút ngắn bán thải COHb."},{"text":"Cho về sớm vì tỉnh táo và da hồng","time_minutes":0,"grade":"harmful","rationale":"Da hồng không đáng tin; nguy cơ thiếu máu cơ tim và di chứng thần kinh muộn."}],"teaching_explanation":"SpO2 đo ngón tay có thể bình thường trong ngộ độc CO vì máy không phân biệt COHb. Chẩn đoán dựa vào hoàn cảnh phơi nhiễm và COHb; xử trí là oxy 100% sớm, theo dõi tim và cân nhắc oxy cao áp."}'::jsonb,
  '2eadd323f98071841d5fde5478a01be5bd404ee6051f0705d142167217017eda'
)
