insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-cap-cuu-103',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-103","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Rắn cắn cổ chân, sưng hoại tử, sụp mi và khó nuốt","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":38,"sex":"nam","patient_label":"Anh L. V. T."},"presentation":{"intro":"Phòng cấp cứu. Anh T., nông dân, bị rắn cắn ở cổ chân phải khi làm ruộng chiều qua. Người nhà bắt được con rắn có bạnh cổ, màu đen xám, mang theo xác rắn. Nay anh sụp mi, nói giọng mũi, nuốt sặc và thở nông.","place":null,"clock":null,"night":false},"vitals":{"hr":108,"sbp":130,"dbp":80,"rr":26,"temperature_c":37.2,"spo2":91},"history":[{"question":"Bị cắn lúc mấy giờ, ở đâu, rắn thế nào?","response":"Bị cắn cách đây 2 giờ ở cổ chân phải; rắn có bạnh cổ, màu đen xám; người nhà mang xác rắn đến."},{"question":"Đã sơ cứu gì ở nhà?","response":"Người nhà buộc dây thun chặt trên gối, rạch vết cắn và đắp lá."},{"question":"Triệu chứng toàn thân từ khi bị cắn?","response":"Mí mắt nặng dần rồi sụp, nhìn đôi, nuốt nghẹn, nói khó, thấy thở không đủ hơi."},{"question":"Vết cắn tại chỗ thay đổi thế nào?","response":"Sưng đau tăng nhanh lên tới gối, có bọng nước, da tím quanh vết cắn."},{"question":"Có chảy máu bất thường, tiểu sẫm màu không?","response":"Không chảy máu, nước tiểu vàng bình thường."},{"question":"Tiền sử dị ứng, hen, đã dùng huyết thanh trước đây, tiêm uốn ván?","response":"Không dị ứng; chưa từng dùng huyết thanh; không nhớ lần tiêm uốn ván cuối."},{"question":"Bệnh nền, thuốc đang dùng?","response":"Khỏe mạnh, không bệnh nền."}],"examination":[{"group":"K","item":"Tri giác và thần kinh sọ","finding":"Tỉnh, Glasgow 15; sụp mi hai bên, liệt vận nhãn, giọng mũi, sặc khi uống nước, gập cổ yếu."},{"group":"K","item":"Hô hấp","finding":"Thở nông, dùng cơ hô hấp phụ, phổi thông khí giảm hai đáy, SpO2 91% khí phòng."},{"group":"K","item":"Vết cắn và chi","finding":"Hai lỗ nanh cách 1,2 cm ở cổ chân phải, sưng nề lan tới gối, bọng nước, da tím, mạch mu chân còn sờ thấy."},{"group":"K","item":"Tuần hoàn","finding":"Mạch nhanh đều, huyết áp ổn, chi ấm."},{"group":"K","item":"Dấu xuất huyết","finding":"Không chảy máu chân răng, vết cắn không rỉ máu."}],"investigations":[{"name":"Khí máu động mạch","duration_minutes":10,"result":"pH 7,28, PaCO2 55 mmHg, PaO2 62 mmHg khí phòng (suy hô hấp type 2)."},{"name":"Công thức máu, đông máu toàn bộ và 20WBCT (đông máu nguyên bào 20 phút)","duration_minutes":40,"result":"Tiểu cầu 210 G/L; INR 1,1; fibrinogen 3,1 g/L; 20WBCT: máu đông."},{"name":"Creatinin, điện giải, CK","duration_minutes":10,"result":"Creatinin 88 µmol/L; kali 4,1 mmol/L; CK 280 U/L."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Nhịp xoang nhanh, không rối loạn dẫn truyền."},{"name":"X-quang cẳng chân","duration_minutes":10,"result":"Phần mềm sưng nề, không gãy xương, không hơi trong mô."},{"name":"CT sọ não khẩn để tìm xuất huyết nội sọ","duration_minutes":40,"result":"Không có chỉ định: không rối loạn đông máu, không đau đầu hay dấu thần kinh khu trú."},{"name":"Định lượng nọc rắn trong máu trước khi dùng huyết thanh","duration_minutes":10,"result":"Không có sẵn và không được chờ kết quả."}],"choices":{"diagnosis":{"ydx":["Hội chứng Guillain-Barré cấp","Rắn lục tre cắn, rối loạn đông máu","Rắn hổ mang cắn có độc tố thần kinh và hoại tử tại chỗ, suy hô hấp","Nhược cơ nặng"]},"actions":["Tháo dây buộc nếu có, bất động chi bằng nẹp, đặt thấp ngang tim, tháo nhẫn vòng","Tiêm phòng uốn ván và dùng kháng sinh theo hướng dẫn","Đắp lá, thuốc nam và chờ theo dõi tại nhà","Theo dõi liên tục SpO2, nhịp thở, Glasgow, đông máu và nước tiểu","Đánh dấu ranh giới sưng, đo vòng chi, theo dõi hội chứng chèn ép khoang và hoại tử; hội chẩn ngoại khoa","Chuẩn bị adrenalin và dùng huyết thanh kháng nọc rắn hổ mang đúng liều khuyến cáo của nhà sản xuất, sớm","Rạch rộng vết cắn và hút nọc bằng miệng hoặc dụng cụ","Rửa vết cắn bằng nước sạch, băng vô khuẩn, giảm đau paracetamol","Tiêm morphin hoặc thuốc an thần liều cao để giảm đau","Garô dây thun chặt phía trên vết cắn trong nhiều giờ","Bảo đảm đường thở và thông khí: oxy, hút đờm, đặt nội khí quản và thở máy sớm khi suy hô hấp tiến triển","Thử neostigmin sau khi tiêm atropin và theo dõi đáp ứng sụp mi, hô hấp"]}}'::jsonb,
  'bb52ded4d11e302134d929ce4fb1cdb9e0aebf57da3a35edc66e3b03fd107b90'
)
