values (
  'noi-cap-cuu-103',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-103","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-103-1","resource_type":"other","source":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí rắn cắn (hồi sức cấp cứu, chống độc); số quyết định và năm ban hành xin đối chiếu.","title":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí rắn cắn (hồi sức cấp cứu, chống độc); số quyết định và năm ban hành xin đối chiếu.","organization":null,"year_version":null,"citation":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí rắn cắn (hồi sức cấp cứu, chống độc); số quyết định và năm ban hành xin đối chiếu.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-who-searo-snakebite-2016","resource_type":"guideline","source":"https://www.who.int/publications/i/item/9789290225300","title":"World Health Organization, Regional Office for South-East Asia. Guidelines for the management of snakebite, 2nd edition, 2016.","organization":null,"year_version":null,"citation":"World Health Organization, Regional Office for South-East Asia. Guidelines for the management of snakebite, 2nd edition, 2016.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-103-3","resource_type":"other","source":"World Health Organization. Snakebite envenoming: a strategy for prevention and control, 2019.","title":"World Health Organization. Snakebite envenoming: a strategy for prevention and control, 2019.","organization":null,"year_version":null,"citation":"World Health Organization. Snakebite envenoming: a strategy for prevention and control, 2019.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-snakebite-warrell-2010","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/20109866/","title":"Warrell DA. Snakebite. Lancet 2010;375:77-88.","organization":null,"year_version":null,"citation":"Warrell DA. Snakebite. Lancet 2010;375:77-88.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,5],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Rắn lục tre cắn, rối loạn đông máu","credit":"none"},{"text":"Hội chứng Guillain-Barré cấp","credit":"none"},{"text":"Nhược cơ nặng","credit":"none"},{"text":"Rắn hổ mang cắn có độc tố thần kinh và hoại tử tại chỗ, suy hô hấp","credit":"full"}]},"action_options":[{"text":"Bảo đảm đường thở và thông khí: oxy, hút đờm, đặt nội khí quản và thở máy sớm khi suy hô hấp tiến triển","time_minutes":2,"grade":"critical","rationale":"Liệt hô hấp là nguyên nhân tử vong chính trong rắn độc thần kinh; SpO2 91% và PaCO2 55 mmHg đã báo hiệu."},{"text":"Tháo dây buộc nếu có, bất động chi bằng nẹp, đặt thấp ngang tim, tháo nhẫn vòng","time_minutes":2,"grade":"critical","rationale":"Giảm hấp thu nọc và đau; garô chặt gây thiếu máu chi và làm hoại tử nặng hơn."},{"text":"Chuẩn bị adrenalin và dùng huyết thanh kháng nọc rắn hổ mang đúng liều khuyến cáo của nhà sản xuất, sớm","time_minutes":5,"grade":"critical","rationale":"Huyết thanh đặc hiệu là điều trị cốt lõi khi có dấu độc thần kinh; phản vệ có thể xảy ra nên phải sẵn sàng."},{"text":"Thử neostigmin sau khi tiêm atropin và theo dõi đáp ứng sụp mi, hô hấp","time_minutes":10,"grade":"critical","rationale":"Thuốc ức chế cholinesterase có thể cải thiện triệu chứng liệt sau synap; không thay thế huyết thanh và thông khí."},{"text":"Rửa vết cắn bằng nước sạch, băng vô khuẩn, giảm đau paracetamol","time_minutes":5,"grade":"critical","rationale":"Chăm sóc tại chỗ, tránh nhiễm trùng; không dùng thuốc ức chế hô hấp."},{"text":"Tiêm phòng uốn ván và dùng kháng sinh theo hướng dẫn","time_minutes":10,"grade":"recommended","rationale":"Vết thương dập nát tăng nguy cơ nhiễm khuẩn, uốn ván."},{"text":"Đánh dấu ranh giới sưng, đo vòng chi, theo dõi hội chứng chèn ép khoang và hoại tử; hội chẩn ngoại khoa","time_minutes":15,"grade":"recommended","rationale":"Hoại tử mô mềm có thể cần cắt lọc, chỉ mở cân khi có chèn ép khoang thật sự."},{"text":"Theo dõi liên tục SpO2, nhịp thở, Glasgow, đông máu và nước tiểu","time_minutes":5,"grade":"recommended","rationale":"Tái đánh giá để quyết định thêm liều huyết thanh."},{"text":"Garô dây thun chặt phía trên vết cắn trong nhiều giờ","time_minutes":0,"grade":"harmful","rationale":"Gây thiếu máu chi, hoại tử và không ngăn được tác động của nọc độc thần kinh."},{"text":"Rạch rộng vết cắn và hút nọc bằng miệng hoặc dụng cụ","time_minutes":0,"grade":"harmful","rationale":"Không lấy được nọc, gây chảy máu, nhiễm trùng, tổn thương gân thần kinh."},{"text":"Đắp lá, thuốc nam và chờ theo dõi tại nhà","time_minutes":0,"grade":"harmful","rationale":"Trì hoãn huyết thanh và hồi sức trong khi liệt hô hấp tiến triển."},{"text":"Tiêm morphin hoặc thuốc an thần liều cao để giảm đau","time_minutes":0,"grade":"harmful","rationale":"Ức chế hô hấp, làm nặng thêm liệt hô hấp."}],"teaching_explanation":"Rắn hổ mang gây liệt thần kinh ngoại biên và hoại tử tại chỗ. Ưu tiên xử trí là đường thở và thông khí, bất động chi, huyết thanh kháng nọc sớm; không garô chặt, rạch hút, đắp thuốc lá."}'::jsonb,
  'bc16e897d1e1f7bb2f9c886916ee9fad06d76778f3f0262255007edfc559f1cc'
)
