  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-104","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Rắn cắn bàn tay, sưng bầm tím, chảy máu chân răng, máu không đông","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":52,"sex":"nữ","patient_label":"Bà N. T. L."},"presentation":{"intro":"Phòng cấp cứu. Bà L. đi hái rau ở bờ rào, bị con rắn màu xanh lá, đầu hình tam giác cắn vào bàn tay trái cách đây khoảng 5 giờ. Bà đến vì bàn tay sưng to, tím bầm, vết cắn rỉ máu và chảy máu chân răng.","place":null,"clock":null,"night":false},"vitals":{"hr":96,"sbp":128,"dbp":78,"rr":20,"temperature_c":37,"spo2":98},"history":[{"question":"Bị cắn lúc nào, con rắn như thế nào?","response":"Cách 5 giờ, rắn xanh lá, đầu tam giác, đuôi đỏ; con trai đánh chết và mang theo."},{"question":"Đã xử trí gì tại nhà?","response":"Buộc dây vải trên cổ tay, đắp lá và uống nước thuốc nam."},{"question":"Có chảy máu bất thường nơi khác không?","response":"Chảy máu chân răng, vết cắn rỉ máu mãi, nơi chích kim ở trạm xá bầm tím rộng."},{"question":"Triệu chứng tại chỗ?","response":"Đau nhiều, sưng từ bàn tay lên khuỷu, bầm tím lan rộng."},{"question":"Có sụp mi, nuốt khó, khó thở không?","response":"Không."},{"question":"Bệnh nền, thuốc chống đông hay thuốc giảm đau đang dùng?","response":"Không bệnh nền, không dùng chống đông; đã uống một viên ibuprofen ở trạm xá."},{"question":"Tiền sử dị ứng, tiêm uốn ván?","response":"Không dị ứng, mũi uốn ván lần cuối khi sinh con."}],"examination":[{"group":"K","item":"Vết cắn và chi trên","finding":"Hai lỗ nanh ở mu bàn tay trái, rỉ máu đỏ; sưng nề đến khuỷu, bầm tím, bọng máu."},{"group":"K","item":"Dấu xuất huyết","finding":"Chảy máu chân răng, bầm tím rải rác nơi chích, không đi ngoài phân đen."},{"group":"K","item":"Thần kinh","finding":"Không sụp mi, nuốt tốt, tỉnh táo, không liệt."},{"group":"K","item":"Hô hấp tuần hoàn","finding":"Tim đều, phổi trong, chi trên ấm, mạch quay trái bắt được."},{"group":"K","item":"Bụng","finding":"Mềm, không đau."}],"investigations":[{"name":"20WBCT (đông máu nguyên bào 20 phút, tại giường)","duration_minutes":40,"result":"Máu không đông sau 20 phút."},{"name":"Công thức máu, PT/INR, aPTT, fibrinogen","duration_minutes":10,"result":"Tiểu cầu 62 G/L; Hb 118 g/L; INR 4,8; aPTT 78 giây; fibrinogen 0,8 g/L."},{"name":"D-dimer","duration_minutes":10,"result":"D-dimer tăng cao rõ."},{"name":"Creatinin, điện giải, men gan","duration_minutes":10,"result":"Creatinin 78 µmol/L, bình thường."},{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Có hồng cầu trong nước tiểu."},{"name":"MRI bàn tay cẳng tay để tìm răng nanh gãy","duration_minutes":10,"result":"Không ảnh hưởng xử trí cấp cứu, tốn thời gian."},{"name":"Nội soi dạ dày thường quy trong cấp cứu","duration_minutes":20,"result":"Không có chỉ định, không có xuất huyết tiêu hóa."}],"choices":{"diagnosis":{"ydx":["Rắn lục tre cắn có nhiễm độc máu và rối loạn đông máu tiêu thụ","Rắn hổ mang cắn có độc tố thần kinh","Rối loạn đông máu do thiếu vitamin K","Giảm tiểu cầu miễn dịch"]},"actions":["Chỉ truyền máu và huyết tương rồi chờ, không dùng huyết thanh","Dùng huyết thanh kháng nọc rắn lục tre sớm, pha truyền tĩnh mạch, sẵn sàng adrenalin","Bất động chi, đặt ngang tim, tháo nhẫn vòng, tháo dây buộc","Tiêm phòng uốn ván dưới da hoặc hoãn đến khi đông máu bình thường; không tiêm bắp","Làm 20WBCT và xét nghiệm đông máu nền; lập hai đường truyền tĩnh mạch, tránh chọc động mạch","Tiêm bắp thuốc giảm đau hoặc kháng sinh, dùng thêm NSAID hay aspirin","Rạch rộng vết cắn và hút nọc","Theo dõi hội chứng chèn ép khoang, tưới máu bàn tay, hội chẩn ngoại khoa","Lặp lại 20WBCT sau 6 giờ từ khi dùng huyết thanh; nếu còn không đông, cân nhắc liều thứ hai","Garô thắt chặt đoạn gốc chi trong nhiều giờ","Cân nhắc huyết tương tươi đông lạnh hoặc tủa lạnh, tiểu cầu chỉ khi chảy máu nặng sau khi đã dùng huyết thanh"]}}'::jsonb,
