values (
  'noi-cap-cuu-104',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-104","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-104-1","resource_type":"other","source":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí rắn cắn (rắn lục, rối loạn đông máu); số quyết định và năm ban hành xin đối chiếu.","title":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí rắn cắn (rắn lục, rối loạn đông máu); số quyết định và năm ban hành xin đối chiếu.","organization":null,"year_version":null,"citation":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí rắn cắn (rắn lục, rối loạn đông máu); số quyết định và năm ban hành xin đối chiếu.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-who-searo-snakebite-2016","resource_type":"guideline","source":"https://www.who.int/publications/i/item/9789290225300","title":"World Health Organization, Regional Office for South-East Asia. Guidelines for the management of snakebite, 2nd edition, 2016.","organization":null,"year_version":null,"citation":"World Health Organization, Regional Office for South-East Asia. Guidelines for the management of snakebite, 2nd edition, 2016.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-104-3","resource_type":"other","source":"Isbister GK. Procoagulant snake toxins: laboratory studies, diagnosis, and understanding snakebite coagulopathy. Semin Thromb Hemost 2009;35:93-103.","title":"Isbister GK. Procoagulant snake toxins: laboratory studies, diagnosis, and understanding snakebite coagulopathy. Semin Thromb Hemost 2009;35:93-103.","organization":null,"year_version":null,"citation":"Isbister GK. Procoagulant snake toxins: laboratory studies, diagnosis, and understanding snakebite coagulopathy. Semin Thromb Hemost 2009;35:93-103.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Rắn lục tre cắn có nhiễm độc máu và rối loạn đông máu tiêu thụ","credit":"full"},{"text":"Rắn hổ mang cắn có độc tố thần kinh","credit":"none"},{"text":"Giảm tiểu cầu miễn dịch","credit":"none"},{"text":"Rối loạn đông máu do thiếu vitamin K","credit":"none"}]},"action_options":[{"text":"Làm 20WBCT và xét nghiệm đông máu nền; lập hai đường truyền tĩnh mạch, tránh chọc động mạch","time_minutes":3,"grade":"critical","rationale":"Dấu hiệu đông máu thúc đẩy quyết định huyết thanh; thủ thuật xâm lấn dễ gây chảy máu."},{"text":"Dùng huyết thanh kháng nọc rắn lục tre sớm, pha truyền tĩnh mạch, sẵn sàng adrenalin","time_minutes":5,"grade":"critical","rationale":"Rối loạn đông máu do nọc chỉ hết khi trung hòa nọc; chế phẩm máu không thay thế."},{"text":"Bất động chi, đặt ngang tim, tháo nhẫn vòng, tháo dây buộc","time_minutes":3,"grade":"critical","rationale":"Giảm sưng và hấp thu; garô chặt làm thiếu máu chi."},{"text":"Lặp lại 20WBCT sau 6 giờ từ khi dùng huyết thanh; nếu còn không đông, cân nhắc liều thứ hai","time_minutes":360,"grade":"critical","rationale":"Đánh giá hiệu quả trung hòa nọc theo hướng dẫn."},{"text":"Cân nhắc huyết tương tươi đông lạnh hoặc tủa lạnh, tiểu cầu chỉ khi chảy máu nặng sau khi đã dùng huyết thanh","time_minutes":20,"grade":"recommended","rationale":"Chế phẩm máu bổ sung yếu tố đông nhưng nọc sẽ tiếp tục tiêu thụ nếu chưa trung hòa."},{"text":"Tiêm phòng uốn ván dưới da hoặc hoãn đến khi đông máu bình thường; không tiêm bắp","time_minutes":10,"grade":"recommended","rationale":"Tiêm bắp ở người rối loạn đông máu gây tụ máu cơ."},{"text":"Theo dõi hội chứng chèn ép khoang, tưới máu bàn tay, hội chẩn ngoại khoa","time_minutes":15,"grade":"recommended","rationale":"Sưng nề căng cứng có thể cần xử trí ngoại khoa."},{"text":"Tiêm bắp thuốc giảm đau hoặc kháng sinh, dùng thêm NSAID hay aspirin","time_minutes":0,"grade":"harmful","rationale":"Gây tụ máu cơ, chảy máu tiêu hóa, làm nặng rối loạn đông máu và chức năng tiểu cầu."},{"text":"Rạch rộng vết cắn và hút nọc","time_minutes":0,"grade":"harmful","rationale":"Chảy máu không cầm, nhiễm trùng, tổn thương gân."},{"text":"Garô thắt chặt đoạn gốc chi trong nhiều giờ","time_minutes":0,"grade":"harmful","rationale":"Làm nặng thiếu máu chi, nhưng không cản được nọc độc máu."},{"text":"Chỉ truyền máu và huyết tương rồi chờ, không dùng huyết thanh","time_minutes":0,"grade":"harmful","rationale":"Nọc tiếp tục tiêu thụ fibrinogen và yếu tố đông, làm lặp lại rối loạn."}],"teaching_explanation":"Rắn lục tre gây rối loạn đông máu tiêu thụ; 20WBCT là xét nghiệm tại giường giúp quyết định huyết thanh. Huyết thanh trung hòa nọc là điều trị nền, chế phẩm máu chỉ bổ trợ; tránh tiêm bắp và thuốc ảnh hưởng đông máu."}'::jsonb,
  'f45f58dd1c77caf6e5a2d8ed50caee940ea34a4b3cfd1247e4c0d9644db5001a'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-cap-cuu-105',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-105","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Gục sau buổi chạy hành quân giữa trưa nắng, sốt 41,8 độ C, lú lẫn","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":22,"sex":"nam","patient_label":"Anh P. Q. D."},"presentation":{"intro":"Phòng cấp cứu. Anh D., sinh viên tham gia huấn luyện quân sự, chạy 12 km giữa trưa nắng (nhiệt độ 36 độ C, độ ẩm cao), đột ngột gục ngã, lú lẫn, co giật ngắn trên đường chuyển viện. Bạn cùng đội đã cởi áo và quạt mát khoảng 15 phút.","place":null,"clock":null,"night":false},"vitals":{"hr":138,"sbp":92,"dbp":54,"rr":32,"temperature_c":41.8,"spo2":94},"history":[{"question":"Hoàn cảnh xảy ra, thời tiết, thời gian vận động?","response":"Chạy hành quân 12 km từ 11 giờ, nắng 36 độ C, ẩm cao, mặc quân phục dày, uống rất ít nước."},{"question":"Triệu chứng trước khi gục?","response":"Chóng mặt, nhức đầu, buồn nôn, rồi nói lảm nhảm và gục."},{"question":"Có co giật không?","response":"Co giật toàn thân ngắn khoảng một phút trên xe."},{"question":"Tiểu như thế nào gần đây?","response":"Từ sáng chưa tiểu; nước tiểu sẫm màu."},{"question":"Bệnh nền, thuốc, rượu, chất kích thích, đợt ốm gần đây?","response":"Mới sốt nhẹ ba ngày trước, tự uống thuốc cảm; không rượu, không dùng chất kích thích."},{"question":"Tiền sử say nóng, bệnh tim, thần kinh, động kinh?","response":"Không."},{"question":"Đã xử trí gì ngay sau khi gục?","response":"Cởi áo, quạt mát, chườm trán, chưa ngâm nước."}],"examination":[{"group":"K","item":"Nhiệt độ trung tâm (hậu môn) và tri giác","finding":"Nhiệt độ hậu môn 41,8 độ C; mê, Glasgow 9, kích động từng lúc."},{"group":"K","item":"Da","finding":"Da nóng, đỏ, còn vã mồ hôi nhẹ (say nóng do gắng sức)."},{"group":"K","item":"Tuần hoàn","finding":"Mạch nhanh nhỏ, huyết áp 92/54 mmHg, chi mát, thời gian làm đầy mao mạch 3 giây."},{"group":"K","item":"Hô hấp","finding":"Thở nhanh nông, phổi không ran, SpO2 94%."},{"group":"K","item":"Cơ và nước tiểu","finding":"Đau cơ căng cứng khi sờ, nước tiểu sẫm màu như nước trà."},{"group":"K","item":"Thần kinh","finding":"Không cứng gáy, không dấu thần kinh khu trú, không phù gai thị."}],"investigations":[{"name":"Khí máu, lactate, điện giải đồ, đường huyết","duration_minutes":10,"result":"pH 7,29, lactate 6,5 mmol/L, natri 136, kali 5,6 mmol/L, đường huyết 4,2 mmol/L."},{"name":"CK, creatinin, men gan, chức năng gan thận","duration_minutes":10,"result":"CK 28 500 U/L; creatinin 190 µmol/L; ALT 420 U/L; AST 560 U/L."},{"name":"Đông máu toàn bộ, công thức máu","duration_minutes":10,"result":"INR 1,6; tiểu cầu 90 G/L; fibrinogen 1,4 g/L."},{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Dương tính huyết sắc tố nhưng ít hồng cầu (gợi ý myoglobin niệu)."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Nhịp xoang nhanh 138 lần/phút, T cao nhọn nhẹ."},{"name":"Chọc dò dịch não tủy ngay trước khi hạ nhiệt","duration_minutes":10,"result":"Chậm hạ nhiệt, không chỉ định ở người có bệnh cảnh say nóng rõ."},{"name":"Cấy máu và cấy đờm thường quy trước làm mát","duration_minutes":10,"result":"Không làm chậm làm mát; chỉ làm khi nghi nhiễm khuẩn rõ."}],"choices":{"diagnosis":{"ydx":["Viêm màng não do vi khuẩn","Hội chứng ác tính do thuốc an thần","Say nóng do gắng sức (sốc nhiệt) kèm tiêu cơ vân và suy đa cơ quan","Sốc nhiễm khuẩn"]},"actions":["Cho paracetamol hoặc aspirin liều cao để hạ nhiệt","Chờ chụp CT sọ và chọc dò dịch não tủy trước khi làm mát","Lập hai đường truyền, bù dịch đẳng trương (NaCl 0,9% hoặc Ringer lactate) từng đợt 500 mL đến 1 L, theo dõi huyết áp, nước tiểu","Đặt thông tiểu, theo dõi lượng nước tiểu, mục tiêu trên 1 đến 2 mL/kg/giờ","Chườm mát ở trán, nách trong phòng nóng chờ xe","Truyền nhanh 5 lít dịch trong vài giờ không theo dõi","Kiểm tra đường huyết, kali, calci, CK; điều trị tăng kali nếu có thay đổi điện tâm đồ","Hội chẩn hồi sức, theo dõi men gan, đông máu, chức năng thận; chuẩn bị lọc máu nếu suy thận nặng","Bảo đảm đường thở, oxy, monitor tim; đặt nội khí quản nếu Glasgow dưới 9 hoặc không bảo vệ đường thở","Cắt cơn co giật bằng benzodiazepin (diazepam 10 mg tĩnh mạch, lặp lại theo đáp ứng)","Làm mát tích cực ngay: cởi quần áo, ngâm nước lạnh 1 đến 15 độ C hoặc đắp khăn ướt đá, quạt phun sương; theo dõi nhiệt độ hậu môn"]}}'::jsonb,
  '6b18363e04236a62a123d5a162d3723995a09cd88a164bf76933a6a8ff85aa13'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-cap-cuu-105',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-105","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-105-1","resource_type":"other","source":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí say nóng, say nắng (hồi sức cấp cứu); số quyết định và năm ban hành xin đối chiếu.","title":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí say nóng, say nắng (hồi sức cấp cứu); số quyết định và năm ban hành xin đối chiếu.","organization":null,"year_version":null,"citation":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí say nóng, say nắng (hồi sức cấp cứu); số quyết định và năm ban hành xin đối chiếu.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-heatstroke-epstein-2019","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/31216400/","title":"Epstein Y, Yanovich R. Heatstroke. N Engl J Med 2019;380:2449-2459.","organization":null,"year_version":null,"citation":"Epstein Y, Yanovich R. Heatstroke. N Engl J Med 2019;380:2449-2459.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-heat-nata-2015","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/26381473/","title":"Casa DJ et al. National Athletic Trainers'' Association position statement: exertional heat illnesses. J Athl Train 2015;50:986-1000.","organization":null,"year_version":null,"citation":"Casa DJ et al. National Athletic Trainers'' Association position statement: exertional heat illnesses. J Athl Train 2015;50:986-1000.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-heat-acsm-2007","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/17473783/","title":"Armstrong LE et al. American College of Sports Medicine position stand: exertional heat illness during training and competition. Med Sci Sports Exerc 2007;39:556-572.","organization":null,"year_version":null,"citation":"Armstrong LE et al. American College of Sports Medicine position stand: exertional heat illness during training and competition. Med Sci Sports Exerc 2007;39:556-572.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2,4],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm màng não do vi khuẩn","credit":"none"},{"text":"Sốc nhiễm khuẩn","credit":"none"},{"text":"Hội chứng ác tính do thuốc an thần","credit":"none"},{"text":"Say nóng do gắng sức (sốc nhiệt) kèm tiêu cơ vân và suy đa cơ quan","credit":"full"}]},"action_options":[{"text":"Làm mát tích cực ngay: cởi quần áo, ngâm nước lạnh 1 đến 15 độ C hoặc đắp khăn ướt đá, quạt phun sương; theo dõi nhiệt độ hậu môn","time_minutes":2,"grade":"critical","rationale":"Thời gian nhiệt độ trên 40 độ C quyết định tổn thương cơ quan; nguyên tắc làm mát trước, vận chuyển sau."},{"text":"Bảo đảm đường thở, oxy, monitor tim; đặt nội khí quản nếu Glasgow dưới 9 hoặc không bảo vệ đường thở","time_minutes":3,"grade":"critical","rationale":"Mê và kích động làm nguy cơ hít sặc; cần bảo vệ đường thở."},{"text":"Lập hai đường truyền, bù dịch đẳng trương (NaCl 0,9% hoặc Ringer lactate) từng đợt 500 mL đến 1 L, theo dõi huyết áp, nước tiểu","time_minutes":5,"grade":"critical","rationale":"Tụt huyết áp do mất nước và giãn mạch; tránh quá tải dịch vì tổn thương tim phổi."},{"text":"Đặt thông tiểu, theo dõi lượng nước tiểu, mục tiêu trên 1 đến 2 mL/kg/giờ","time_minutes":10,"grade":"critical","rationale":"Tiêu cơ vân và suy thận cấp; cần duy trì dòng nước tiểu."},{"text":"Cắt cơn co giật bằng benzodiazepin (diazepam 10 mg tĩnh mạch, lặp lại theo đáp ứng)","time_minutes":3,"grade":"recommended","rationale":"Co giật và run lạnh tăng sinh nhiệt; benzodiazepin cũng giảm run khi làm mát."},{"text":"Kiểm tra đường huyết, kali, calci, CK; điều trị tăng kali nếu có thay đổi điện tâm đồ","time_minutes":10,"grade":"recommended","rationale":"Tiêu cơ vân gây tăng kali, toan chuyển hóa, hạ calci."},{"text":"Hội chẩn hồi sức, theo dõi men gan, đông máu, chức năng thận; chuẩn bị lọc máu nếu suy thận nặng","time_minutes":20,"grade":"recommended","rationale":"Say nóng có thể gây suy gan, đông máu nội mạch rải rác và suy thận."},{"text":"Chườm mát ở trán, nách trong phòng nóng chờ xe","time_minutes":0,"grade":"waste","rationale":"Làm mát chậm, không đủ để hạ nhiệt trung tâm."},{"text":"Cho paracetamol hoặc aspirin liều cao để hạ nhiệt","time_minutes":0,"grade":"harmful","rationale":"Không hiệu quả vì điều hòa nhiệt đã hỏng; làm nặng tổn thương gan."},{"text":"Chờ chụp CT sọ và chọc dò dịch não tủy trước khi làm mát","time_minutes":0,"grade":"harmful","rationale":"Trì hoãn làm mát gây tăng tổn thương đa cơ quan."},{"text":"Truyền nhanh 5 lít dịch trong vài giờ không theo dõi","time_minutes":0,"grade":"harmful","rationale":"Nguy cơ phù phổi, quá tải dịch, rối loạn điện giải nặng thêm."}],"teaching_explanation":"Say nóng (sốc nhiệt) là cấp cứu: nhiệt độ trung tâm trên 40 độ C kèm rối loạn thần kinh. Làm mát nhanh bằng ngâm nước lạnh là điều trị quyết định; thuốc hạ sốt không có tác dụng."}'::jsonb,
  'af5587c9d89173dfacdaa6104066af530d318cb0bcec3c09d255a82e81473003'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-cap-cuu-106',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-106","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Trẻ 6 tuổi được vớt khỏi ao, ho bọt hồng, thở nhanh, tím tái","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":6,"sex":"nam","patient_label":"Cháu N. G. K."},"presentation":{"intro":"Phòng cấp cứu. Cháu K., 6 tuổi, cân nặng 20 kg, được người nhà vớt lên khỏi ao sau khoảng 5 phút chìm. Người nhà đã dốc ngược cháu và ép bụng khoảng 3 phút rồi đưa đến viện. Nay cháu ho, khạc bọt hồng, thở nhanh, môi tím, lơ mơ.","place":null,"clock":null,"night":false},"vitals":{"hr":148,"sbp":84,"dbp":50,"rr":42,"temperature_c":34.9,"spo2":84},"history":[{"question":"Chìm trong nước bao lâu, loại nước nào?","response":"Khoảng 5 phút, trong ao nước ngọt sau nhà."},{"question":"Khi vớt lên cháu có thở, có tỉnh không? Có hô hấp nhân tạo, ép tim không?","response":"Lúc vớt tím tái, thở yếu nấc, người nhà thổi ngạt vài lần, không ép tim; sau khi dốc ngược cháu nôn nước và ho."},{"question":"Đã xử trí gì trước khi đến viện?","response":"Dốc ngược, ép bụng khoảng 3 phút, thay quần áo ướt bằng khăn."},{"question":"Có chấn thương khi ngã hay nhảy xuống nước không?","response":"Cháu trượt chân ngã xuống ao, không đập đầu hay cổ theo lời người nhà."},{"question":"Triệu chứng sau khi vớt?","response":"Ho nhiều, khạc bọt hồng, thở nhanh, lơ mơ, rét run."},{"question":"Tiền sử bệnh tim, hen, động kinh, dị ứng?","response":"Không bệnh nền, không dị ứng."},{"question":"Cháu có ăn uống gì trước đó không?","response":"Ăn trưa cách 2 giờ."}],"examination":[{"group":"K","item":"Hô hấp","finding":"Thở nhanh 42 lần/phút, co kéo hõm ức, ran ẩm hai phổi, ho bọt hồng, SpO2 84% khí phòng."},{"group":"K","item":"Tri giác","finding":"Lơ mơ, Glasgow 11, đáp ứng khi gọi, không dấu thần kinh khu trú."},{"group":"K","item":"Tuần hoàn","finding":"Mạch nhanh 148 lần/phút, huyết áp 84/50 mmHg, chi lạnh, môi tím."},{"group":"K","item":"Nhiệt độ và da","finding":"Nhiệt độ 34,9 độ C, da lạnh ẩm."},{"group":"K","item":"Cột sống cổ và chấn thương","finding":"Không đau cổ, không bầm tím đầu mặt, không vết thương."},{"group":"K","item":"Bụng","finding":"Chướng nhẹ, mềm, không dấu hiệu chấn thương."}],"investigations":[{"name":"Khí máu động mạch và lactate (lấy sau khi cho oxy)","duration_minutes":10,"result":"pH 7,22, PaCO2 50 mmHg, PaO2 52 mmHg (khí phòng), HCO3 17 mmol/L, lactate 5,0 mmol/L."},{"name":"X-quang ngực thẳng","duration_minutes":10,"result":"Thâm nhiễm lan tỏa hai phế trường dạng phù phổi, tim không to."},{"name":"Đường huyết, điện giải đồ, creatinin","duration_minutes":10,"result":"Đường huyết 6,8 mmol/L; natri 138, kali 4,2 mmol/L; creatinin bình thường."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Nhịp xoang nhanh, không loạn nhịp."},{"name":"Công thức máu, CRP","duration_minutes":10,"result":"Bạch cầu 14 G/L, CRP bình thường."},{"name":"CT cột sống cổ toàn bộ thường quy","duration_minutes":40,"result":"Không có cơ chế chấn thương, khám cổ không đau, không chỉ định."},{"name":"Cấy dịch tỵ hầu và nước ao thường quy khi cấp cứu","duration_minutes":10,"result":"Không thay đổi xử trí cấp cứu."}],"choices":{"diagnosis":{"ydx":["Cơn hen cấp nặng","Phù phổi do tim","Suy hô hấp cấp do đuối nước (phù phổi do hít nước), hạ nhiệt nhẹ","Viêm phổi cộng đồng nặng"]},"actions":["Bảo đảm đường thở, thở oxy 100% qua mặt nạ túi dự trữ; hỗ trợ thông khí bằng bóng mặt nạ nếu thở yếu","Bắt đầu bằng ép tim đơn thuần mà không thông khí, hoặc cố ý bỏ thổi ngạt","Dốc ngược hoặc ép bụng để tháo nước ra khỏi phổi","Cởi bỏ quần áo ướt, lau khô, ủ ấm bằng chăn ấm, lò sưởi, dịch ấm","Gắn monitor tim và SpO2, lập đường truyền tĩnh mạch, lấy khí máu và điện giải","Đặt nội khí quản thở máy với PEEP hoặc CPAP khi SpO2 dưới khoảng 90% dù đã thở oxy lưu lượng cao hoặc tri giác xấu","Nhập hồi sức, theo dõi ít nhất 4 đến 8 giờ ngay cả khi tỉnh táo","Bù dịch đẳng trương NaCl 0,9% 10 mL/kg (200 mL) bolus, đánh giá lại tưới máu, tránh quá tải","Cho uống nước đường hoặc ăn khi đang lơ mơ và suy hô hấp","Dùng kháng sinh phổ rộng và corticoid dự phòng thường quy","Đặt sonde dạ dày hút hơi và dịch","Chụp X-quang ngực, điện tâm đồ; khí dung salbutamol nếu có khò khè"]}}'::jsonb,
  'd8b175803044bbce30cc2817aa56c4b349883f307d658b2fd66964905f8b396f'
)
