values (
  'noi-cap-cuu-106',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-106","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-106-1","resource_type":"other","source":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí đuối nước (hồi sức cấp cứu); số quyết định và năm ban hành xin đối chiếu.","title":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí đuối nước (hồi sức cấp cứu); số quyết định và năm ban hành xin đối chiếu.","organization":null,"year_version":null,"citation":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí đuối nước (hồi sức cấp cứu); số quyết định và năm ban hành xin đối chiếu.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-106-2","resource_type":"other","source":"American Heart Association. 2020 Guidelines for CPR and Emergency Cardiovascular Care: Part 3, Special circumstances (drowning).","title":"American Heart Association. 2020 Guidelines for CPR and Emergency Cardiovascular Care: Part 3, Special circumstances (drowning).","organization":null,"year_version":null,"citation":"American Heart Association. 2020 Guidelines for CPR and Emergency Cardiovascular Care: Part 3, Special circumstances (drowning).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-drowning-szpilman-2012","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/22646632/","title":"Szpilman D, Bierens JJLM, Handley AJ, Orlowski JP. Drowning. N Engl J Med 2012;366:2102-2110.","organization":null,"year_version":null,"citation":"Szpilman D, Bierens JJLM, Handley AJ, Orlowski JP. Drowning. N Engl J Med 2012;366:2102-2110.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-106-4","resource_type":"other","source":"World Health Organization. Preventing drowning: an implementation guide, 2017.","title":"World Health Organization. Preventing drowning: an implementation guide, 2017.","organization":null,"year_version":null,"citation":"World Health Organization. Preventing drowning: an implementation guide, 2017.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm phổi cộng đồng nặng","credit":"none"},{"text":"Cơn hen cấp nặng","credit":"none"},{"text":"Phù phổi do tim","credit":"none"},{"text":"Suy hô hấp cấp do đuối nước (phù phổi do hít nước), hạ nhiệt nhẹ","credit":"full"}]},"action_options":[{"text":"Bảo đảm đường thở, thở oxy 100% qua mặt nạ túi dự trữ; hỗ trợ thông khí bằng bóng mặt nạ nếu thở yếu","time_minutes":1,"grade":"critical","rationale":"Thiếu oxy là cơ chế chính gây tổn thương trong đuối nước nên thông khí và oxy ưu tiên số một."},{"text":"Đặt nội khí quản thở máy với PEEP hoặc CPAP khi SpO2 dưới khoảng 90% dù đã thở oxy lưu lượng cao hoặc tri giác xấu","time_minutes":3,"grade":"critical","rationale":"Phù phổi do hít nước và mất surfactant làm xẹp phế nang, cần PEEP."},{"text":"Cởi bỏ quần áo ướt, lau khô, ủ ấm bằng chăn ấm, lò sưởi, dịch ấm","time_minutes":2,"grade":"critical","rationale":"Nhiệt độ 34,9 độ C; hạ nhiệt làm nặng thêm rối loạn đông máu và nhịp tim."},{"text":"Gắn monitor tim và SpO2, lập đường truyền tĩnh mạch, lấy khí máu và điện giải","time_minutes":3,"grade":"critical","rationale":"Theo dõi nguy cơ loạn nhịp và suy hô hấp."},{"text":"Bù dịch đẳng trương NaCl 0,9% 10 mL/kg (200 mL) bolus, đánh giá lại tưới máu, tránh quá tải","time_minutes":5,"grade":"critical","rationale":"Huyết áp thấp do giảm thể tích tương đối; cần thận trọng với phù phổi."},{"text":"Đặt sonde dạ dày hút hơi và dịch","time_minutes":5,"grade":"recommended","rationale":"Trẻ nuốt nhiều nước và hơi, dễ trào ngược gây hít sặc."},{"text":"Chụp X-quang ngực, điện tâm đồ; khí dung salbutamol nếu có khò khè","time_minutes":10,"grade":"recommended","rationale":"Đánh giá phù phổi, loạn nhịp; co thắt phế quản do kích thích."},{"text":"Nhập hồi sức, theo dõi ít nhất 4 đến 8 giờ ngay cả khi tỉnh táo","time_minutes":20,"grade":"recommended","rationale":"Tổn thương phổi có thể diễn tiến chậm."},{"text":"Dốc ngược hoặc ép bụng để tháo nước ra khỏi phổi","time_minutes":0,"grade":"harmful","rationale":"Không tháo được nước đã vào phổi, gây nôn trào, hít sặc, làm chậm hồi sức."},{"text":"Bắt đầu bằng ép tim đơn thuần mà không thông khí, hoặc cố ý bỏ thổi ngạt","time_minutes":0,"grade":"harmful","rationale":"Đuối nước là ngừng tim do thiếu oxy, nên thông khí đi trước."},{"text":"Dùng kháng sinh phổ rộng và corticoid dự phòng thường quy","time_minutes":0,"grade":"harmful","rationale":"Không có bằng chứng lợi ích khi không có nhiễm trùng; cần thận trọng."},{"text":"Cho uống nước đường hoặc ăn khi đang lơ mơ và suy hô hấp","time_minutes":0,"grade":"harmful","rationale":"Nguy cơ hít sặc."}],"teaching_explanation":"Đuối nước gây tổn thương chủ yếu do thiếu oxy: hồi sức bắt đầu bằng thông khí và oxy, ủ ấm; không dốc ngược hay ép bụng. Phù phổi do hít nước cần PEEP khi không đạt oxy."}'::jsonb,
  '1beba2c278934a909178541b14f13f3114f2fb7a2c6bb296110119122d1b032d'
)
