values (
  'noi-cap-cuu-107',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-107","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Mờ mắt như nhìn qua sương, thở sâu sau uống rượu nấu lậu","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":41,"sex":"nam","patient_label":"Ông H. V. B."},"presentation":{"intro":"Phòng cấp cứu. Ông B. đến viện vào buổi trưa vì mờ mắt, buồn nôn, đau bụng và thở sâu. Tối hôm trước ông cùng hai người bạn uống khoảng 300 mL rượu nấu lậu mua ở vỉa hè; một người bạn đã được đưa vào viện khác với triệu chứng tương tự. Cân nặng 65 kg.","place":null,"clock":null,"night":false},"vitals":{"hr":112,"sbp":108,"dbp":66,"rr":34,"temperature_c":36.8,"spo2":98},"history":[{"question":"Uống loại rượu gì, bao nhiêu, lúc nào?","response":"Rượu nấu lậu không nhãn, khoảng 300 mL cách khoảng 14 giờ; hai người bạn cùng uống."},{"question":"Có rối loạn thị giác không?","response":"Mờ mắt như nhìn qua sương mù hay tuyết rơi, chói sáng, thị lực giảm dần từ sáng."},{"question":"Triệu chứng toàn thân khác?","response":"Đau đầu, buồn nôn, nôn, đau bụng thượng vị, thở sâu và nhanh, mệt."},{"question":"Có uống thêm thuốc hay hóa chất nào khác không?","response":"Không."},{"question":"Có say rượu rõ lúc uống không? Triệu chứng xuất hiện sau bao lâu?","response":"Hơi say nhẹ lúc uống, ngủ được; sáng dậy mới mờ mắt và khó thở."},{"question":"Tiền sử bệnh gan thận, đái tháo đường, dùng rượu thường xuyên?","response":"Uống rượu thỉnh thoảng; không bệnh gan thận, không đái tháo đường."},{"question":"Dị ứng thuốc?","response":"Không."}],"examination":[{"group":"K","item":"Hô hấp và thăng bằng kiềm toan","finding":"Thở sâu nhanh kiểu Kussmaul, phổi không ran."},{"group":"K","item":"Mắt","finding":"Đồng tử giãn 5 mm, phản xạ ánh sáng chậm, thị lực đếm ngón tay 1 m, soi đáy mắt phù gai thị hai bên."},{"group":"K","item":"Thần kinh","finding":"Tỉnh, trả lời chậm, Glasgow 14, không liệt khu trú, không cứng gáy."},{"group":"K","item":"Bụng","finding":"Đau thượng vị khi ấn, bụng mềm, không phản ứng thành bụng."},{"group":"K","item":"Tuần hoàn","finding":"Mạch nhanh, huyết áp 108/66, chi ấm."}],"investigations":[{"name":"Khí máu động mạch, lactate","duration_minutes":10,"result":"pH 7,08; PaCO2 22 mmHg; HCO3 7 mmol/L; lactate 4,1 mmol/L."},{"name":"Điện giải đồ, urê, creatinin, đường huyết, tính khoảng trống anion","duration_minutes":10,"result":"Na 140, K 4,4, Cl 100 mmol/L; khoảng trống anion 33; urê 6 mmol/L; đường huyết 5,2 mmol/L; creatinin 98 µmol/L."},{"name":"Áp lực thẩm thấu máu đo và tính khoảng trống thẩm thấu","duration_minutes":10,"result":"Osm đo 342 mOsm/kg, Osm tính khoảng 291; khoảng trống thẩm thấu khoảng 51."},{"name":"Methanol máu (gửi mẫu, không chờ kết quả để giải độc)","duration_minutes":10,"result":"Gửi mẫu; kết quả vài giờ đến vài ngày; thực tế 62 mg/dL."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Nhịp xoang nhanh, QT bình thường."},{"name":"Men gan, amylase, lipase","duration_minutes":10,"result":"Amylase tăng nhẹ, men gan bình thường."},{"name":"Điện não đồ khẩn","duration_minutes":10,"result":"Không thay đổi xử trí cấp cứu."},{"name":"MRI sọ não khẩn trước khi điều trị giải độc","duration_minutes":10,"result":"Chậm giải độc; tổn thương nhân bèo sẫm màu chỉ có ý nghĩa chẩn đoán muộn."}],"choices":{"diagnosis":{"ydx":["Ngộ độc salicylate","Ngộ độc methanol cấp với toan chuyển hóa tăng khoảng trống anion và tổn thương thị thần kinh","Ngộ độc rượu ethanol cấp","Nhiễm toan ceton đái tháo đường"]},"actions":["Chỉ truyền glucose 5% và dịch nuôi dưỡng mà không giải độc","Giải độc đặc hiệu ngay: fomepizole 15 mg/kg tĩnh mạch, hoặc ethanol 10% truyền duy trì nồng độ ethanol máu 100 đến 150 mg/dL nếu không có fomepizole","Chờ kết quả methanol máu rồi mới giải độc","Đánh giá ABC, gắn monitor, lập đường truyền, lấy khí máu, điện giải, đo áp lực thẩm thấu","Acid folic 50 mg tĩnh mạch mỗi 4 giờ (hoặc folinic) để tăng chuyển formate thành CO2","Hội chẩn mắt, hồi sức, độc chất; theo dõi thị lực, đường huyết, kali, calci","Truyền natri bicarbonat tĩnh mạch 1 đến 2 mmol/kg để đưa pH trên 7,3, lặp lại theo khí máu","Chuẩn bị chạy thận nhân tạo sớm; chỉ định khi toan nặng, tổn thương thị lực, nồng độ methanol cao hoặc suy thận","Dùng than hoạt","Tìm và báo cáo nạn nhân khác cùng uống; xử lý nguồn rượu","Gây nôn hoặc rửa dạ dày để loại chất độc"]}}'::jsonb,
  'fd7a68c59afdc0cdfd2ec14aa4dad5428dc769e348e85a201f96c98c8c024c8a'
)
