insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-cap-cuu-107',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-107","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-107-1","resource_type":"other","source":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí ngộ độc cấp (ngộ độc methanol); số quyết định và năm ban hành xin đối chiếu.","title":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí ngộ độc cấp (ngộ độc methanol); số quyết định và năm ban hành xin đối chiếu.","organization":null,"year_version":null,"citation":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và xử trí ngộ độc cấp (ngộ độc methanol); số quyết định và năm ban hành xin đối chiếu.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-methanol-aact-2002","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/12216995/","title":"Barceloux DG et al. American Academy of Clinical Toxicology practice guidelines on the treatment of methanol poisoning. J Toxicol Clin Toxicol 2002;40:415-446.","organization":null,"year_version":null,"citation":"Barceloux DG et al. American Academy of Clinical Toxicology practice guidelines on the treatment of methanol poisoning. J Toxicol Clin Toxicol 2002;40:415-446.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-methanol-ectr-2015","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/25493973/","title":"Roberts DM et al. Recommendations for the role of extracorporeal treatments in the management of acute methanol poisoning: a systematic review and consensus statement (EXTRIP). Crit Care Med 2015;43:461-472.","organization":null,"year_version":null,"citation":"Roberts DM et al. Recommendations for the role of extracorporeal treatments in the management of acute methanol poisoning: a systematic review and consensus statement (EXTRIP). Crit Care Med 2015;43:461-472.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-toxic-alcohols-kraut-2018","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/29342392/","title":"Kraut JA, Mullins ME. Toxic alcohols. N Engl J Med 2018;378:270-280.","organization":null,"year_version":null,"citation":"Kraut JA, Mullins ME. Toxic alcohols. N Engl J Med 2018;378:270-280.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,4,5],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"neutral"},{"index":6,"role":"waste"},{"index":7,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Nhiễm toan ceton đái tháo đường","credit":"none"},{"text":"Ngộ độc rượu ethanol cấp","credit":"none"},{"text":"Ngộ độc salicylate","credit":"none"},{"text":"Ngộ độc methanol cấp với toan chuyển hóa tăng khoảng trống anion và tổn thương thị thần kinh","credit":"full"}]},"action_options":[{"text":"Đánh giá ABC, gắn monitor, lập đường truyền, lấy khí máu, điện giải, đo áp lực thẩm thấu","time_minutes":3,"grade":"critical","rationale":"Toan chuyển hóa nặng, nhịp thở bù trừ; xét nghiệm xác định khoảng trống anion và khoảng trống thẩm thấu."},{"text":"Truyền natri bicarbonat tĩnh mạch 1 đến 2 mmol/kg để đưa pH trên 7,3, lặp lại theo khí máu","time_minutes":5,"grade":"critical","rationale":"Toan làm tăng thấm formate vào mô và nặng thêm độc tính."},{"text":"Giải độc đặc hiệu ngay: fomepizole 15 mg/kg tĩnh mạch, hoặc ethanol 10% truyền duy trì nồng độ ethanol máu 100 đến 150 mg/dL nếu không có fomepizole","time_minutes":10,"grade":"critical","rationale":"Ngăn alcohol dehydrogenase chuyển methanol thành formaldehyd và formate; không chờ kết quả methanol máu."},{"text":"Chuẩn bị chạy thận nhân tạo sớm; chỉ định khi toan nặng, tổn thương thị lực, nồng độ methanol cao hoặc suy thận","time_minutes":20,"grade":"critical","rationale":"Thận nhân tạo lấy methanol và formate khỏi máu."},{"text":"Acid folic 50 mg tĩnh mạch mỗi 4 giờ (hoặc folinic) để tăng chuyển formate thành CO2","time_minutes":5,"grade":"critical","rationale":"Tăng đào thải formate, giảm độc tính."},{"text":"Hội chẩn mắt, hồi sức, độc chất; theo dõi thị lực, đường huyết, kali, calci","time_minutes":20,"grade":"recommended","rationale":"Theo dõi tổn thương thị thần kinh và rối loạn điện giải."},{"text":"Tìm và báo cáo nạn nhân khác cùng uống; xử lý nguồn rượu","time_minutes":30,"grade":"recommended","rationale":"Có nhiều người bị ngộ độc cộng đồng."},{"text":"Dùng than hoạt","time_minutes":3,"grade":"waste","rationale":"Than hoạt không gắn tốt rượu nhỏ phân tử như methanol."},{"text":"Gây nôn hoặc rửa dạ dày để loại chất độc","time_minutes":0,"grade":"harmful","rationale":"Đã quá muộn (14 giờ), không hiệu quả; nguy cơ hít sặc."},{"text":"Chờ kết quả methanol máu rồi mới giải độc","time_minutes":0,"grade":"harmful","rationale":"Chậm trễ gây mất thị lực vĩnh viễn và tử vong; chẩn đoán dựa khoảng trống anion và thẩm thấu."},{"text":"Chỉ truyền glucose 5% và dịch nuôi dưỡng mà không giải độc","time_minutes":0,"grade":"harmful","rationale":"Không ngăn được chuyển hóa độc tố, toan nặng hơn."}],"teaching_explanation":"Nghi ngộ độc methanol khi uống rượu không rõ nguồn, mờ mắt, toan chuyển hóa nặng với khoảng trống anion và thẩm thấu cao. Không chờ định lượng methanol: bicarbonat, fomepizole hoặc ethanol, acid folic và chạy thận nhân tạo sớm."}'::jsonb,
  'f86661bc283734d1acc90651f49b01275c8c26e6a36e141f61fdbedcabf3a4e2'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-cap-cuu-108',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-108","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Lơ mơ, nói lảm nhảm ở người xơ gan rượu, run vẩy tay","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":58,"sex":"nam","patient_label":"Ông Đ. V. S."},"presentation":{"intro":"Phòng cấp cứu. Vợ đưa ông S. đến vì ba ngày nay ông ngủ ngày, thức đêm, nay lơ mơ, nói lảm nhảm. Ông xơ gan rượu đã hai năm, cổ trướng, đang dùng furosemid và spironolacton; mấy ngày gần đây tăng liều, ăn kém và táo bón bốn ngày.","place":null,"clock":null,"night":false},"vitals":{"hr":98,"sbp":100,"dbp":60,"rr":22,"temperature_c":37.4,"spo2":96},"history":[{"question":"Triệu chứng thay đổi ý thức diễn ra thế nào?","response":"Ba ngày nay đảo ngược nhịp ngủ, hay quên, nay lơ mơ nói lảm nhảm."},{"question":"Gần đây dùng thuốc gì, có tăng liều lợi tiểu, thuốc an thần?","response":"Tự tăng furosemid 80 mg và spironolacton 200 mg mỗi ngày; không dùng thuốc ngủ, an thần."},{"question":"Đại tiện, tiêu chảy hay táo bón?","response":"Táo bón bốn ngày, không có phân đen, không đi ngoài ra máu."},{"question":"Có nôn máu, đi ngoài phân đen không?","response":"Không."},{"question":"Có sốt, đau bụng, ho, tiểu buốt không?","response":"Không sốt, bụng căng nhiều hơn nhưng không đau; không ho."},{"question":"Uống rượu gần đây không? Tiền sử xơ gan?","response":"Đã bỏ rượu một năm nay; xơ gan rượu, từng nằm viện vì cổ trướng."},{"question":"Có té ngã, chấn thương đầu gần đây không?","response":"Không."}],"examination":[{"group":"K","item":"Tri giác và thần kinh","finding":"Li bì, đáp ứng lời gọi, lảm nhảm, mất định hướng rõ, run vẩy hai bàn tay (flapping), không dấu thần kinh khu trú."},{"group":"K","item":"Da niêm và dấu hiệu bệnh gan","finding":"Vàng da, vàng mắt, sao mạch, lòng bàn tay son, hơi thở mùi gan."},{"group":"K","item":"Bụng","finding":"Cổ trướng mức độ vừa, bụng không đau, không phản ứng thành bụng."},{"group":"K","item":"Dấu mất nước","finding":"Niêm khô, nếp véo da giảm, huyết áp thấp ranh giới."},{"group":"K","item":"Tim phổi","finding":"Tim nhanh nhẹ, phổi trong."}],"investigations":[{"name":"Đường huyết mao mạch tại giường","duration_minutes":10,"result":"4,2 mmol/L."},{"name":"Điện giải đồ, creatinin, urê","duration_minutes":10,"result":"Natri 127, kali 2,9 mmol/L; creatinin 118 µmol/L (nền 80), urê 11 mmol/L."},{"name":"Công thức máu, bilirubin, albumin, INR","duration_minutes":10,"result":"Hb 102 g/L; tiểu cầu 70 G/L; bilirubin 98 µmol/L; albumin 22 g/L; INR 2,1."},{"name":"Chọc dò dịch cổ trướng chẩn đoán (đếm tế bào, cấy)","duration_minutes":10,"result":"Bạch cầu đa nhân 90/mm3 (dưới 250); loại trừ viêm phúc mạc nhiễm khuẩn tự phát."},{"name":"Amoniac máu","duration_minutes":10,"result":"Amoniac tĩnh mạch 148 µmol/L; không cần để quyết định điều trị."},{"name":"CT sọ không cản quang","duration_minutes":40,"result":"Không xuất huyết nội sọ, không phù não rõ."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Nhịp xoang nhanh nhẹ, QT bình thường, T dẹt do hạ kali."},{"name":"Lặp lại amoniac máu mỗi 6 giờ để chỉnh liều lactulose","duration_minutes":10,"result":"Không có giá trị chỉ đạo điều trị; theo dõi lâm sàng và số lần đi ngoài."},{"name":"Sinh thiết gan qua da khẩn","duration_minutes":10,"result":"Chống chỉ định khi INR cao, cổ trướng; không thay đổi điều trị cấp."}],"choices":{"diagnosis":{"ydx":["Hạ đường huyết nặng","Bệnh não gan độ III (West Haven) do xơ gan, yếu tố khởi phát là lợi tiểu liều cao, hạ kali và táo bón","Viêm phúc mạc nhiễm khuẩn tự phát","Xuất huyết não"]},"actions":["Nhịn đạm hoàn toàn nhiều ngày","Cho lactulose 25 mL qua đường uống hoặc sonde mỗi 1 đến 2 giờ đến khi đi ngoài mềm; thụt tháo lactulose 300 mL pha trong 1 lít nước nếu không uống được","Dinh dưỡng đủ đạm 1,2 đến 1,5 g/kg/ngày, chia nhiều bữa, bao gồm bữa tối muộn","Tìm và loại trừ yếu tố khởi phát khác: xuất huyết tiêu hóa, nhiễm trùng, thuốc an thần; chọc dịch cổ trướng chẩn đoán","Bù natri chậm: không tăng quá 8 mmol/L trong 24 giờ","Ngưng lợi tiểu, bù kali tĩnh mạch an toàn theo điện giải và monitor, mục tiêu kali từ 3,5 mmol/L","Đánh giá ABC, tư thế nằm nghiêng an toàn, kiểm tra đường huyết mao mạch, gắn monitor, theo dõi Glasgow; chuẩn bị đặt nội khí quản nếu Glasgow dưới 9","Tiếp tục furosemid, spironolacton liều cao và truyền NaCl 3% nhanh để nâng natri","Tiêm diazepam hoặc morphin để trấn tĩnh khi kích động","Thêm rifaximin 550 mg uống hai lần mỗi ngày sau khi đã dùng lactulose","Truyền albumin 1 g/kg trong 2 ngày khi nghi tổn thương thận do lợi tiểu và nền xơ gan"]}}'::jsonb,
  'ccf7ffb1ab972ab325469aae736a2130724f4152d3c929f0b3eb9ad6c52c2f47'
)
on conflict (case_id) do update set
