values (
  'noi-cap-cuu-108',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-108","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-108-1","resource_type":"other","source":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và điều trị xơ gan và biến chứng (bệnh não gan); số quyết định và năm ban hành xin đối chiếu.","title":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và điều trị xơ gan và biến chứng (bệnh não gan); số quyết định và năm ban hành xin đối chiếu.","organization":null,"year_version":null,"citation":"Bộ Y tế Việt Nam. Hướng dẫn chẩn đoán và điều trị xơ gan và biến chứng (bệnh não gan); số quyết định và năm ban hành xin đối chiếu.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-he-aasld-2014","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/25042402/","title":"Vilstrup H et al. Hepatic encephalopathy in chronic liver disease: 2014 practice guideline by AASLD and EASL. Hepatology 2014;60:715-735.","organization":null,"year_version":null,"citation":"Vilstrup H et al. Hepatic encephalopathy in chronic liver disease: 2014 practice guideline by AASLD and EASL. Hepatology 2014;60:715-735.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-108-3","resource_type":"other","source":"European Association for the Study of the Liver. EASL Clinical Practice Guidelines for the management of patients with decompensated cirrhosis. J Hepatol 2018;69:406-460.","title":"European Association for the Study of the Liver. EASL Clinical Practice Guidelines for the management of patients with decompensated cirrhosis. J Hepatol 2018;69:406-460.","organization":null,"year_version":null,"citation":"European Association for the Study of the Liver. EASL Clinical Practice Guidelines for the management of patients with decompensated cirrhosis. J Hepatol 2018;69:406-460.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-108-4","resource_type":"other","source":"Ferenci P et al. Hepatic encephalopathy: definition, nomenclature, diagnosis, and quantification: final report of the working party at the 11th World Congresses of Gastroenterology, Vienna, 1998. Hepatology 2002;35:716-721.","title":"Ferenci P et al. Hepatic encephalopathy: definition, nomenclature, diagnosis, and quantification: final report of the working party at the 11th World Congresses of Gastroenterology, Vienna, 1998. Hepatology 2002;35:716-721.","organization":null,"year_version":null,"citation":"Ferenci P et al. Hepatic encephalopathy: definition, nomenclature, diagnosis, and quantification: final report of the working party at the 11th World Congresses of Gastroenterology, Vienna, 1998. Hepatology 2002;35:716-721.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"neutral"},{"index":6,"role":"neutral"},{"index":7,"role":"waste"},{"index":8,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Hạ đường huyết nặng","credit":"none"},{"text":"Bệnh não gan độ III (West Haven) do xơ gan, yếu tố khởi phát là lợi tiểu liều cao, hạ kali và táo bón","credit":"full"},{"text":"Xuất huyết não","credit":"none"},{"text":"Viêm phúc mạc nhiễm khuẩn tự phát","credit":"none"}]},"action_options":[{"text":"Đánh giá ABC, tư thế nằm nghiêng an toàn, kiểm tra đường huyết mao mạch, gắn monitor, theo dõi Glasgow; chuẩn bị đặt nội khí quản nếu Glasgow dưới 9","time_minutes":2,"grade":"critical","rationale":"Độ III có nguy cơ hít sặc; hạ đường huyết là nguyên nhân phải loại trừ ngay."},{"text":"Cho lactulose 25 mL qua đường uống hoặc sonde mỗi 1 đến 2 giờ đến khi đi ngoài mềm; thụt tháo lactulose 300 mL pha trong 1 lít nước nếu không uống được","time_minutes":5,"grade":"critical","rationale":"Lactulose là nền tảng điều trị, giảm hấp thu amoniac và dọn sạch ruột."},{"text":"Ngưng lợi tiểu, bù kali tĩnh mạch an toàn theo điện giải và monitor, mục tiêu kali từ 3,5 mmol/L","time_minutes":10,"grade":"critical","rationale":"Hạ kali làm tăng sinh amoniac ở thận; lợi tiểu liều cao là yếu tố khởi phát."},{"text":"Bù natri chậm: không tăng quá 8 mmol/L trong 24 giờ","time_minutes":10,"grade":"critical","rationale":"Nâng natri nhanh gây hủy myelin thẩm thấu."},{"text":"Truyền albumin 1 g/kg trong 2 ngày khi nghi tổn thương thận do lợi tiểu và nền xơ gan","time_minutes":20,"grade":"recommended","rationale":"Giảm nguy cơ hội chứng gan thận và thể tích tuần hoàn hiệu quả thấp."},{"text":"Thêm rifaximin 550 mg uống hai lần mỗi ngày sau khi đã dùng lactulose","time_minutes":10,"grade":"recommended","rationale":"Giảm tái phát bệnh não gan."},{"text":"Dinh dưỡng đủ đạm 1,2 đến 1,5 g/kg/ngày, chia nhiều bữa, bao gồm bữa tối muộn","time_minutes":30,"grade":"recommended","rationale":"Hạn chế đạm làm mất cơ, nặng thêm bệnh não gan."},{"text":"Tìm và loại trừ yếu tố khởi phát khác: xuất huyết tiêu hóa, nhiễm trùng, thuốc an thần; chọc dịch cổ trướng chẩn đoán","time_minutes":20,"grade":"recommended","rationale":"Bệnh não gan nặng luôn có yếu tố khởi phát cần tìm."},{"text":"Tiêm diazepam hoặc morphin để trấn tĩnh khi kích động","time_minutes":0,"grade":"harmful","rationale":"Làm nặng thêm ức chế thần kinh trung ương và che lấp diễn tiến."},{"text":"Nhịn đạm hoàn toàn nhiều ngày","time_minutes":0,"grade":"harmful","rationale":"Không có lợi ích; gây dị hóa cơ và làm nặng bệnh não gan."},{"text":"Tiếp tục furosemid, spironolacton liều cao và truyền NaCl 3% nhanh để nâng natri","time_minutes":0,"grade":"harmful","rationale":"Hạ kali, hạ natri, suy thận và hủy myelin thẩm thấu."}],"teaching_explanation":"Bệnh não gan ở người xơ gan thường có yếu tố khởi phát: lợi tiểu, hạ kali, táo bón, xuất huyết, nhiễm trùng. Điều trị là tìm và sửa yếu tố khởi phát, lactulose đến đi ngoài mềm; amoniac máu không dùng để chẩn đoán hay chỉnh điều trị; tránh an thần và nhịn đạm."}'::jsonb,
  '6452172ecd2160428536f6064a6d5967acfd7ddf3290b727256806130ff1e507'
)
