insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-cap-cuu-001',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Dao còn cắm ở ngực phải, khó thở và tụt huyết áp","setting":"capcuu","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":28,"sex":"nam","patient_label":"Anh T. V. N."},"presentation":{"intro":"Phòng cấp cứu, 22 giờ. Nam thanh niên bị đâm bằng dao 25 phút trước, cán dao còn nhô ra ở thành ngực phải. Anh khó thở, da lạnh. Ca mô phỏng, mọi thông tin là giả định.","place":null,"clock":null,"night":false},"vitals":{"hr":118,"sbp":92,"dbp":58,"rr":28,"temperature_c":36.8,"spo2":91},"history":[{"question":"Bị đâm lúc nào, bằng gì, có bị nơi khác không?","response":"Cách đây 25 phút, một nhát dao ở ngực phải. Em không bị đâm chỗ khác. Dao vẫn còn cắm ở đó."},{"question":"Khó thở thế nào, có ho ra máu không?","response":"Thở không đủ hơi, đau nhói khi hít sâu. Có ho vài lần ra ít máu bọt."},{"question":"Có choáng váng, vã mồ hôi, sắp ngất không?","response":"Chóng mặt, lạnh người, thấy muốn xỉu."},{"question":"Sau khi bị đâm có ai động vào dao không? Máu mất nhiều không?","response":"Người nhà giữ nguyên dao, chỉ lấy khăn ép quanh dao. Máu chảy ít ngoài da."},{"question":"Tiền sử bệnh, dị ứng, thuốc đang dùng?","response":"Khỏe mạnh, không dị ứng thuốc, không dùng thuốc gì."},{"question":"Ăn uống lần cuối, có uống rượu không?","response":"Ăn tối cách đây 3 giờ, có uống vài lon bia."},{"question":"Tiêm phòng uốn ván lần cuối?","response":"Không nhớ đã tiêm lúc nào."},{"question":"Nghề nghiệp, hoàn cảnh bị đâm?","response":"Cãi vã sau bữa nhậu, bị người quen đâm."}],"examination":[{"group":"K","item":"Đường thở và giọng nói","finding":"Nói được từng câu ngắn, không tiếng rít, không máu trong miệng."},{"group":"K","item":"Lồng ngực","finding":"Dao cắm ở khoảng liên sườn 6, đường nách giữa phải, cán dao nghiêng nhẹ lên trên. Lồng ngực phải di động kém, không có tiếng sủi khí qua vết thương."},{"group":"K","item":"Gõ và nghe phổi","finding":"Phổi phải gõ đục vùng thấp, rì rào phế nang giảm rõ nửa dưới. Phổi trái bình thường."},{"group":"K","item":"Khí quản và tĩnh mạch cổ","finding":"Khí quản ở giữa, tĩnh mạch cổ xẹp."},{"group":"K","item":"Tuần hoàn ngoại vi","finding":"Da lạnh, nhợt, mạch quay nhanh nhẹ, thời gian làm đầy mao mạch 3 giây."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, không phản ứng thành bụng, không có vết thương khác."},{"group":"K","item":"Khám lưng và các vùng bị che khuất sau khi lăn trục","finding":"Không có vết thương phía sau lưng, cột sống không đau."},{"group":"K","item":"Thần kinh","finding":"GCS 15, đồng tử hai bên đều."}],"investigations":[{"name":"Siêu âm eFAST tại giường","duration_minutes":15,"result":"Dịch trong khoang màng phổi phải, mất trượt màng phổi phải nhẹ; khoang màng tim và ổ bụng không có dịch."},{"name":"X quang ngực thẳng tại giường (vẫn để nguyên dao)","duration_minutes":10,"result":"Mờ góc sườn hoành phải, mức khí-dịch nhỏ. Bóng tim không to. Đầu dao nằm trong vùng nền phổi phải."},{"name":"Công thức máu, nhóm máu, thử chéo máu, đông máu","duration_minutes":10,"result":"Hb 12,1 g/dL, tiểu cầu 238 G/L, INR 1,1. Nhóm máu đã có, đã chéo 4 đơn vị."},{"name":"Khí máu động mạch và lactate","duration_minutes":10,"result":"pH 7,31; PaO2 62 mmHg (thở oxy qua mặt nạ); BE -5; lactate 3,2 mmol/L."},{"name":"Điện tim và troponin","duration_minutes":10,"result":"Nhịp nhanh xoang 118 lần/phút, không bất thường ST. Troponin bình thường."},{"name":"CT ngực bụng có cản quang trước khi xử trí","duration_minutes":40,"result":"Không nên làm khi huyết động chưa ổn định và còn nghi chảy máu lớn trong ngực."},{"name":"Ure, creatinin, điện giải đồ","duration_minutes":10,"result":"Trong giới hạn bình thường."}],"choices":{"diagnosis":{"ydx":["Vết thương thấu bụng có tổn thương tạng đặc","Tràn khí màng phổi áp lực đơn thuần, không mất máu","Tràn dịch màng ngoài tim chèn ép tim","Vết thương thấu ngực phải do dao, tràn máu tràn khí màng phổi kèm sốc mất máu độ III"]},"actions":["Tiêm vắc xin và globulin miễn dịch uốn ván, cho kháng sinh dự phòng cefazolin tĩnh mạch","Đặt 2 đường truyền tĩnh mạch ngoại vi cỡ lớn, lấy máu xét nghiệm và gọi máu","Cố định cán dao bằng gạc dày và băng dính hoặc băng ép, lăn trục khám lưng","Làm eFAST và X quang ngực tại giường mà không rút dao","Cho thở oxy lưu lượng cao qua mặt nạ có túi dự trữ, theo dõi SpO2 và monitor liên tục","Hội chẩn khẩn phẫu thuật lồng ngực, chuẩn bị phòng mổ và đưa người bệnh đi mổ khi đủ chỉ định","Rút dao ra khỏi ngực ngay tại phòng cấp cứu để dễ khám","Băng kín bốn cạnh toàn bộ quanh vết thương rồi hỏi bệnh tiếp","Giảm đau tĩnh mạch liều nhỏ chia nhỏ, theo dõi hô hấp","Đặt ống dẫn lưu màng phổi phải ở khoang liên sườn 4-5 trước đường nách giữa, không đặt qua vết thương","Chuyển đi chụp CT ngực bụng khi còn sốc","Truyền dịch tinh thể ấm thận trọng 1 L, chuyển sang truyền máu theo tỉ lệ khi cần, tránh hạ huyết áp quá thấp"]}}'::jsonb,
  '2da62ed8895fccf7e9de52a0bc876dda2582c43ae7971f6c56a3b092b48543e2'
)
on conflict (case_id) do update set
