values (
  'ngoai-cap-cuu-001',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-001-1","resource_type":"other","source":"ATLS 10th Edition (American College of Surgeons), Chapter 4: Thoracic Trauma, 2018","title":"ATLS 10th Edition (American College of Surgeons), Chapter 4: Thoracic Trauma, 2018","organization":null,"year_version":null,"citation":"ATLS 10th Edition (American College of Surgeons), Chapter 4: Thoracic Trauma, 2018","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-001-2","resource_type":"other","source":"Hướng dẫn quy trình cấp cứu chấn thương ngực của Bộ Y tế Việt Nam (tên hướng dẫn; số quyết định xem can_doi_chieu)","title":"Hướng dẫn quy trình cấp cứu chấn thương ngực của Bộ Y tế Việt Nam (tên hướng dẫn; số quyết định xem can_doi_chieu)","organization":null,"year_version":null,"citation":"Hướng dẫn quy trình cấp cứu chấn thương ngực của Bộ Y tế Việt Nam (tên hướng dẫn; số quyết định xem can_doi_chieu)","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-001-3","resource_type":"other","source":"EAST Practice Management Guidelines: Penetrating thoracic trauma, nhóm tác giả EAST","title":"EAST Practice Management Guidelines: Penetrating thoracic trauma, nhóm tác giả EAST","organization":null,"year_version":null,"citation":"EAST Practice Management Guidelines: Penetrating thoracic trauma, nhóm tác giả EAST","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3,4,5,6],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"},{"index":6,"role":"neutral"}],"diagnosis_options":{"ydx":[{"text":"Vết thương thấu bụng có tổn thương tạng đặc","credit":"none"},{"text":"Tràn khí màng phổi áp lực đơn thuần, không mất máu","credit":"none"},{"text":"Vết thương thấu ngực phải do dao, tràn máu tràn khí màng phổi kèm sốc mất máu độ III","credit":"full"},{"text":"Tràn dịch màng ngoài tim chèn ép tim","credit":"none"}]},"action_options":[{"text":"Cho thở oxy lưu lượng cao qua mặt nạ có túi dự trữ, theo dõi SpO2 và monitor liên tục","time_minutes":1,"grade":"critical","rationale":"Đường thở thông nhưng SpO2 91%, cần oxy ngay trong đánh giá A, B."},{"text":"Đặt 2 đường truyền tĩnh mạch ngoại vi cỡ lớn, lấy máu xét nghiệm và gọi máu","time_minutes":2,"grade":"critical","rationale":"Sốc mất máu độ III cần đường truyền lớn và máu sớm."},{"text":"Đặt ống dẫn lưu màng phổi phải ở khoang liên sườn 4-5 trước đường nách giữa, không đặt qua vết thương","time_minutes":5,"grade":"critical","rationale":"Giải phóng máu khí, đánh giá lượng máu mất để quyết định mở ngực."},{"text":"Truyền dịch tinh thể ấm thận trọng 1 L, chuyển sang truyền máu theo tỉ lệ khi cần, tránh hạ huyết áp quá thấp","time_minutes":5,"grade":"critical","rationale":"Hồi sức giảm thể tích có kiểm soát, tránh pha loãng và hạ thân nhiệt."},{"text":"Làm eFAST và X quang ngực tại giường mà không rút dao","time_minutes":5,"grade":"critical","rationale":"Tìm tràn máu, tràn khí và loại trừ tràn máu màng tim."},{"text":"Cố định cán dao bằng gạc dày và băng dính hoặc băng ép, lăn trục khám lưng","time_minutes":2,"grade":"recommended","rationale":"Vật đâm xuyên được giữ nguyên, tránh dịch chuyển gây tổn thương thêm."},{"text":"Giảm đau tĩnh mạch liều nhỏ chia nhỏ, theo dõi hô hấp","time_minutes":3,"grade":"recommended","rationale":"Đau làm thở nông thêm nhưng phải tránh ức chế hô hấp và hạ huyết áp."},{"text":"Tiêm vắc xin và globulin miễn dịch uốn ván, cho kháng sinh dự phòng cefazolin tĩnh mạch","time_minutes":5,"grade":"recommended","rationale":"Vết thương xuyên thấu bẩn, chưa rõ tiền sử tiêm uốn ván."},{"text":"Hội chẩn khẩn phẫu thuật lồng ngực, chuẩn bị phòng mổ và đưa người bệnh đi mổ khi đủ chỉ định","time_minutes":5,"grade":"recommended","rationale":"Chảy máu liên tục trong ngực cần can thiệp phẫu thuật cầm máu."},{"text":"Rút dao ra khỏi ngực ngay tại phòng cấp cứu để dễ khám","time_minutes":1,"grade":"harmful","rationale":"Dao có thể đang chèn một mạch máu, rút ra gây chảy máu ồ ạt không kiểm soát được."},{"text":"Chuyển đi chụp CT ngực bụng khi còn sốc","time_minutes":40,"grade":"harmful","rationale":"Làm chậm cầm máu, người bệnh có thể ngừng tim ở phòng CT."},{"text":"Băng kín bốn cạnh toàn bộ quanh vết thương rồi hỏi bệnh tiếp","time_minutes":1,"grade":"harmful","rationale":"Không phải vết thương hở hút khí; băng kín mà không có dẫn lưu có thể gây tràn khí áp lực, nên chỉ cố định dao."}],"teaching_explanation":"Vật đâm xuyên còn trong cơ thể phải được cố định, không rút ngoài phòng mổ. Sốc mất máu do tràn máu màng phổi cần dẫn lưu sớm, hồi sức giảm thể tích có kiểm soát và quyết định mổ dựa vào lượng máu ra, không chờ CT."}'::jsonb,
  'ce88e299ef0916a64d8c3cbd2de93efcda2a9f9a13be3e9bca901662192897b7'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-cap-cuu-002',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-002","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Khó thở đột ngột sau đặt catheter tĩnh mạch dưới đòn","setting":"capcuu","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":62,"sex":"nam","patient_label":"Ông L. V. K."},"presentation":{"intro":"Khoa Hồi sức ngoại. Ông có COPD, đang nằm viện vì viêm phổi, vừa được đặt catheter tĩnh mạch dưới đòn phải 20 phút. Ông đột ngột khó thở dữ dội, vã mồ hôi. Ca mô phỏng, mọi thông tin là giả định.","place":null,"clock":null,"night":false},"vitals":{"hr":132,"sbp":78,"dbp":46,"rr":36,"temperature_c":37.4,"spo2":82},"history":[{"question":"Triệu chứng bắt đầu khi nào và thế nào?","response":"Vừa sau khi đặt ống truyền ở cổ ngực phải, đột ngột thấy tức ngực phải và hụt hơi."},{"question":"Đau ngực kiểu gì, lan đi đâu?","response":"Đau nhói ngực phải, tăng khi thở, hơi lan lên vai phải."},{"question":"Có ho ra máu, đau chân, sốt mới không?","response":"Không ho ra máu, chân không đau, không sốt mới."},{"question":"Tiền sử bệnh phổi và hút thuốc?","response":"COPD nhiều năm, hút thuốc gần 40 gói-năm, hay khó thở khi gắng sức."},{"question":"Đang dùng thuốc gì, có dị ứng không?","response":"Thuốc xịt giãn phế quản và kháng sinh tĩnh mạch. Không dị ứng thuốc."},{"question":"Lần đặt catheter có khó khăn, chọc kim mấy lần?","response":"Bác sĩ chọc ba lần mới vào."},{"question":"Có đang dùng thuốc chống đông không?","response":"Không dùng chống đông."},{"question":"Tiền sử gia đình có ai bị bệnh phổi tương tự không?","response":"Không ai."}],"examination":[{"group":"K","item":"Quan sát đường thở và tri giác","finding":"Vật vã, thở nhanh nông, nói được từng từ, còn tỉnh."},{"group":"K","item":"Tĩnh mạch cổ và khí quản","finding":"Tĩnh mạch cổ nổi căng, khí quản lệch sang trái."},{"group":"K","item":"Gõ và nghe phổi","finding":"Lồng ngực phải căng, di động kém, gõ vang như trống, mất rì rào phế nang bên phải."},{"group":"K","item":"Tuần hoàn","finding":"Mạch nhanh, nhẹ, huyết áp tụt, đầu chi lạnh."},{"group":"K","item":"Tại vị trí đặt catheter","finding":"Catheter dưới đòn phải còn đúng vị trí, không có tụ máu lớn, không phù nề thành ngực."},{"group":"K","item":"Khám chi dưới","finding":"Hai cẳng chân không sưng, không đau khi bóp bắp chân."},{"group":"K","item":"Tim","finding":"Tiếng tim xa xăm do thành ngực căng, không có tiếng thổi."}],"investigations":[{"name":"X quang ngực thẳng tại giường (chỉ làm sau khi đã giải áp)","duration_minutes":10,"result":"Phổi phải xẹp, tăng sáng toàn bộ, trung thất đẩy sang trái, đầu catheter nằm trong tĩnh mạch chủ trên."},{"name":"Khí máu động mạch","duration_minutes":10,"result":"pH 7,19; PaCO2 78 mmHg; PaO2 49 mmHg; lactate 4,2 mmol/L."},{"name":"Siêu âm phổi tại giường","duration_minutes":15,"result":"Mất dấu trượt màng phổi bên phải, có điểm phổi."},{"name":"Điện tim","duration_minutes":10,"result":"Nhịp nhanh xoang 132 lần/phút, không thiếu máu cơ tim cấp."},{"name":"Chờ phim X quang ngực rồi mới quyết định giải áp","duration_minutes":10,"result":"Chẩn đoán tràn khí áp lực là chẩn đoán lâm sàng, chờ phim làm chậm cứu sống."},{"name":"Chụp cắt lớp mạch phổi tìm thuyên tắc","duration_minutes":10,"result":"Không có chỉ định lúc này vì đã có hội chứng tràn khí màng phổi rõ."}],"choices":{"diagnosis":{"ydx":["Tràn khí màng phổi áp lực phải do biến chứng đặt catheter dưới đòn, trên nền COPD","Cơn kịch phát COPD đơn thuần","Nhồi máu cơ tim cấp","Thuyên tắc phổi lớn"]},"actions":["Giảm đau bằng thuốc phù hợp, tránh ức chế hô hấp","Chụp CT mạch phổi khi người bệnh chưa ổn định","Khí máu động mạch, theo dõi tăng CO2 và cân nhắc thở không xâm nhập khi ổn","Thở máy áp lực dương mà chưa giải áp","Truyền dịch tinh thể nhỏ giọt có kiểm soát đến khi huyết áp phục hồi","Giải áp bằng kim 14G, dài 8 cm, chọc khoang liên sườn 5 đường nách trước phải","Nhận định tràn khí áp lực trên lâm sàng và gọi hỗ trợ khẩn","X quang ngực sau dẫn lưu để xác nhận phổi nở và vị trí catheter","Oxy lưu lượng cao, theo dõi monitor, 2 đường truyền","Đặt ống dẫn lưu màng phổi phải, nối hệ thống một chiều dưới nước","Chờ chụp X quang ngực rồi mới giải áp","Theo dõi dẫn lưu, báo bác sĩ đặt catheter, ghi nhận biến chứng thủ thuật"]}}'::jsonb,
  '4cad5fd6da52af0c55898196f369ec915390d269575a8efd53e0d49d99a2cb82'
)
