insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'ngoai-cap-cuu-002',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-002","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-002-1","resource_type":"other","source":"ATLS 10th Edition (American College of Surgeons), Chapter 4: Thoracic Trauma, 2018","title":"ATLS 10th Edition (American College of Surgeons), Chapter 4: Thoracic Trauma, 2018","organization":null,"year_version":null,"citation":"ATLS 10th Edition (American College of Surgeons), Chapter 4: Thoracic Trauma, 2018","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-002-2","resource_type":"other","source":"BTS Pleural Disease Guideline 2010 (Thorax 2010; 65 Suppl 2)","title":"BTS Pleural Disease Guideline 2010 (Thorax 2010; 65 Suppl 2)","organization":null,"year_version":null,"citation":"BTS Pleural Disease Guideline 2010 (Thorax 2010; 65 Suppl 2)","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-002-3","resource_type":"other","source":"Hướng dẫn quy trình kỹ thuật dẫn lưu màng phổi và xử trí tràn khí màng phổi của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu)","title":"Hướng dẫn quy trình kỹ thuật dẫn lưu màng phổi và xử trí tràn khí màng phổi của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu)","organization":null,"year_version":null,"citation":"Hướng dẫn quy trình kỹ thuật dẫn lưu màng phổi và xử trí tràn khí màng phổi của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu)","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Nhồi máu cơ tim cấp","credit":"none"},{"text":"Cơn kịch phát COPD đơn thuần","credit":"none"},{"text":"Tràn khí màng phổi áp lực phải do biến chứng đặt catheter dưới đòn, trên nền COPD","credit":"full"},{"text":"Thuyên tắc phổi lớn","credit":"none"}]},"action_options":[{"text":"Nhận định tràn khí áp lực trên lâm sàng và gọi hỗ trợ khẩn","time_minutes":1,"grade":"critical","rationale":"Tĩnh mạch cổ nổi, khí quản lệch, phổi phải gõ vang là đủ để chẩn đoán."},{"text":"Giải áp bằng kim 14G, dài 8 cm, chọc khoang liên sườn 5 đường nách trước phải","time_minutes":2,"grade":"critical","rationale":"Cứu sống, chuyển tràn khí áp lực thành tràn khí đơn giản."},{"text":"Đặt ống dẫn lưu màng phổi phải, nối hệ thống một chiều dưới nước","time_minutes":8,"grade":"critical","rationale":"Điều trị xác định sau giải áp, kim dễ tắc hoặc tụt."},{"text":"Oxy lưu lượng cao, theo dõi monitor, 2 đường truyền","time_minutes":2,"grade":"critical","rationale":"Nâng oxy hóa máu và chuẩn bị hồi sức."},{"text":"Truyền dịch tinh thể nhỏ giọt có kiểm soát đến khi huyết áp phục hồi","time_minutes":3,"grade":"critical","rationale":"Hạ huyết áp do giảm tuần hoàn về tim và sẽ cải thiện sau giải áp."},{"text":"X quang ngực sau dẫn lưu để xác nhận phổi nở và vị trí catheter","time_minutes":10,"grade":"recommended","rationale":"Đánh giá hiệu quả dẫn lưu, kiểm tra đầu catheter tĩnh mạch dưới đòn."},{"text":"Khí máu động mạch, theo dõi tăng CO2 và cân nhắc thở không xâm nhập khi ổn","time_minutes":10,"grade":"recommended","rationale":"Nền COPD dễ ứ CO2, cần hỗ trợ thông khí có điều chỉnh."},{"text":"Theo dõi dẫn lưu, báo bác sĩ đặt catheter, ghi nhận biến chứng thủ thuật","time_minutes":5,"grade":"recommended","rationale":"Biến chứng thủ thuật cần được rút kinh nghiệm và chuẩn bị đường truyền thay thế."},{"text":"Giảm đau bằng thuốc phù hợp, tránh ức chế hô hấp","time_minutes":3,"grade":"recommended","rationale":"Đau làm hạn chế thông khí ở người COPD."},{"text":"Chờ chụp X quang ngực rồi mới giải áp","time_minutes":25,"grade":"harmful","rationale":"Chậm trễ gây ngừng tim; tràn khí áp lực là chẩn đoán lâm sàng."},{"text":"Thở máy áp lực dương mà chưa giải áp","time_minutes":5,"grade":"harmful","rationale":"Áp lực dương làm tràn khí tăng nhanh, gây ngừng tim."},{"text":"Chụp CT mạch phổi khi người bệnh chưa ổn định","time_minutes":50,"grade":"harmful","rationale":"Mất thời gian vô ích và rời khỏi vị trí hồi sức khi đang suy sụp huyết động."}],"teaching_explanation":"Tràn khí màng phổi áp lực là chẩn đoán lâm sàng và phải giải áp ngay, không chờ X quang. Thở máy áp lực dương hoặc di chuyển bệnh nhân đi chụp khi chưa giải áp có thể gây ngừng tim."}'::jsonb,
  'bcdb1eb3f06cd8bf300cdfe203c41172d6614067fee7fa081326257e8eaf6889'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-cap-cuu-003',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-003","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Gãy hàm mặt do tai nạn, máu đầy miệng, thở rít","setting":"capcuu","level":"Khó","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":31,"sex":"nam","patient_label":"Anh P. Q. H."},"presentation":{"intro":"Phòng cấp cứu, 18 giờ 30. Anh đi xe máy không đội mũ bảo hiểm, ngã đập mặt xuống đường 40 phút trước. Mặt biến dạng, máu đầy miệng, thở có tiếng rít. Ca mô phỏng, mọi thông tin là giả định.","place":null,"clock":null,"night":false},"vitals":{"hr":124,"sbp":104,"dbp":64,"rr":30,"temperature_c":36.6,"spo2":87},"history":[{"question":"Tai nạn xảy ra thế nào, có mất ý thức không?","response":"Em ngã xe máy, mặt đập xuống đường, ngất vài phút rồi tỉnh."},{"question":"Có khó thở, nghẹn, sặc máu không?","response":"Máu chảy nhiều trong miệng, em hay ho sặc, nằm ngửa thì khó thở hơn."},{"question":"Có đau cổ, tê yếu tay chân không?","response":"Đau cổ hơi hơi, tay chân vẫn cử động được."},{"question":"Có chảy dịch trong từ mũi hay tai không?","response":"Mũi chảy nước hồng nhạt loãng."},{"question":"Răng có gãy, có nuốt phải mảnh răng không?","response":"Răng cửa gãy mấy cái, không biết có nuốt không."},{"question":"Tiền sử bệnh, dị ứng, thuốc đang dùng?","response":"Khỏe mạnh, không dị ứng thuốc."},{"question":"Ăn uống lần cuối?","response":"Ăn cơm trưa cách đây 6 giờ."},{"question":"Có uống rượu bia trước khi đi xe không?","response":"Có uống vài chai bia."}],"examination":[{"group":"K","item":"Đường thở","finding":"Thở rít khi hít vào, máu và nước bọt đọng ở hầu họng, lưỡi có xu hướng tụt ra sau khi nằm ngửa. Nói giọng ngậm nước."},{"group":"K","item":"Khám mặt","finding":"Mặt giữa phù nề, di động bất thường khi nắm hàm trên và kéo (dấu hiệu Le Fort). Cằm lún sâu, cắn hở trước."},{"group":"K","item":"Khám trong miệng","finding":"Rách niêm mạc sàn miệng, mảnh xương hàm dưới di lệch, nhiều răng cửa gãy, chảy máu từ vùng cằm."},{"group":"K","item":"Cột sống cổ","finding":"Ấn đau điểm giữa cổ, chưa có dấu hiệu thần kinh. Đã được nẹp cổ cứng."},{"group":"K","item":"Thần kinh","finding":"GCS 14 điểm (M6 V4 E4), đồng tử đều phản xạ tốt."},{"group":"K","item":"Ngực và bụng","finding":"Rì rào phế nang hai bên đều, bụng mềm."},{"group":"K","item":"Tuần hoàn","finding":"Mạch nhanh, da hơi nhợt, thời gian làm đầy mao mạch 3 giây."}],"investigations":[{"name":"Đo SpO2 liên tục, kiểm tra khí máu động mạch","duration_minutes":10,"result":"pH 7,28; PaCO2 52 mmHg; PaO2 58 mmHg (đang thở oxy mặt nạ)."},{"name":"Hút máu và dị vật hầu họng, quan sát đường thở","duration_minutes":10,"result":"Hút được máu cục và mảnh răng gãy."},{"name":"Công thức máu, nhóm máu, đông máu","duration_minutes":10,"result":"Hb 11,6 g/dL, tiểu cầu 210 G/L, INR 1,0."},{"name":"X quang cột sống cổ nghiêng và thẳng (làm sau khi kiểm soát đường thở)","duration_minutes":10,"result":"Không thấy gãy rõ trên phim thường; chưa loại trừ hoàn toàn tổn thương dây chằng."},{"name":"CT sọ mặt cột sống cổ (làm sau khi đường thở an toàn)","duration_minutes":40,"result":"Gãy Le Fort II hai bên, gãy hai bên cằm, gãy xương mũi sàng, tụ máu nhỏ ngoài màng cứng vùng trán 4 mm."},{"name":"Chụp CT mặt trước khi bảo đảm đường thở","duration_minutes":40,"result":"Không nên đưa người bệnh còn nguy cơ tắc đường thở đi chụp."},{"name":"Điện tim và men tim thường quy","duration_minutes":10,"result":"Nhịp nhanh xoang, không thiếu máu cơ tim."}],"choices":{"diagnosis":{"ydx":["Viêm thanh quản cấp","Dị vật đường thở thuần túy","Phản vệ độ III","Đa chấn thương hàm mặt (Le Fort II và gãy hàm dưới hai bên) gây tắc nghẽn đường thở trên, nghi chấn thương sọ não và cột sống cổ kèm theo"]},"actions":["Kháng sinh dự phòng (cefazolin hoặc amoxicillin-clavulanate), phòng uốn ván, giảm đau","Đặt nội khí quản qua mũi mù khi nghi gãy mặt giữa và nền sọ","Đưa đi chụp CT trước khi bảo đảm đường thở","Sau khi ổn định đường thở: CT sọ não mặt cột sống cổ","Chuẩn bị và thực hiện đặt nội khí quản đường miệng với gây mê nhanh, bảo vệ cột sống cổ; sẵn sàng mở màng nhẫn giáp","Hút máu và dị vật hầu họng, cho ngồi cúi nhẹ về trước nếu cột sống cho phép, giữ đầu trung tính","Cho nằm ngửa phẳng, bất động hàm, quan sát mà không hút","Ép cầm máu tại chỗ, nẹp cố định hàm tạm thời, chèn mũi sau trước nếu chảy máu mũi nhiều","Nâng hàm, kéo lưỡi ra trước, bất động cột sống cổ trục thẳng","Đặt 2 đường truyền tĩnh mạch, truyền dịch tinh thể có kiểm soát, lấy máu xét nghiệm","Oxy lưu lượng cao qua mặt nạ có túi dự trữ cho đến khi có đường thở xác định","Hội chẩn răng hàm mặt, tai mũi họng và phẫu thuật thần kinh"]}}'::jsonb,
  'd56ba9e17f88971b14e8638aaad48268cb5818c7453b42fe80c87af9c57a5461'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'ngoai-cap-cuu-003',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-003","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-003-1","resource_type":"other","source":"ATLS 10th Edition (American College of Surgeons), Chapter 2: Initial Assessment and Management; Chapter 3 và phụ lục Facial Trauma, 2018","title":"ATLS 10th Edition (American College of Surgeons), Chapter 2: Initial Assessment and Management; Chapter 3 và phụ lục Facial Trauma, 2018","organization":null,"year_version":null,"citation":"ATLS 10th Edition (American College of Surgeons), Chapter 2: Initial Assessment and Management; Chapter 3 và phụ lục Facial Trauma, 2018","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-airway-das-2015","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/26556848/","title":"Difficult Airway Society 2015 guidelines for management of unanticipated difficult intubation (Br J Anaesth 2015)","organization":null,"year_version":null,"citation":"Difficult Airway Society 2015 guidelines for management of unanticipated difficult intubation (Br J Anaesth 2015)","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-003-3","resource_type":"other","source":"Hướng dẫn quy trình cấp cứu chấn thương hàm mặt và kiểm soát đường thở của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu)","title":"Hướng dẫn quy trình cấp cứu chấn thương hàm mặt và kiểm soát đường thở của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu)","organization":null,"year_version":null,"citation":"Hướng dẫn quy trình cấp cứu chấn thương hàm mặt và kiểm soát đường thở của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu)","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,5,6],"examination_essential_indices":[0,1,2,3,4],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"essential"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm thanh quản cấp","credit":"none"},{"text":"Phản vệ độ III","credit":"none"},{"text":"Dị vật đường thở thuần túy","credit":"none"},{"text":"Đa chấn thương hàm mặt (Le Fort II và gãy hàm dưới hai bên) gây tắc nghẽn đường thở trên, nghi chấn thương sọ não và cột sống cổ kèm theo","credit":"full"}]},"action_options":[{"text":"Hút máu và dị vật hầu họng, cho ngồi cúi nhẹ về trước nếu cột sống cho phép, giữ đầu trung tính","time_minutes":2,"grade":"critical","rationale":"Làm thông đường thở tức thì và giảm sặc máu."},{"text":"Nâng hàm, kéo lưỡi ra trước, bất động cột sống cổ trục thẳng","time_minutes":1,"grade":"critical","rationale":"Mở thông đường thở khi lưỡi tụt do gãy cằm hai bên, bảo vệ cột sống cổ."},{"text":"Chuẩn bị và thực hiện đặt nội khí quản đường miệng với gây mê nhanh, bảo vệ cột sống cổ; sẵn sàng mở màng nhẫn giáp","time_minutes":8,"grade":"critical","rationale":"Đường thở xác định trước khi vận chuyển, tránh mặt giữa gãy khi đặt qua mũi."},{"text":"Oxy lưu lượng cao qua mặt nạ có túi dự trữ cho đến khi có đường thở xác định","time_minutes":1,"grade":"critical","rationale":"SpO2 87%, cần cải thiện oxy ngay."},{"text":"Đặt 2 đường truyền tĩnh mạch, truyền dịch tinh thể có kiểm soát, lấy máu xét nghiệm","time_minutes":3,"grade":"critical","rationale":"Phòng mất máu từ vùng mặt và cổ."},{"text":"Ép cầm máu tại chỗ, nẹp cố định hàm tạm thời, chèn mũi sau trước nếu chảy máu mũi nhiều","time_minutes":5,"grade":"recommended","rationale":"Kiểm soát chảy máu vùng mặt."},{"text":"Sau khi ổn định đường thở: CT sọ não mặt cột sống cổ","time_minutes":40,"grade":"recommended","rationale":"Đánh giá toàn bộ tổn thương xương và nội sọ."},{"text":"Kháng sinh dự phòng (cefazolin hoặc amoxicillin-clavulanate), phòng uốn ván, giảm đau","time_minutes":5,"grade":"recommended","rationale":"Gãy hở vào khoang miệng và xoang."},{"text":"Hội chẩn răng hàm mặt, tai mũi họng và phẫu thuật thần kinh","time_minutes":10,"grade":"recommended","rationale":"Đa chuyên khoa vì tụ máu ngoài màng cứng nhỏ và gãy mặt phức tạp."},{"text":"Đặt nội khí quản qua mũi mù khi nghi gãy mặt giữa và nền sọ","time_minutes":5,"grade":"harmful","rationale":"Ống có thể lọt vào nội sọ, gây nhiễm khuẩn và chấn thương thêm."},{"text":"Đưa đi chụp CT trước khi bảo đảm đường thở","time_minutes":45,"grade":"harmful","rationale":"Tắc nghẽn đường thở có thể xảy ra bất cứ lúc nào, người bệnh chết ở phòng CT."},{"text":"Cho nằm ngửa phẳng, bất động hàm, quan sát mà không hút","time_minutes":10,"grade":"harmful","rationale":"Lưỡi tụt và máu đọng làm tắc đường thở hoàn toàn."}],"teaching_explanation":"Ở chấn thương hàm mặt, đường thở được ưu tiên số một: hút, nâng hàm, bảo vệ cột sống cổ và kiểm soát đường thở xác định sớm, sẵn sàng mở màng nhẫn giáp. Không đặt nội khí quản qua mũi mù khi nghi gãy mặt giữa hoặc nền sọ, không đưa đi chụp trước khi đường thở an toàn."}'::jsonb,
  'efb1a735b976ca053acefd707e3be9854ee412e51aca12125ebb2679b6b66647'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-cap-cuu-004',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-004","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Vết cắt sâu đùi, máu phun thành tia","setting":"capcuu","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":34,"sex":"nam","patient_label":"Anh Đ. M. T."},"presentation":{"intro":"Phòng cấp cứu, 14 giờ. Công nhân lắp kính bị tấm kính vỡ cứa vào đùi trái 20 phút trước, máu phun thành tia, quần thấm đẫm máu. Ca mô phỏng, mọi thông tin là giả định.","place":null,"clock":null,"night":false},"vitals":{"hr":130,"sbp":82,"dbp":50,"rr":26,"temperature_c":36.2,"spo2":95},"history":[{"question":"Chấn thương xảy ra thế nào và lúc nào?","response":"Cách đây 20 phút, tấm kính vỡ cứa vào đùi trái, máu phun thành tia."},{"question":"Ước lượng mất bao nhiêu máu? Máu chảy liên tục hay ngắt quãng?","response":"Máu chảy ướt đẫm cả quần và vũng trên nền nhà, chảy thành tia theo nhịp tim."},{"question":"Đã sơ cứu thế nào?","response":"Đồng nghiệp lấy khăn ép nhưng máu vẫn thấm đẫm; chưa buộc garô."},{"question":"Có choáng váng, khát nước, tê chân không?","response":"Chóng mặt, khát nước, bàn chân lạnh và hơi tê."},{"question":"Có bệnh nền, dùng thuốc chống đông không?","response":"Không bệnh nền, không dùng chống đông."},{"question":"Dị ứng thuốc, tiêm uốn ván?","response":"Không dị ứng, tiêm uốn ván cách đây 3 năm."},{"question":"Ăn uống lần cuối?","response":"Ăn sáng 7 giờ."},{"question":"Còn đau chỗ nào khác không?","response":"Chỉ đau đùi trái."}],"examination":[{"group":"K","item":"Vết thương đùi trái","finding":"Vết rách 8 cm mặt trước trong đùi trái, máu phun thành tia sáng đỏ, ép tay chưa cầm được; khối tụ máu đang to lên."},{"group":"K","item":"Mạch ngoại vi chi trái","finding":"Mạch mu chân và chày sau trái không bắt được; mạch bên phải rõ."},{"group":"K","item":"Màu sắc, nhiệt độ, cảm giác chân trái","finding":"Bàn chân trái tái, lạnh, cảm giác giảm, cử động ngón còn."},{"group":"K","item":"Toàn thân","finding":"Vã mồ hôi, da nhợt, mạch nhanh nhẹ, tỉnh nhưng lo lắng."},{"group":"K","item":"Các vị trí tổn thương khác","finding":"Không có thêm thương tích đầu, ngực, bụng; xương đùi không gãy."},{"group":"K","item":"Thần kinh","finding":"GCS 15."},{"group":"K","item":"Tim phổi","finding":"Phổi thông khí tốt, tim nhanh đều."}],"investigations":[{"name":"Nhóm máu và thử chéo máu, công thức máu, đông máu","duration_minutes":10,"result":"Hb 10,2 g/dL, tiểu cầu 205 G/L, INR 1,1. Chuẩn bị 4 đơn vị hồng cầu lắng và huyết tương."},{"name":"Khí máu và lactate","duration_minutes":10,"result":"pH 7,29; BE -7; lactate 4,6 mmol/L."},{"name":"Siêu âm Doppler mạch đùi tại giường (nếu không làm chậm cầm máu)","duration_minutes":15,"result":"Gián đoạn dòng động mạch đùi nông trái tại vị trí vết cắt; huyết khối ít."},{"name":"X quang đùi","duration_minutes":10,"result":"Không có dị vật kim loại, không gãy xương; mảnh kính nhỏ trong phần mềm."},{"name":"Chụp cắt lớp mạch máu (CTA) chi trước khi cầm máu","duration_minutes":40,"result":"Không làm khi còn chảy máu ồ ạt và có dấu hiệu rõ tổn thương mạch."},{"name":"Điện tim và men tim","duration_minutes":10,"result":"Không có chỉ định ở bệnh nhân trẻ tuổi chảy máu ngoại."}],"choices":{"diagnosis":{"ydx":["Rách tĩnh mạch hiển nông đơn thuần","Gãy xương đùi hở","Vết thương động mạch đùi chi dưới trái chảy máu ồ ạt, sốc mất máu độ III, thiếu máu cấp chi dưới","Tụ máu phần mềm đơn thuần do dập cơ"]},"actions":["Hội chẩn khẩn phẫu thuật mạch máu và chuyển ngay phòng mổ","Đặt 2 đường truyền lớn, bắt đầu truyền máu và các chế phẩm sớm, tiêm acid tranexamic","Đặt garô cách mép vết thương 5-7 cm phía trên, siết đến khi hết chảy máu và mất mạch, ghi giờ đặt garô","Dùng kẹp cầm máu mò mẫm trong vết thương sâu đang chảy ồ ạt","Giảm đau tĩnh mạch, kháng sinh dự phòng và phòng uốn ván","Ghi nhận thời gian đặt garô, kiểm tra lại mạch và chảy máu sau khi garô","Chụp CT mạch trước khi cầm máu","Chuẩn bị rạch cân dự phòng hội chứng khoang sau tái thông","Nới garô định kỳ trong vài phút để máu lưu thông lại","Siêu âm Doppler tại giường chỉ khi chắc chắn không làm chậm đưa vào phòng mổ","Thở oxy, giữ ấm, theo dõi monitor","Ép trực tiếp mạnh bằng gạc dày và băng ép vào vết thương"]}}'::jsonb,
  '5bdd03fdc8da403bf51848058c66bab6f76c9be40168b4dc7e09fc21c8a2975c'
)
