values (
  'ngoai-cap-cuu-004',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-004","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-004-1","resource_type":"other","source":"ATLS 10th Edition (American College of Surgeons), Chapter 3: Shock, 2018","title":"ATLS 10th Edition (American College of Surgeons), Chapter 3: Shock, 2018","organization":null,"year_version":null,"citation":"ATLS 10th Edition (American College of Surgeons), Chapter 3: Shock, 2018","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-004-2","resource_type":"other","source":"Stop the Bleed / Hướng dẫn kiểm soát chảy máu ngoại của Hội Phẫu thuật Chấn thương Hoa Kỳ, 2015 (ACS Committee on Trauma)","title":"Stop the Bleed / Hướng dẫn kiểm soát chảy máu ngoại của Hội Phẫu thuật Chấn thương Hoa Kỳ, 2015 (ACS Committee on Trauma)","organization":null,"year_version":null,"citation":"Stop the Bleed / Hướng dẫn kiểm soát chảy máu ngoại của Hội Phẫu thuật Chấn thương Hoa Kỳ, 2015 (ACS Committee on Trauma)","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-004-3","resource_type":"other","source":"Hướng dẫn quy trình cấp cứu chấn thương chi và cầm máu của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu)","title":"Hướng dẫn quy trình cấp cứu chấn thương chi và cầm máu của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu)","organization":null,"year_version":null,"citation":"Hướng dẫn quy trình cấp cứu chấn thương chi và cầm máu của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu)","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Rách tĩnh mạch hiển nông đơn thuần","credit":"none"},{"text":"Gãy xương đùi hở","credit":"none"},{"text":"Tụ máu phần mềm đơn thuần do dập cơ","credit":"none"},{"text":"Vết thương động mạch đùi chi dưới trái chảy máu ồ ạt, sốc mất máu độ III, thiếu máu cấp chi dưới","credit":"full"}]},"action_options":[{"text":"Ép trực tiếp mạnh bằng gạc dày và băng ép vào vết thương","time_minutes":1,"grade":"critical","rationale":"Bước đầu tiên để cầm máu, dùng cả bàn tay khi cần."},{"text":"Đặt garô cách mép vết thương 5-7 cm phía trên, siết đến khi hết chảy máu và mất mạch, ghi giờ đặt garô","time_minutes":2,"grade":"critical","rationale":"Ép không đủ khi chảy máu động mạch lớn ở đùi; garô cứu sống."},{"text":"Đặt 2 đường truyền lớn, bắt đầu truyền máu và các chế phẩm sớm, tiêm acid tranexamic","time_minutes":5,"grade":"critical","rationale":"Sốc mất máu độ III; hạn chế dịch tinh thể để tránh pha loãng."},{"text":"Thở oxy, giữ ấm, theo dõi monitor","time_minutes":2,"grade":"critical","rationale":"Giảm thiếu oxy và hạ thân nhiệt, góp phần rối loạn đông máu."},{"text":"Giảm đau tĩnh mạch, kháng sinh dự phòng và phòng uốn ván","time_minutes":5,"grade":"critical","rationale":"Vết thương do kính có nguy cơ nhiễm trùng."},{"text":"Hội chẩn khẩn phẫu thuật mạch máu và chuyển ngay phòng mổ","time_minutes":10,"grade":"recommended","rationale":"Thiếu máu chi do mất liên tục động mạch đùi cần phục hồi trong vài giờ."},{"text":"Siêu âm Doppler tại giường chỉ khi chắc chắn không làm chậm đưa vào phòng mổ","time_minutes":10,"grade":"recommended","rationale":"Có thể giúp xác định vị trí tổn thương nhưng không bắt buộc khi đã có dấu hiệu rõ."},{"text":"Ghi nhận thời gian đặt garô, kiểm tra lại mạch và chảy máu sau khi garô","time_minutes":1,"grade":"recommended","rationale":"Theo dõi hiệu quả và thời gian thiếu máu."},{"text":"Chuẩn bị rạch cân dự phòng hội chứng khoang sau tái thông","time_minutes":10,"grade":"recommended","rationale":"Tái tưới máu sau thiếu máu kéo dài nguy cơ cao hội chứng khoang."},{"text":"Dùng kẹp cầm máu mò mẫm trong vết thương sâu đang chảy ồ ạt","time_minutes":3,"grade":"harmful","rationale":"Có thể tổn thương thêm thần kinh và tĩnh mạch kề cận, mất thời gian."},{"text":"Nới garô định kỳ trong vài phút để máu lưu thông lại","time_minutes":3,"grade":"harmful","rationale":"Gây chảy máu lại, mất máu thêm và đẩy chất chuyển hóa độc vào tuần hoàn."},{"text":"Chụp CT mạch trước khi cầm máu","time_minutes":45,"grade":"harmful","rationale":"Chậm cầm máu ở người đã sốc."}],"teaching_explanation":"Chảy máu chi đe dọa tính mạng được xử trí theo X trong ABCDE: ép trực tiếp, garô sớm, hồi sức cân bằng và chuyển phẫu thuật mạch khẩn cấp. Dấu hiệu rõ tổn thương mạch (chảy máu phun tia, mất mạch) là chỉ định thăm dò phẫu thuật, không chờ chụp mạch."}'::jsonb,
  '60fbdc1a531fec84cf802cc9f95d22765322fe09ad0debb3c8aa49eced11dbcc'
)
