insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-cap-cuu-005',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-005","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau dữ dội cẳng chân sau bó bột gãy xương","setting":"capcuu","level":"Khó","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":19,"sex":"nam","patient_label":"Anh N. H. B."},"presentation":{"intro":"Khoa Chấn thương chỉnh hình, 23 giờ. Sinh viên gãy kín hai xương cẳng chân trái do đá bóng, nắn bó bột 8 giờ trước. Từ chiều đau tăng dần, giờ uống giảm đau không đỡ. Ca mô phỏng, mọi thông tin là giả định.","place":null,"clock":null,"night":false},"vitals":{"hr":112,"sbp":140,"dbp":84,"rr":22,"temperature_c":37.6,"spo2":98},"history":[{"question":"Đau thế nào, có tăng dần không?","response":"Đau tăng dần, giờ như bị bóp nghẹt chặt trong bột; thuốc giảm đau uống không đỡ."},{"question":"Đau có khi cử động ngón chân không?","response":"Chỉ động nhẹ ngón là đau thốn lên bắp chân."},{"question":"Có tê, kiến bò, yếu ngón chân không?","response":"Ngón chân tê rần, nhúc nhích yếu hơn lúc chiều."},{"question":"Bột có chật, chân có sưng, nâng cao có đỡ không?","response":"Chân sưng lên, bột chật, kê cao cũng không bớt đau."},{"question":"Đã dùng thuốc giảm đau gì? Có dùng thuốc chống đông, bệnh nền gì không?","response":"Uống paracetamol và tramadol; không bệnh nền, không dùng chống đông."},{"question":"Tiền sử dị ứng thuốc?","response":"Không dị ứng."},{"question":"Ăn uống lần cuối?","response":"Ăn trưa lúc 12 giờ."},{"question":"Cơ chế chấn thương cụ thể?","response":"Bị đối phương va mạnh vào cẳng chân khi đá bóng."}],"examination":[{"group":"K","item":"Quan sát chi trái trong bột","finding":"Bột kín từ bàn chân đến gối, ngón chân phù nề, màu hơi tím, nóng."},{"group":"K","item":"Đau khi kéo duỗi thụ động ngón chân (sau khi rạch dọc bột)","finding":"Đau dữ dội khi gập mu bàn chân và ngón cái thụ động."},{"group":"K","item":"Khám khoang cẳng chân sau khi nới bột","finding":"Các khoang cẳng chân căng cứng như gỗ, ấn đau nhiều ở khoang trước và khoang sâu sau."},{"group":"K","item":"Mạch ngoại vi","finding":"Mạch mu chân và chày sau còn bắt được, yếu hơn bên phải; thời gian làm đầy mao mạch 3 giây."},{"group":"K","item":"Cảm giác và vận động ngón chân","finding":"Giảm cảm giác kẽ ngón I-II (thần kinh mác sâu), gập mu ngón cái yếu."},{"group":"K","item":"Các tổn thương khác","finding":"Không có tổn thương nơi khác; cột sống và chi còn lại bình thường."},{"group":"K","item":"Toàn thân","finding":"Vã mồ hôi, lo âu, GCS 15."}],"investigations":[{"name":"Đo áp lực khoang cẳng chân (khoang trước và khoang sâu sau)","duration_minutes":10,"result":"Khoang trước 52 mmHg, khoang sâu sau 58 mmHg; huyết áp tâm trương 84 mmHg nên delta áp lực 26-32 mmHg."},{"name":"Công thức máu, CK, ure, creatinin, điện giải","duration_minutes":10,"result":"CK 8400 U/L, creatinin 92 µmol/L, kali 4,9 mmol/L, bạch cầu 14 G/L."},{"name":"Nước tiểu (màu sắc, myoglobin)","duration_minutes":10,"result":"Nước tiểu sẫm, que thử hồng cầu dương tính với ít hồng cầu trên soi."},{"name":"X quang cẳng chân thẳng nghiêng sau nới bột","duration_minutes":10,"result":"Gãy 1/3 giữa hai xương cẳng chân, di lệch ít, bột chật."},{"name":"Điện tim","duration_minutes":10,"result":"Nhịp nhanh xoang, không bất thường."},{"name":"Chụp CT mạch chi dưới trước khi quyết định rạch cân","duration_minutes":40,"result":"Mạch còn, chẩn đoán là lâm sàng và áp lực khoang; mất thời gian vô ích."},{"name":"Siêu âm tĩnh mạch sâu chi dưới thường quy","duration_minutes":15,"result":"Không có chỉ định ở bệnh cảnh này."}],"choices":{"diagnosis":{"ydx":["Huyết khối tĩnh mạch sâu","Đau do cal xương và bột chật đơn thuần","Tổn thương động mạch khoeo kèm theo","Hội chứng khoang cấp cẳng chân trái sau gãy kín hai xương cẳng chân"]},"actions":["Ghi chép giờ khởi phát, theo dõi thần kinh mạch mỗi 1 giờ","Giảm đau tĩnh mạch theo bậc, tránh phong bế thần kinh vùng làm mất cảnh báo đau","Nới rộng bột (rạch dọc toàn bộ bột và băng lót), mở bột hoàn toàn","Chờ mất mạch hoặc liệt vận động mới quyết định mổ","Cố định ngoài hoặc kết hợp xương tạm thời cùng thì mở cân khi huyết động ổn","Đưa chi ngang mức tim, không nâng cao hơn tim","Xoa bóp mạnh vùng bắp chân để giảm căng","Nâng chi cao quá tim hoặc chườm đá lên chi","Thở oxy, 2 đường truyền, truyền dịch tinh thể đủ để duy trì huyết áp bình thường","Chuẩn bị mổ mở cân 4 khoang khẩn cấp, mời gây mê, chuẩn bị máu","Kiểm tra CK, creatinin, nước tiểu, điện giải","Đo áp lực khoang hoặc hội chẩn phẫu thuật mở cân khi delta áp lực dưới 30 mmHg"]}}'::jsonb,
  '5741c5e6de7689c17988a8f5f60e2e6ea5f0cfd97af5617fc9fcf1364e8bc16a'
)
on conflict (case_id) do update set
