insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'ngoai-cap-cuu-005',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-005","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-005-1","resource_type":"other","source":"Hội chứng khoang cấp: AAOS, Journal of the American Academy of Orthopaedic Surgeons, 2005 (Compartment syndrome review)","title":"Hội chứng khoang cấp: AAOS, Journal of the American Academy of Orthopaedic Surgeons, 2005 (Compartment syndrome review)","organization":null,"year_version":null,"citation":"Hội chứng khoang cấp: AAOS, Journal of the American Academy of Orthopaedic Surgeons, 2005 (Compartment syndrome review)","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-005-2","resource_type":"other","source":"ATLS 10th Edition (American College of Surgeons), Chapter 7: Musculoskeletal Trauma, 2018","title":"ATLS 10th Edition (American College of Surgeons), Chapter 7: Musculoskeletal Trauma, 2018","organization":null,"year_version":null,"citation":"ATLS 10th Edition (American College of Surgeons), Chapter 7: Musculoskeletal Trauma, 2018","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-005-3","resource_type":"other","source":"Hướng dẫn chẩn đoán và điều trị gãy xương và hội chứng khoang của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu)","title":"Hướng dẫn chẩn đoán và điều trị gãy xương và hội chứng khoang của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu)","organization":null,"year_version":null,"citation":"Hướng dẫn chẩn đoán và điều trị gãy xương và hội chứng khoang của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu)","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3,4],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Tổn thương động mạch khoeo kèm theo","credit":"none"},{"text":"Huyết khối tĩnh mạch sâu","credit":"none"},{"text":"Hội chứng khoang cấp cẳng chân trái sau gãy kín hai xương cẳng chân","credit":"full"},{"text":"Đau do cal xương và bột chật đơn thuần","credit":"none"}]},"action_options":[{"text":"Nới rộng bột (rạch dọc toàn bộ bột và băng lót), mở bột hoàn toàn","time_minutes":5,"grade":"critical","rationale":"Bột chật là nguyên nhân có thể đảo ngược nhanh nhất."},{"text":"Đưa chi ngang mức tim, không nâng cao hơn tim","time_minutes":1,"grade":"critical","rationale":"Nâng cao quá làm giảm áp lực tưới máu khoang."},{"text":"Đo áp lực khoang hoặc hội chẩn phẫu thuật mở cân khi delta áp lực dưới 30 mmHg","time_minutes":15,"grade":"critical","rationale":"Delta áp lực (tâm trương trừ áp lực khoang) 26-32 mmHg là ngưỡng chỉ định."},{"text":"Thở oxy, 2 đường truyền, truyền dịch tinh thể đủ để duy trì huyết áp bình thường","time_minutes":5,"grade":"critical","rationale":"Hạ huyết áp làm giảm áp lực tưới máu khoang."},{"text":"Giảm đau tĩnh mạch theo bậc, tránh phong bế thần kinh vùng làm mất cảnh báo đau","time_minutes":5,"grade":"critical","rationale":"Không làm che lấp dấu hiệu đau; không dùng gây tê vùng kéo dài."},{"text":"Chuẩn bị mổ mở cân 4 khoang khẩn cấp, mời gây mê, chuẩn bị máu","time_minutes":20,"grade":"recommended","rationale":"Không trì hoãn quá 6 giờ từ khi khởi phát."},{"text":"Kiểm tra CK, creatinin, nước tiểu, điện giải","time_minutes":15,"grade":"recommended","rationale":"Phát hiện sớm tiêu cơ vân và nguy cơ suy thận."},{"text":"Cố định ngoài hoặc kết hợp xương tạm thời cùng thì mở cân khi huyết động ổn","time_minutes":90,"grade":"recommended","rationale":"Ổn định xương giúp chăm sóc vết mổ giải áp."},{"text":"Ghi chép giờ khởi phát, theo dõi thần kinh mạch mỗi 1 giờ","time_minutes":2,"grade":"recommended","rationale":"Dấu hiệu tiến triển giúp định thời điểm can thiệp."},{"text":"Nâng chi cao quá tim hoặc chườm đá lên chi","time_minutes":3,"grade":"harmful","rationale":"Chườm đá co mạch, nâng cao quá tim làm giảm tưới máu khoang."},{"text":"Chờ mất mạch hoặc liệt vận động mới quyết định mổ","time_minutes":120,"grade":"harmful","rationale":"Mất mạch là dấu muộn, đã có hoại tử cơ và thần kinh không hồi phục."},{"text":"Xoa bóp mạnh vùng bắp chân để giảm căng","time_minutes":3,"grade":"harmful","rationale":"Tăng tổn thương cơ, không giải quyết nguyên nhân."}],"teaching_explanation":"Đau không tương xứng, đau khi kéo duỗi thụ động ngón và các khoang căng cứng là dấu hiệu sớm của hội chứng khoang, đặc biệt sau gãy xương cẳng chân bó bột. Xử trí khẩn: nới bột, giữ chi ngang tim, duy trì huyết áp và mổ mở cân sớm khi delta áp lực dưới 30 mmHg, không chờ mất mạch."}'::jsonb,
  'ab90795e65fce107ff30c940145a83a9ebafe6e43fcade22794cc157aa7fc13a'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-cap-cuu-006',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-006","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Gãy hở cẳng chân lộ xương, rách da rộng sau tai nạn","setting":"capcuu","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":40,"sex":"nam","patient_label":"Ông Ch. V. D."},"presentation":{"intro":"Phòng cấp cứu, 16 giờ. Ông đi xe máy bị xe tải quệt, ngã xuống ruộng bùn 90 phút trước. Cẳng chân phải biến dạng, đầu xương lộ ra ngoài, vết thương dính bùn đất. Ca mô phỏng, mọi thông tin là giả định.","place":null,"clock":null,"night":false},"vitals":{"hr":108,"sbp":100,"dbp":62,"rr":22,"temperature_c":36.9,"spo2":97},"history":[{"question":"Chấn thương xảy ra thế nào, ở đâu và cách đây bao lâu?","response":"Cách đây 90 phút, xe tải quệt, em ngã xuống ruộng, chân phải bị đè."},{"question":"Vết thương hở thế nào, có dính đất không?","response":"Xương nhô ra ngoài, dính bùn đất ruộng nhiều."},{"question":"Có tê, lạnh, mất cảm giác bàn chân không?","response":"Bàn chân lạnh, tê nhiều, khó cử động ngón."},{"question":"Đã sơ cứu thế nào?","response":"Người nhà lấy khăn ép và dùng nẹp tre tạm, không rửa gì."},{"question":"Có đau đầu, ngất, đau ngực bụng, chấn thương nơi khác?","response":"Hơi choáng nhưng không ngất; đau nhiều ở chân phải, ngoài ra không đau chỗ khác."},{"question":"Tiền sử bệnh, dị ứng thuốc, tiêm uốn ván?","response":"Tăng huyết áp không điều trị; không dị ứng; chưa tiêm uốn ván bao giờ."},{"question":"Ăn uống lần cuối?","response":"Ăn trưa lúc 12 giờ."},{"question":"Nghề nghiệp?","response":"Làm nông."}],"examination":[{"group":"K","item":"Đường thở, hô hấp, tuần hoàn (A, B, C)","finding":"Đường thở thông, thở đều, SpO2 97%, mạch 108, huyết áp 100/62, đã cầm máu bằng băng ép."},{"group":"K","item":"Vết thương cẳng chân phải","finding":"Vết rách 14 cm mặt trước trong, da mất khoảng 6x8 cm, xương chày lộ ra ngoài, nhiều bùn và dị vật, gãy phức tạp nhiều mảnh."},{"group":"K","item":"Mạch và tưới máu bàn chân phải","finding":"Mạch mu chân yếu, mạch chày sau không bắt được; bàn chân tái, lạnh, thời gian làm đầy mao mạch 4 giây."},{"group":"K","item":"Vận động và cảm giác bàn chân phải","finding":"Giảm cảm giác mu chân và lòng bàn chân; gập mu bàn chân yếu."},{"group":"K","item":"Khám các vùng khác theo ATLS","finding":"Đầu, cột sống, ngực, bụng, khung chậu không có tổn thương."},{"group":"K","item":"Khám khoang cẳng chân","finding":"Cẳng chân sưng căng nhưng mềm vì vết rách thoát áp."},{"group":"K","item":"Thần kinh","finding":"GCS 15."}],"investigations":[{"name":"X quang cẳng chân hai tư thế gồm cả khớp gối và cổ chân","duration_minutes":10,"result":"Gãy phức tạp nhiều mảnh 1/3 giữa và dưới xương chày, gãy xương mác, có hơi trong mô mềm."},{"name":"Công thức máu, nhóm máu, thử chéo, đông máu","duration_minutes":10,"result":"Hb 11,0 g/dL, bạch cầu 15 G/L, INR 1,1."},{"name":"Doppler hoặc chỉ số cổ chân-cánh tay (ABI)","duration_minutes":10,"result":"ABI 0,7 bên phải; giảm dòng chảy động mạch chày sau."},{"name":"Khí máu, lactate","duration_minutes":10,"result":"Lactate 2,6 mmol/L, không toan nặng."},{"name":"CTA chi dưới khi nghi tổn thương mạch kèm theo","duration_minutes":40,"result":"Chỉ làm khi cần xác định vị trí, không làm chậm kháng sinh và cố định."},{"name":"Cấy dịch vết thương bằng tăm bông tại phòng cấp cứu","duration_minutes":10,"result":"Không cải thiện kết cục, cấy lấy trong mổ cắt lọc mới có giá trị."},{"name":"Chụp MRI cẳng chân","duration_minutes":10,"result":"Không có chỉ định trong cấp cứu gãy hở."}],"choices":{"diagnosis":{"ydx":["Gãy hở thân hai xương cẳng chân phải độ IIIB (Gustilo-Anderson), nghi tổn thương mạch chày sau","Gãy hở độ I vết thương nhỏ sạch","Trật khớp cổ chân hở","Gãy kín thân hai xương cẳng chân có bóng nước"]},"actions":["Tiêm kháng sinh tĩnh mạch sớm trong vòng 1 giờ (cefazolin, phối hợp aminoglycoside theo độ nặng, thêm penicillin nếu đất bẩn)","Giảm đau tĩnh mạch, giữ ấm","Rửa vết thương bằng cồn hoặc dung dịch sát khuẩn đậm đặc và chờ cấy","Che vết thương bằng gạc vô khuẩn thấm nước muối, nẹp bất động chi, không đẩy xương lộ vào","Khâu kín da ngay tại phòng cấp cứu khi chưa cắt lọc","Đưa vào mổ rửa cắt lọc, cố định ngoài, sửa mạch nếu cần trong 24 giờ","Phòng uốn ván: vắc xin và globulin miễn dịch uốn ván","Rửa vết thương bằng nhiều nước muối sinh lý áp lực thấp trong phòng mổ","Đẩy đầu xương lộ ra vào trong hoặc nắn mạnh tại phòng cấp cứu","Làm X quang cẳng chân, đo ABI hoặc Doppler","Đánh giá ABC, kiểm soát chảy máu bằng băng ép, thở oxy, đường truyền lớn","Hội chẩn chấn thương chỉnh hình và phẫu thuật mạch"]}}'::jsonb,
  '9979cc6efa66ecc52d395a1f7da8ddd7d1ebd830f5e53811ca822c5fdd418080'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'ngoai-cap-cuu-006',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-006","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-006-1","resource_type":"other","source":"ATLS 10th Edition (American College of Surgeons), Chapter 7: Musculoskeletal Trauma, 2018","title":"ATLS 10th Edition (American College of Surgeons), Chapter 7: Musculoskeletal Trauma, 2018","organization":null,"year_version":null,"citation":"ATLS 10th Edition (American College of Surgeons), Chapter 7: Musculoskeletal Trauma, 2018","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-006-2","resource_type":"other","source":"BOAST 4: The Management of Severe Open Lower Limb Fractures (British Orthopaedic Association and BAPRAS), 2017","title":"BOAST 4: The Management of Severe Open Lower Limb Fractures (British Orthopaedic Association and BAPRAS), 2017","organization":null,"year_version":null,"citation":"BOAST 4: The Management of Severe Open Lower Limb Fractures (British Orthopaedic Association and BAPRAS), 2017","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-open-fracture-east-2011","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/21610369/","title":"EAST Practice Management Guidelines: Antibiotic prophylaxis in open fractures, 2011","organization":null,"year_version":null,"citation":"EAST Practice Management Guidelines: Antibiotic prophylaxis in open fractures, 2011","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5,6],"examination_essential_indices":[0,1,2,3,4],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Gãy hở thân hai xương cẳng chân phải độ IIIB (Gustilo-Anderson), nghi tổn thương mạch chày sau","credit":"full"},{"text":"Gãy kín thân hai xương cẳng chân có bóng nước","credit":"none"},{"text":"Gãy hở độ I vết thương nhỏ sạch","credit":"none"},{"text":"Trật khớp cổ chân hở","credit":"none"}]},"action_options":[{"text":"Đánh giá ABC, kiểm soát chảy máu bằng băng ép, thở oxy, đường truyền lớn","time_minutes":3,"grade":"critical","rationale":"Xử trí ATLS luôn đứng trước vết thương chi."},{"text":"Tiêm kháng sinh tĩnh mạch sớm trong vòng 1 giờ (cefazolin, phối hợp aminoglycoside theo độ nặng, thêm penicillin nếu đất bẩn)","time_minutes":5,"grade":"critical","rationale":"Kháng sinh sớm làm giảm nguy cơ nhiễm trùng ở gãy hở độ III."},{"text":"Che vết thương bằng gạc vô khuẩn thấm nước muối, nẹp bất động chi, không đẩy xương lộ vào","time_minutes":5,"grade":"critical","rationale":"Giảm nhiễm trùng, đau và tổn thương thêm."},{"text":"Phòng uốn ván: vắc xin và globulin miễn dịch uốn ván","time_minutes":5,"grade":"critical","rationale":"Chưa từng tiêm uốn ván, vết thương bẩn đất ruộng."},{"text":"Giảm đau tĩnh mạch, giữ ấm","time_minutes":5,"grade":"critical","rationale":"Kiểm soát đau và hạ thân nhiệt."},{"text":"Làm X quang cẳng chân, đo ABI hoặc Doppler","time_minutes":20,"grade":"recommended","rationale":"Đánh giá gãy xương và tưới máu chi."},{"text":"Hội chẩn chấn thương chỉnh hình và phẫu thuật mạch","time_minutes":10,"grade":"recommended","rationale":"Gãy độ IIIB kèm nghi tổn thương mạch là cấp cứu chi."},{"text":"Đưa vào mổ rửa cắt lọc, cố định ngoài, sửa mạch nếu cần trong 24 giờ","time_minutes":60,"grade":"recommended","rationale":"Cắt lọc kỹ và phủ da sớm giảm nhiễm trùng và biến chứng."},{"text":"Rửa vết thương bằng nhiều nước muối sinh lý áp lực thấp trong phòng mổ","time_minutes":10,"grade":"recommended","rationale":"Loại bỏ dị vật và giảm vi khuẩn."},{"text":"Đẩy đầu xương lộ ra vào trong hoặc nắn mạnh tại phòng cấp cứu","time_minutes":3,"grade":"harmful","rationale":"Mang vi khuẩn và đất vào sâu, làm nhiễm trùng xương."},{"text":"Khâu kín da ngay tại phòng cấp cứu khi chưa cắt lọc","time_minutes":10,"grade":"harmful","rationale":"Giữ lại mô hoại tử và vi khuẩn, nguy cơ nhiễm khuẩn kỵ khí."},{"text":"Rửa vết thương bằng cồn hoặc dung dịch sát khuẩn đậm đặc và chờ cấy","time_minutes":10,"grade":"harmful","rationale":"Gây độc mô, làm chậm kháng sinh và cắt lọc."}],"teaching_explanation":"Gãy hở độ III là cấp cứu: sau ABC, kháng sinh sớm trong 1 giờ, phòng uốn ván, che vết thương và nẹp, mổ rửa cắt lọc cố định ngoài trong vòng 24 giờ. Không đẩy xương lộ vào trong, không khâu kín khi chưa cắt lọc, không bỏ qua tổn thương mạch."}'::jsonb,
  'cc826c70d407973767f4a97bffa3781c28e4dc4e98664b06f4cb8f6dd4c4e2de'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-cap-cuu-007',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-007","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau thượng vị dữ dội sau uống rượu, thở nhanh và tụt huyết áp","setting":"capcuu","level":"Khó","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":48,"sex":"nam","patient_label":"Ông V. T. L."},"presentation":{"intro":"Khoa Cấp cứu, 3 giờ sáng. Ông đau thượng vị lan ra sau lưng 2 ngày sau một cuộc nhậu lớn, nôn nhiều, thở nhanh, tiểu ít. Ca mô phỏng, mọi thông tin là giả định.","place":null,"clock":null,"night":false},"vitals":{"hr":128,"sbp":84,"dbp":50,"rr":32,"temperature_c":38.4,"spo2":89},"history":[{"question":"Đau bụng khởi phát khi nào, tính chất, lan đi đâu?","response":"Đau thượng vị dữ dội 2 ngày, lan xuyên ra sau lưng, tăng khi nằm ngửa, đỡ chút khi ngồi cúi."},{"question":"Có nôn, bí trung tiện, chướng bụng không?","response":"Nôn nhiều, không ra hơi, bụng chướng."},{"question":"Liên quan rượu bia, sỏi mật, thuốc?","response":"Uống rượu nhiều trong 20 năm, vừa nhậu lớn 2 ngày trước; chưa biết sỏi mật."},{"question":"Có khó thở, ho, tiểu ít, lú lẫn không?","response":"Khó thở tăng dần, tiểu rất ít 12 giờ nay, người lơ mơ."},{"question":"Có sốt, vàng da, rét run không?","response":"Sốt nhẹ, mắt hơi vàng."},{"question":"Tiền sử tăng triglyceride, đái tháo đường, bệnh gan?","response":"Chưa kiểm tra mỡ máu, không đái tháo đường."},{"question":"Có đại tiện phân đen, nôn máu không?","response":"Không."},{"question":"Dị ứng thuốc?","response":"Không."}],"examination":[{"group":"K","item":"Đánh giá chung và tri giác","finding":"Lơ mơ nhẹ, vã mồ hôi, thở nhanh nông, da tái; GCS 14."},{"group":"K","item":"Khám tim phổi","finding":"Mạch nhanh, rì rào phế nang giảm đáy phổi phải, ran nổ hai đáy, thở co kéo."},{"group":"K","item":"Khám bụng","finding":"Bụng chướng vừa, đau và co cứng vùng thượng vị, bụng không mềm, nhu động ruột giảm."},{"group":"K","item":"Tưới máu và nước tiểu","finding":"Chi lạnh, thời gian làm đầy mao mạch 4 giây, sonde tiểu ra 40 mL trong 3 giờ."},{"group":"K","item":"Da, mắt","finding":"Vàng nhẹ củng mạc; quầng tím hai hông (dấu Grey Turner) mờ."},{"group":"K","item":"Dấu hiệu viêm phúc mạc lan tỏa","finding":"Phản ứng thành bụng khu trú thượng vị, chưa co cứng như gỗ."},{"group":"K","item":"Khám chi dưới","finding":"Không phù, không đau bắp chân."}],"investigations":[{"name":"Lipase và amylase máu","duration_minutes":10,"result":"Lipase 1620 U/L (hơn 3 lần giới hạn trên), amylase 1850 U/L."},{"name":"Công thức máu, CRP, đường huyết, điện giải, canxi, ure, creatinin, men gan, bilirubin","duration_minutes":10,"result":"Bạch cầu 21 G/L, Hct 52%, CRP 240 mg/L, glucose 11,6 mmol/L, canxi 1,7 mmol/L, ure 14 mmol/L, creatinin 210 µmol/L, ALT 96 U/L, bilirubin toàn phần 34 µmol/L."},{"name":"Khí máu động mạch và lactate","duration_minutes":10,"result":"pH 7,28; PaO2 58 mmHg; PaCO2 30 mmHg; HCO3 14 mmol/L; lactate 3,6 mmol/L; PaO2/FiO2 khoảng 130 khi thở oxy."},{"name":"Siêu âm bụng tại giường","duration_minutes":15,"result":"Tụy phù to, giảm âm, dịch quanh tụy; túi mật không sỏi rõ, ống mật chủ 7 mm; tràn dịch màng phổi phải ít."},{"name":"X quang ngực thẳng","duration_minutes":10,"result":"Thâm nhiễm hai đáy phổi, tràn dịch màng phổi phải ít, hình ảnh tổn thương phế nang lan tỏa."},{"name":"Triglyceride máu","duration_minutes":10,"result":"Triglyceride 5,8 mmol/L (tăng cao, có thể góp phần)."},{"name":"CT bụng có cản quang ngay khi nhập viện","duration_minutes":40,"result":"Không cần thiết giai đoạn sớm 72 giờ đầu; dễ làm nặng suy thận và không đổi xử trí hồi sức."},{"name":"Nội soi dạ dày khẩn mà không có xuất huyết","duration_minutes":20,"result":"Không có chỉ định."}],"choices":{"diagnosis":{"ydx":["Viêm tụy cấp nặng nghi hoại tử do rượu, có suy hô hấp, suy thận và sốc (suy đa tạng kéo dài)","Nhồi máu mạc treo ruột","Thủng ổ loét dạ dày tá tràng","Viêm tụy cấp nhẹ phù nề kẽ"]},"actions":["Mổ mở cắt lọc hoại tử khẩn trong 48 giờ đầu","Theo dõi suy thận, cân nhắc lọc máu khi vô niệu hoặc toan máu nặng, bù canxi khi cần","Dùng vận mạch (noradrenaline) khi tụt huyết áp kéo dài dù bù dịch hợp lý","Hội chẩn ngoại khoa, tiêu hóa, hồi sức; xem xét CT có cản quang sau 72 đến 96 giờ nếu xấu đi hoặc nghi hoại tử nhiễm trùng","Bắt đầu nuôi ăn ruột sớm trong 24 đến 72 giờ khi dung nạp, ống thông mũi hỗng tràng hoặc dạ dày","Truyền dịch tinh thể ồ ạt không giới hạn vượt mức mục tiêu","Siêu âm bụng, theo dõi triglyceride, đánh giá nguyên nhân (rượu, tăng triglyceride, sỏi)","Nhịn ăn và nuôi tĩnh mạch toàn phần kéo dài từ đầu","Giảm đau tĩnh mạch đa mô thức đủ liều","Đặt đường truyền trung tâm, catheter động mạch, sonde tiểu theo dõi nước tiểu","Hồi sức dịch Ringer lactate có kiểm soát, đo nước tiểu, lactate và Hct để chỉnh","Chuyển hồi sức, đặt oxy lưu lượng cao, theo dõi monitor và nâng đỡ hô hấp (cannula mũi dòng cao hoặc thông khí không xâm nhập), chuẩn bị đặt nội khí quản nếu suy hô hấp không cải thiện"]}}'::jsonb,
  '5ca11953e3a107d48827f32697787354aed0bfa82a488bfadcdacfb1f782e44c'
)
