values (
  'ngoai-cap-cuu-007',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-007","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-atlanta-2012","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/23100216/","title":"Revised Atlanta Classification of Acute Pancreatitis 2012 (Banks PA et al., Gut 2013)","organization":null,"year_version":null,"citation":"Revised Atlanta Classification of Acute Pancreatitis 2012 (Banks PA et al., Gut 2013)","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-pancreatitis-acg-2024-22ee1eeffb34","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/38857482/","title":"ACG Guideline: Management of Acute Pancreatitis, 2024 và IAP/APA Evidence-based guidelines for the management of acute pancreatitis, 2013","organization":null,"year_version":null,"citation":"ACG Guideline: Management of Acute Pancreatitis, 2024 và IAP/APA Evidence-based guidelines for the management of acute pancreatitis, 2013","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-pancreatitis-wses-2019","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/31210778/","title":"WSES Guidelines for the management of severe acute pancreatitis, 2019","organization":null,"year_version":null,"citation":"WSES Guidelines for the management of severe acute pancreatitis, 2019","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"essential"},{"index":5,"role":"neutral"},{"index":6,"role":"waste"},{"index":7,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Nhồi máu mạc treo ruột","credit":"none"},{"text":"Viêm tụy cấp nặng nghi hoại tử do rượu, có suy hô hấp, suy thận và sốc (suy đa tạng kéo dài)","credit":"full"},{"text":"Thủng ổ loét dạ dày tá tràng","credit":"none"},{"text":"Viêm tụy cấp nhẹ phù nề kẽ","credit":"none"}]},"action_options":[{"text":"Chuyển hồi sức, đặt oxy lưu lượng cao, theo dõi monitor và nâng đỡ hô hấp (cannula mũi dòng cao hoặc thông khí không xâm nhập), chuẩn bị đặt nội khí quản nếu suy hô hấp không cải thiện","time_minutes":5,"grade":"critical","rationale":"Suy hô hấp PaO2/FiO2 khoảng 130 cần hỗ trợ hô hấp sớm."},{"text":"Hồi sức dịch Ringer lactate có kiểm soát, đo nước tiểu, lactate và Hct để chỉnh","time_minutes":10,"grade":"critical","rationale":"Hồi sức dịch sớm và hợp lý cải thiện kết cục; tránh quá tải vì ARDS."},{"text":"Giảm đau tĩnh mạch đa mô thức đủ liều","time_minutes":5,"grade":"critical","rationale":"Đau là yếu tố nặng thêm; ưu tiên opioid khi cần."},{"text":"Đặt đường truyền trung tâm, catheter động mạch, sonde tiểu theo dõi nước tiểu","time_minutes":20,"grade":"critical","rationale":"Theo dõi huyết động và thể tích chính xác."},{"text":"Dùng vận mạch (noradrenaline) khi tụt huyết áp kéo dài dù bù dịch hợp lý","time_minutes":10,"grade":"critical","rationale":"Sốc kéo dài cần vận mạch để duy trì MAP tối thiểu 65 mmHg."},{"text":"Bắt đầu nuôi ăn ruột sớm trong 24 đến 72 giờ khi dung nạp, ống thông mũi hỗng tràng hoặc dạ dày","time_minutes":60,"grade":"recommended","rationale":"Nuôi ăn đường ruột sớm giảm nhiễm trùng và biến chứng."},{"text":"Theo dõi suy thận, cân nhắc lọc máu khi vô niệu hoặc toan máu nặng, bù canxi khi cần","time_minutes":30,"grade":"recommended","rationale":"Suy thận cấp là một phần của suy đa tạng."},{"text":"Siêu âm bụng, theo dõi triglyceride, đánh giá nguyên nhân (rượu, tăng triglyceride, sỏi)","time_minutes":20,"grade":"recommended","rationale":"Xác định nguyên nhân để dự phòng tái phát."},{"text":"Hội chẩn ngoại khoa, tiêu hóa, hồi sức; xem xét CT có cản quang sau 72 đến 96 giờ nếu xấu đi hoặc nghi hoại tử nhiễm trùng","time_minutes":10,"grade":"recommended","rationale":"Phối hợp để quyết định can thiệp khi cần."},{"text":"Mổ mở cắt lọc hoại tử khẩn trong 48 giờ đầu","time_minutes":120,"grade":"harmful","rationale":"Mổ sớm tăng tử vong; hoãn can thiệp sau 4 tuần nếu có thể và chọn can thiệp xâm lấn tối thiểu."},{"text":"Truyền dịch tinh thể ồ ạt không giới hạn vượt mức mục tiêu","time_minutes":30,"grade":"harmful","rationale":"Nguy cơ quá tải, ARDS nặng thêm và hội chứng khoang bụng."},{"text":"Nhịn ăn và nuôi tĩnh mạch toàn phần kéo dài từ đầu","time_minutes":60,"grade":"harmful","rationale":"Tăng nhiễm trùng, mất hàng rào ruột so với nuôi đường ruột."}],"teaching_explanation":"Viêm tụy cấp nặng cần hồi sức tích cực: dịch có kiểm soát, giảm đau, hỗ trợ hô hấp và thận, nuôi ăn đường ruột sớm. Không dùng kháng sinh dự phòng thường quy và không mổ cắt lọc sớm trong 48 giờ đầu."}'::jsonb,
  '5e39953cc508b0fa0ad6ec11db00705b206e998a6d5475f86c0c83f01663e268'
)
