values (
  'ngoai-cap-cuu-008',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-008","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Dao đâm vào bụng, ruột lòi ra ngoài","setting":"capcuu","level":"Dễ","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":26,"sex":"nam","patient_label":"Anh H. M. K."},"presentation":{"intro":"Phòng cấp cứu, 1 giờ sáng. Nam thanh niên bị đâm một nhát dao vào bụng trái 30 phút trước, quai ruột và mạc nối lòi ra ngoài vết thương. Ca mô phỏng, mọi thông tin là giả định.","place":null,"clock":null,"night":false},"vitals":{"hr":112,"sbp":96,"dbp":60,"rr":24,"temperature_c":36.7,"spo2":97},"history":[{"question":"Bị đâm lúc nào, bằng gì, mấy nhát?","response":"Cách đây 30 phút, một nhát dao ở bụng trái, ngoài ra không bị đâm chỗ khác."},{"question":"Đau bụng thế nào, lan đi đâu?","response":"Đau quặn ở bụng, càng lúc càng đau."},{"question":"Có buồn nôn, nôn ra máu, đại tiểu tiện ra máu không?","response":"Có buồn nôn, chưa nôn máu, chưa đi tiểu."},{"question":"Có choáng váng, vã mồ hôi?","response":"Chóng mặt, hơi lạnh người."},{"question":"Tiền sử bệnh, dị ứng, thuốc đang dùng?","response":"Khỏe mạnh, không dị ứng thuốc, không dùng thuốc nào."},{"question":"Đã sơ cứu thế nào? Có tự nhét ruột lại không?","response":"Người nhà lấy khăn sạch đậy lên, không nhét lại."},{"question":"Tiêm uốn ván lần cuối?","response":"Không nhớ."},{"question":"Ăn uống lần cuối?","response":"Ăn tối 4 giờ trước."}],"examination":[{"group":"K","item":"Đường thở, hô hấp","finding":"Đường thở thông, thở nhanh nhẹ, phổi hai bên đều."},{"group":"K","item":"Tuần hoàn","finding":"Mạch nhanh, huyết áp thấp nhẹ, thời gian làm đầy mao mạch 3 giây, da lạnh."},{"group":"K","item":"Vết thương bụng","finding":"Vết thương dài 4 cm hố chậu trái trên, quai ruột non khoảng 30 cm và mạc nối lớn lòi ra, ruột còn hồng, có ít dịch tiêu hóa."},{"group":"K","item":"Khám bụng toàn bộ","finding":"Bụng căng nhẹ, đau và phản ứng khắp bụng dưới, nhu động giảm."},{"group":"K","item":"Lăn trục kiểm tra lưng và các vùng khác","finding":"Không có vết thương ở lưng, ngực."},{"group":"K","item":"Thần kinh","finding":"GCS 15, tỉnh táo, hợp tác."},{"group":"K","item":"Tinh hoàn, hậu môn trực tràng","finding":"Không có máu ở hậu môn."}],"investigations":[{"name":"Siêu âm eFAST tại giường","duration_minutes":15,"result":"Có ít dịch tự do ở hố chậu trái và túi cùng Douglas; không dịch màng tim."},{"name":"Nhóm máu, thử chéo máu, công thức máu, đông máu","duration_minutes":10,"result":"Hb 12,8 g/dL, bạch cầu 14 G/L, INR 1,0. Chéo 2 đơn vị."},{"name":"Khí máu và lactate","duration_minutes":10,"result":"pH 7,34; lactate 2,8 mmol/L; BE -3."},{"name":"X quang ngực thẳng","duration_minutes":10,"result":"Không tràn khí hoặc dịch màng phổi, không liềm hơi dưới hoành."},{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Không có hồng cầu."},{"name":"CT bụng có cản quang khi đã có ruột lòi","duration_minutes":40,"result":"Không cần thiết, đã có chỉ định mổ thăm dò."},{"name":"Thăm dò vết thương bằng ngón tay hoặc kẹp tại phòng cấp cứu","duration_minutes":10,"result":"Không có giá trị, có thể gây tổn thương thêm."}],"choices":{"diagnosis":{"ydx":["Vết thương thấu bụng do dao có lòi ruột và mạc nối, nghi tổn thương tạng rỗng và sốc mất máu độ II","Thoát vị thành bụng nghẹt","Vết thương thành bụng chưa thấu phúc mạc","Vỡ gan do chấn thương kín"]},"actions":["Đánh giá ABC, thở oxy, 2 đường truyền lớn, lấy máu xét nghiệm và gọi máu","Chuyển phòng mổ thăm dò ổ bụng cấp cứu","Tiêm kháng sinh tĩnh mạch sớm (cefazolin phối hợp metronidazole hoặc cefoxitin)","Chụp CT bụng ngực khi đã có ruột lòi và huyết động không ổn","Nhịn ăn uống, đặt sonde dạ dày giải áp nếu cần và sonde tiểu","Giữ ấm, ghi chép thời gian bị thương và theo dõi sát dấu hiệu sinh tồn","Truyền dịch tinh thể ấm có kiểm soát, truyền máu khi mất máu nhiều","Thăm dò vết thương bằng kẹp hoặc ngón tay, cho ăn uống nước đường","Làm eFAST tại giường, không làm chậm chuyển mổ","Phòng uốn ván và giảm đau tĩnh mạch","Nhét ruột lòi vào ổ bụng tại phòng cấp cứu","Phủ ruột lòi bằng gạc vô khuẩn thấm nước muối ấm, che kín, không nhét lại"]}}'::jsonb,
  'd132f1af25f69c691411089c5fac82cc7816c95817b8b6c407c93a8825e40134'
)
