values (
  'ngoai-cap-cuu-008',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-008","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-008-1","resource_type":"other","source":"ATLS 10th Edition (American College of Surgeons), Chapter 5: Abdominal and Pelvic Trauma, 2018","title":"ATLS 10th Edition (American College of Surgeons), Chapter 5: Abdominal and Pelvic Trauma, 2018","organization":null,"year_version":null,"citation":"ATLS 10th Edition (American College of Surgeons), Chapter 5: Abdominal and Pelvic Trauma, 2018","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-penetrating-abd-wses-2022","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/35246190/","title":"WSES Guidelines: Management of penetrating abdominal trauma, 2022 (World Society of Emergency Surgery)","organization":null,"year_version":null,"citation":"WSES Guidelines: Management of penetrating abdominal trauma, 2022 (World Society of Emergency Surgery)","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-008-3","resource_type":"other","source":"Hướng dẫn quy trình cấp cứu chấn thương bụng của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu)","title":"Hướng dẫn quy trình cấp cứu chấn thương bụng của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu)","organization":null,"year_version":null,"citation":"Hướng dẫn quy trình cấp cứu chấn thương bụng của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu)","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5,7],"examination_essential_indices":[0,1,2,3,4],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Vết thương thành bụng chưa thấu phúc mạc","credit":"none"},{"text":"Vết thương thấu bụng do dao có lòi ruột và mạc nối, nghi tổn thương tạng rỗng và sốc mất máu độ II","credit":"full"},{"text":"Vỡ gan do chấn thương kín","credit":"none"},{"text":"Thoát vị thành bụng nghẹt","credit":"none"}]},"action_options":[{"text":"Đánh giá ABC, thở oxy, 2 đường truyền lớn, lấy máu xét nghiệm và gọi máu","time_minutes":3,"grade":"critical","rationale":"Hồi sức theo ATLS cho sốc mất máu độ II."},{"text":"Phủ ruột lòi bằng gạc vô khuẩn thấm nước muối ấm, che kín, không nhét lại","time_minutes":3,"grade":"critical","rationale":"Giữ ẩm ruột và giảm nhiễm trùng, tránh làm tổn thương thêm."},{"text":"Chuyển phòng mổ thăm dò ổ bụng cấp cứu","time_minutes":15,"grade":"critical","rationale":"Ruột lòi là chỉ định mổ tuyệt đối theo hướng dẫn thấu bụng."},{"text":"Truyền dịch tinh thể ấm có kiểm soát, truyền máu khi mất máu nhiều","time_minutes":10,"grade":"critical","rationale":"Hồi sức có kiểm soát đến lúc cầm máu."},{"text":"Làm eFAST tại giường, không làm chậm chuyển mổ","time_minutes":5,"grade":"critical","rationale":"Tìm dịch tự do hỗ trợ ra quyết định."},{"text":"Tiêm kháng sinh tĩnh mạch sớm (cefazolin phối hợp metronidazole hoặc cefoxitin)","time_minutes":5,"grade":"recommended","rationale":"Dự phòng nhiễm khuẩn ổ bụng do tổn thương tạng rỗng."},{"text":"Phòng uốn ván và giảm đau tĩnh mạch","time_minutes":5,"grade":"recommended","rationale":"Vết thương nhiễm bẩn, chưa rõ tiền sử uốn ván."},{"text":"Nhịn ăn uống, đặt sonde dạ dày giải áp nếu cần và sonde tiểu","time_minutes":10,"grade":"recommended","rationale":"Chuẩn bị gây mê và phẫu thuật."},{"text":"Giữ ấm, ghi chép thời gian bị thương và theo dõi sát dấu hiệu sinh tồn","time_minutes":2,"grade":"recommended","rationale":"Phòng hạ thân nhiệt và theo dõi diễn tiến."},{"text":"Nhét ruột lòi vào ổ bụng tại phòng cấp cứu","time_minutes":2,"grade":"harmful","rationale":"Ruột có thể đang thủng và nhiễm bẩn, đẩy vi khuẩn vào ổ bụng và bỏ sót tổn thương mạch mạc treo."},{"text":"Chụp CT bụng ngực khi đã có ruột lòi và huyết động không ổn","time_minutes":50,"grade":"harmful","rationale":"Làm chậm phẫu thuật không cần thiết."},{"text":"Thăm dò vết thương bằng kẹp hoặc ngón tay, cho ăn uống nước đường","time_minutes":15,"grade":"harmful","rationale":"Gây tổn thương thêm và nôn, hít sặc trước mổ."}],"teaching_explanation":"Ruột hoặc mạc nối lòi qua vết thương thấu bụng là chỉ định mổ thăm dò cấp cứu tuyệt đối. Cách xử trí đúng là hồi sức theo ABCDE, phủ gạc ẩm vô khuẩn, không nhét ruột lại, kháng sinh sớm và đưa đi mổ, không chụp CT làm chậm."}'::jsonb,
  'e5d7b0c9d2972618c811270dda7dc3592b1d967df6003635c5f5258d1f4ed3a8'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-cap-cuu-101',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-101","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau hố chậu trái, sốt và bụng cứng như gỗ","setting":"capcuu","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":68,"sex":"nữ","patient_label":"Bà N. T. L."},"presentation":{"intro":"Phòng cấp cứu, 3 giờ sáng. Bà 68 tuổi đau bụng dưới trái 3 ngày, đau dữ dội toàn bụng 6 giờ nay, sốt và nôn. Ca mô phỏng, mọi thông tin là giả định.","place":null,"clock":null,"night":false},"vitals":{"hr":116,"sbp":96,"dbp":58,"rr":26,"temperature_c":38.9,"spo2":94},"history":[{"question":"Đau bụng bắt đầu ở đâu, diễn tiến thế nào?","response":"Ba ngày nay đau âm ỉ bụng dưới bên trái, sáu giờ qua đau dữ dội lan khắp bụng, không dám cử động."},{"question":"Có sốt, nôn, bí trung đại tiện không?","response":"Sốt cao, nôn hai lần; hai ngày nay đi ngoài ít, hôm nay chưa trung tiện."},{"question":"Có từng được chẩn đoán viêm túi thừa hoặc táo bón kéo dài không?","response":"Táo bón nhiều năm; hai năm trước từng đau bụng dưới trái, bác sĩ nói viêm túi thừa và cho uống kháng sinh."},{"question":"Có dùng thuốc chống viêm giảm đau hoặc corticoid không?","response":"Uống thuốc giảm đau khớp (ibuprofen) hằng ngày nhiều năm."},{"question":"Có đi ngoài ra máu, sụt cân không?","response":"Không có máu trong phân, không sụt cân rõ."},{"question":"Tiền sử bệnh tim, tiểu đường, dị ứng thuốc?","response":"Tăng huyết áp dùng amlodipin; không dị ứng thuốc."},{"question":"Tiền sử phẫu thuật bụng?","response":"Cắt tử cung cách đây 20 năm."},{"question":"Lần ăn cuối?","response":"Bữa tối hôm qua, sau đó nôn."}],"examination":[{"group":"K","item":"Toàn trạng và tưới máu","finding":"Tỉnh, nhăn nhó, môi khô, da lạnh ẩm, thời gian làm đầy mao mạch 3 giây."},{"group":"K","item":"Nhìn và sờ bụng","finding":"Bụng chướng nhẹ, co cứng toàn bụng, phản ứng dội rõ, đau nhất hố chậu trái."},{"group":"K","item":"Gõ và nghe bụng","finding":"Mất vùng đục trước gan, âm ruột giảm."},{"group":"K","item":"Thăm trực tràng","finding":"Bóng trực tràng rỗng, đau khi thăm, không máu trên găng."},{"group":"K","item":"Tim phổi","finding":"Tim nhanh đều, phổi thông khí đều, không ran."},{"group":"K","item":"Vết mổ cũ","finding":"Sẹo mổ đường giữa dưới rốn đã liền tốt."}],"investigations":[{"name":"X quang bụng đứng không chuẩn bị hoặc ngực thẳng","duration_minutes":10,"result":"Liềm hơi dưới hoành phải."},{"name":"Công thức máu, CRP, lactate, điện giải, creatinin","duration_minutes":10,"result":"Bạch cầu 21 G/L, bạch cầu trung tính 90 phần trăm; CRP 260 mg/L; lactate 3,4 mmol/L; creatinin 130 µmol/L."},{"name":"CT bụng có cản quang tĩnh mạch nếu huyết động cho phép","duration_minutes":40,"result":"Khí tự do trong ổ bụng, dịch và khí quanh đoạn đại tràng sigma có nhiều túi thừa, thành sigma dày, có ổ tụ khí nhỏ quanh sigma; dịch lan tỏa ổ bụng."},{"name":"Khí máu động mạch","duration_minutes":10,"result":"pH 7,30; HCO3 17; BE -8."},{"name":"Điện tim","duration_minutes":10,"result":"Nhịp nhanh xoang, không biến đổi ST."},{"name":"Nội soi đại tràng ngay để tìm lỗ thủng","duration_minutes":20,"result":"Chống chỉ định khi viêm phúc mạc, nội soi bơm hơi làm tình trạng nặng thêm."},{"name":"Thụt tháo bằng barium","duration_minutes":10,"result":"Không có chỉ định khi nghi thủng."}],"choices":{"diagnosis":{"ydx":["Viêm túi thừa sigma không biến chứng","Thủng ổ loét dạ dày tá tràng","Viêm phúc mạc toàn thể do thủng túi thừa đại tràng sigma (Hinchey III đến IV), có nhiễm khuẩn huyết","Tắc ruột do u đại tràng đơn thuần"]},"actions":["Giải thích tình trạng nặng và khả năng hậu môn nhân tạo cho gia đình, ký cam kết mổ","Làm CT bụng chỉ khi huyết động đáp ứng hồi sức và không làm chậm mổ","Nhịn ăn uống, đặt sonde dạ dày giảm áp, sonde tiểu theo dõi nước tiểu","Giảm đau tĩnh mạch liều nhỏ chia nhỏ","Cho thuốc nhuận tràng và thụt tháo để giải quyết táo bón","Hội chẩn ngoại khoa tiêu hóa và gây mê hồi sức, đưa vào mổ cấp cứu","Nội soi đại tràng ngay để tìm lỗ thủng","Cho thuốc giảm đau chống viêm không steroid để giảm đau và hạ sốt","Cấy máu rồi dùng kháng sinh phổ rộng tĩnh mạch trong giờ đầu (phủ Gram âm và kỵ khí)","Thở oxy, đặt hai đường truyền lớn, truyền tinh thể ấm và đo lactate, nước tiểu","Chờ cấy máu có kết quả mới dùng kháng sinh","Dùng noradrenaline khi huyết áp trung bình dưới 65 mmHg dù đã bù dịch"]}}'::jsonb,
  '2612aedce3b88b56d48aeddeda635b09a18236a86e89f46b391b1dc0d5614478'
)
on conflict (case_id) do update set
