values (
  'ngoai-cap-cuu-101',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-101","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-diverticulitis-wses-2020","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/32381121/","title":"World Society of Emergency Surgery (WSES) guidelines for the management of acute left sided colonic diverticulitis in the emergency setting, World J Emerg Surg 2020. DOI: 10.1186/s13017-020-00336-x.","organization":null,"year_version":null,"citation":"World Society of Emergency Surgery (WSES) guidelines for the management of acute left sided colonic diverticulitis in the emergency setting, World J Emerg Surg 2020. DOI: 10.1186/s13017-020-00336-x.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-sepsis-ssc-2021-89948a253b0a","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/34605781/","title":"Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2021. DOI: 10.1007/s00134-021-06506-y.","organization":null,"year_version":null,"citation":"Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2021. DOI: 10.1007/s00134-021-06506-y.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-101-3","resource_type":"other","source":"Hướng dẫn chẩn đoán và điều trị nhiễm khuẩn huyết, sốc nhiễm khuẩn của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","title":"Hướng dẫn chẩn đoán và điều trị nhiễm khuẩn huyết, sốc nhiễm khuẩn của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","organization":null,"year_version":null,"citation":"Hướng dẫn chẩn đoán và điều trị nhiễm khuẩn huyết, sốc nhiễm khuẩn của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,5],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Tắc ruột do u đại tràng đơn thuần","credit":"none"},{"text":"Viêm túi thừa sigma không biến chứng","credit":"none"},{"text":"Viêm phúc mạc toàn thể do thủng túi thừa đại tràng sigma (Hinchey III đến IV), có nhiễm khuẩn huyết","credit":"full"},{"text":"Thủng ổ loét dạ dày tá tràng","credit":"none"}]},"action_options":[{"text":"Thở oxy, đặt hai đường truyền lớn, truyền tinh thể ấm và đo lactate, nước tiểu","time_minutes":5,"grade":"critical","rationale":"Có dấu sốc nhiễm khuẩn, cần hồi sức dịch sớm theo Surviving Sepsis."},{"text":"Cấy máu rồi dùng kháng sinh phổ rộng tĩnh mạch trong giờ đầu (phủ Gram âm và kỵ khí)","time_minutes":5,"grade":"critical","rationale":"Nhiễm khuẩn huyết do viêm phúc mạc cần kháng sinh sớm."},{"text":"Nhịn ăn uống, đặt sonde dạ dày giảm áp, sonde tiểu theo dõi nước tiểu","time_minutes":5,"grade":"critical","rationale":"Chuẩn bị mổ và theo dõi tưới máu thận."},{"text":"Giảm đau tĩnh mạch liều nhỏ chia nhỏ","time_minutes":3,"grade":"critical","rationale":"Giảm đau không che lấp khám bụng khi đã chẩn đoán rõ."},{"text":"Hội chẩn ngoại khoa tiêu hóa và gây mê hồi sức, đưa vào mổ cấp cứu","time_minutes":10,"grade":"recommended","rationale":"Viêm phúc mạc do thủng cần phẫu thuật kiểm soát nguồn nhiễm sớm."},{"text":"Dùng noradrenaline khi huyết áp trung bình dưới 65 mmHg dù đã bù dịch","time_minutes":10,"grade":"recommended","rationale":"Sốc nhiễm khuẩn kéo dài cần vận mạch."},{"text":"Làm CT bụng chỉ khi huyết động đáp ứng hồi sức và không làm chậm mổ","time_minutes":30,"grade":"recommended","rationale":"CT xác định nguyên nhân khi chưa rõ, nhưng X quang có liềm hơi và bụng cứng đã đủ chỉ định mổ."},{"text":"Giải thích tình trạng nặng và khả năng hậu môn nhân tạo cho gia đình, ký cam kết mổ","time_minutes":10,"grade":"recommended","rationale":"Quyền được thông tin và đồng thuận."},{"text":"Cho thuốc nhuận tràng và thụt tháo để giải quyết táo bón","time_minutes":10,"grade":"harmful","rationale":"Tăng áp lực lên lỗ thủng, làm ổ bụng nhiễm bẩn nặng thêm."},{"text":"Nội soi đại tràng ngay để tìm lỗ thủng","time_minutes":60,"grade":"harmful","rationale":"Nội soi bơm hơi trong viêm phúc mạc có thể làm lan phân vào ổ bụng."},{"text":"Chờ cấy máu có kết quả mới dùng kháng sinh","time_minutes":60,"grade":"harmful","rationale":"Kháng sinh phải dùng sớm khi nghi nhiễm khuẩn huyết."},{"text":"Cho thuốc giảm đau chống viêm không steroid để giảm đau và hạ sốt","time_minutes":5,"grade":"harmful","rationale":"NSAID là yếu tố nguy cơ thủng túi thừa và gây hại thận khi sốc."}],"teaching_explanation":"Bụng cứng, phản ứng dội và liềm hơi dưới hoành là đủ chỉ định mổ cấp cứu; không trì hoãn để làm thêm xét nghiệm. Thủng túi thừa sigma kèm viêm phúc mạc cần hồi sức, kháng sinh sớm và kiểm soát nguồn nhiễm, thường là phẫu thuật Hartmann khi tình trạng nặng. Tránh NSAID và thủ thuật bơm hơi."}'::jsonb,
  '2bc219bb597787ac45c2b4f129a6bdab6bbee640a46d9677ddf8625d4be8bf41'
)
