insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-cap-cuu-102',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-102","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau quặn bụng dữ dội, nôn mật và bụng chướng sau mổ cũ","setting":"capcuu","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":45,"sex":"nam","patient_label":"Anh T. Q. H."},"presentation":{"intro":"Phòng cấp cứu, 20 giờ. Nam 45 tuổi đau quặn bụng dữ dội từng cơn rồi đau liên tục, nôn mật, bụng chướng 10 giờ nay. Ca mô phỏng, mọi thông tin là giả định.","place":null,"clock":null,"night":false},"vitals":{"hr":118,"sbp":98,"dbp":60,"rr":24,"temperature_c":37.9,"spo2":96},"history":[{"question":"Đau bụng bắt đầu thế nào, có thay đổi tính chất không?","response":"Đau quặn từng cơn quanh rốn từ sáng, hai giờ nay đau liên tục, dữ dội hơn, thuốc giảm đau không bớt."},{"question":"Có nôn không, nôn ra gì? Có trung tiện, đi ngoài không?","response":"Nôn nhiều lần, ra dịch vàng xanh. Từ trưa không trung tiện, không đi ngoài."},{"question":"Đã mổ bụng lần nào chưa?","response":"Mổ ruột thừa vỡ cách đây 8 năm, mổ đường giữa dưới rốn."},{"question":"Có sốt, chướng bụng không?","response":"Bụng chướng dần, hơi sốt."},{"question":"Có đi ngoài ra máu hoặc sụt cân gần đây không?","response":"Không."},{"question":"Có bệnh tim, tiểu đường, dị ứng thuốc không?","response":"Khỏe mạnh, không dị ứng thuốc."},{"question":"Có dùng thuốc gì, uống rượu không?","response":"Thỉnh thoảng uống bia, không dùng thuốc thường xuyên."},{"question":"Lần ăn cuối?","response":"Bữa trưa, sau đó nôn."}],"examination":[{"group":"K","item":"Toàn trạng","finding":"Tỉnh, vẻ mặt đau, môi khô, da hơi lạnh, làm đầy mao mạch 3 giây."},{"group":"K","item":"Nhìn và sờ bụng","finding":"Bụng chướng, có sẹo mổ cũ đường giữa dưới rốn, đau khu trú quanh rốn và hố chậu phải, phản ứng thành bụng khu trú."},{"group":"K","item":"Gõ và nghe bụng","finding":"Gõ vang vùng chướng; nghe âm ruột lúc đầu tăng sau giảm dần."},{"group":"K","item":"Thoát vị thành bụng","finding":"Không có khối thoát vị bẹn, đùi hay sẹo mổ."},{"group":"K","item":"Thăm trực tràng","finding":"Bóng trực tràng rỗng, không máu."},{"group":"K","item":"Tim phổi","finding":"Tim nhanh đều, phổi trong."}],"investigations":[{"name":"X quang bụng đứng không chuẩn bị","duration_minutes":10,"result":"Nhiều mức nước hơi ở vùng giữa bụng, quai ruột non giãn, ít hơi trong đại tràng."},{"name":"CT bụng có cản quang","duration_minutes":40,"result":"Quai ruột non giãn, dấu xoáy ở mạc treo, một đoạn ruột thành mỏng, ngấm thuốc kém, ít dịch tự do; vùng chuyển tiếp ở hố chậu phải."},{"name":"Công thức máu, CRP, lactate, điện giải, creatinin","duration_minutes":10,"result":"Bạch cầu 16 G/L; CRP 95 mg/L; lactate 3,6 mmol/L; Na 133, K 3,1 mmol/L; creatinin 118 µmol/L."},{"name":"Khí máu động mạch","duration_minutes":10,"result":"pH 7,31; BE -6."},{"name":"Siêu âm bụng tại giường","duration_minutes":15,"result":"Quai ruột giãn, ít dịch tự do giữa các quai, nhu động giảm."},{"name":"Cho uống cản quang barium đường tiêu hóa trên","duration_minutes":10,"result":"Không phù hợp khi nôn nhiều, nghi xoắn và thiếu máu ruột, làm chậm mổ."},{"name":"Nội soi dạ dày","duration_minutes":20,"result":"Không có chỉ định trong tắc ruột non cấp."}],"choices":{"diagnosis":{"ydx":["Tắc ruột non quai kín do xoắn quanh dây dính sau mổ, nghi thiếu máu ruột","Tắc ruột do u đại tràng","Viêm ruột thừa cấp","Liệt ruột cơ năng do rối loạn điện giải"]},"actions":["Giảm đau tĩnh mạch an toàn sau khi đã có chẩn đoán","Giải thích khả năng cắt ruột và hậu quả cho gia đình, ký cam kết mổ","Cho uống barium để đánh giá vị trí tắc","Cho thuốc tăng nhu động ruột và thụt tháo để giải quyết tắc","Dùng kháng sinh phổ rộng tĩnh mạch trước mổ","Làm CT bụng có cản quang để xác định nguyên nhân và dấu thiếu máu","Hội chẩn ngoại khoa, chuẩn bị mổ cấp cứu sớm vì nghi xoắn quai kín và thiếu máu ruột","Điều trị bảo tồn kéo dài 48 đến 72 giờ khi đã nghi xoắn","Nhịn ăn uống, đặt sonde dạ dày giảm áp","Theo dõi sinh hiệu, nước tiểu, khí máu và lactate sau hồi sức","Truyền dịch glucose 5% đơn thuần để bù dịch","Đặt đường truyền lớn, bù dịch tinh thể và điện giải (đặc biệt kali), đo nước tiểu"]}}'::jsonb,
  '2540a226170b308b408532b777e01f89b4b761cf7386add7621f57dd131734a3'
)
