values (
  'ngoai-cap-cuu-102',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-102","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-asbo-bologna-2017-627c8d4cb120","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/29946347/","title":"World Society of Emergency Surgery (WSES) guidelines for adhesive small bowel obstruction, World J Emerg Surg 2018. DOI: 10.1186/s13017-018-0185-2.","organization":null,"year_version":null,"citation":"World Society of Emergency Surgery (WSES) guidelines for adhesive small bowel obstruction, World J Emerg Surg 2018. DOI: 10.1186/s13017-018-0185-2.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-102-3","resource_type":"other","source":"Hướng dẫn quy trình chẩn đoán và điều trị hội chứng tắc ruột cấp của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","title":"Hướng dẫn quy trình chẩn đoán và điều trị hội chứng tắc ruột cấp của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","organization":null,"year_version":null,"citation":"Hướng dẫn quy trình chẩn đoán và điều trị hội chứng tắc ruột cấp của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm ruột thừa cấp","credit":"none"},{"text":"Liệt ruột cơ năng do rối loạn điện giải","credit":"none"},{"text":"Tắc ruột non quai kín do xoắn quanh dây dính sau mổ, nghi thiếu máu ruột","credit":"full"},{"text":"Tắc ruột do u đại tràng","credit":"none"}]},"action_options":[{"text":"Đặt đường truyền lớn, bù dịch tinh thể và điện giải (đặc biệt kali), đo nước tiểu","time_minutes":10,"grade":"critical","rationale":"Mất dịch vào lòng ruột, nôn nhiều gây giảm thể tích và hạ kali."},{"text":"Nhịn ăn uống, đặt sonde dạ dày giảm áp","time_minutes":5,"grade":"critical","rationale":"Giảm nôn, giảm chướng và nguy cơ sặc."},{"text":"Hội chẩn ngoại khoa, chuẩn bị mổ cấp cứu sớm vì nghi xoắn quai kín và thiếu máu ruột","time_minutes":10,"grade":"critical","rationale":"Dấu hiệu đau liên tục, lactate tăng, CT có dấu xoáy cho thấy bảo tồn dễ gây hoại tử ruột."},{"text":"Dùng kháng sinh phổ rộng tĩnh mạch trước mổ","time_minutes":10,"grade":"critical","rationale":"Phòng nhiễm khuẩn khi nghi thiếu máu ruột."},{"text":"Giảm đau tĩnh mạch an toàn sau khi đã có chẩn đoán","time_minutes":5,"grade":"critical","rationale":"Giảm đau không che lấp bệnh khi đã làm hình ảnh."},{"text":"Làm CT bụng có cản quang để xác định nguyên nhân và dấu thiếu máu","time_minutes":30,"grade":"recommended","rationale":"CT giúp phân biệt xoắn, thoát vị và u."},{"text":"Theo dõi sinh hiệu, nước tiểu, khí máu và lactate sau hồi sức","time_minutes":15,"grade":"recommended","rationale":"Đánh giá đáp ứng và quyết định thời điểm mổ."},{"text":"Giải thích khả năng cắt ruột và hậu quả cho gia đình, ký cam kết mổ","time_minutes":10,"grade":"recommended","rationale":"Tôn trọng quyền được thông tin."},{"text":"Cho thuốc tăng nhu động ruột và thụt tháo để giải quyết tắc","time_minutes":5,"grade":"harmful","rationale":"Có thể làm ruột xoắn nặng thêm và gây thủng."},{"text":"Điều trị bảo tồn kéo dài 48 đến 72 giờ khi đã nghi xoắn","time_minutes":120,"grade":"harmful","rationale":"Trì hoãn mổ làm tăng nguy cơ hoại tử ruột và tử vong."},{"text":"Cho uống barium để đánh giá vị trí tắc","time_minutes":120,"grade":"harmful","rationale":"Không cần thiết, làm chậm mổ và nguy cơ sặc."},{"text":"Truyền dịch glucose 5% đơn thuần để bù dịch","time_minutes":10,"grade":"harmful","rationale":"Không bù được điện giải, làm hạ natri nặng thêm."}],"teaching_explanation":"Bụng có sẹo mổ cũ, nôn mật, chướng bụng và bí trung đại tiện là tắc ruột non do dây dính cho đến khi chứng minh khác. Đau liên tục, lactate tăng, CT có dấu xoáy mạc treo và ruột giảm ngấm thuốc gợi xoắn thiếu máu ruột, cần mổ sớm sau hồi sức, không kéo dài điều trị bảo tồn."}'::jsonb,
  '5fda27225578cc41b579db010103b006c19886920279b1eabdabf739f90f33eb'
)
