values (
  'ngoai-cap-cuu-103',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-103","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau hông lưng, sốt rét run và tụt huyết áp","setting":"capcuu","level":"Khó","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":54,"sex":"nữ","patient_label":"Bà L. T. M."},"presentation":{"intro":"Phòng cấp cứu, 15 giờ. Nữ 54 tuổi sốt rét run, đau hông lưng phải 2 ngày, hôm nay lơ mơ. Ca mô phỏng, mọi thông tin là giả định.","place":null,"clock":null,"night":false},"vitals":{"hr":124,"sbp":82,"dbp":46,"rr":28,"temperature_c":39.8,"spo2":94},"history":[{"question":"Đau hông lưng bắt đầu thế nào, có đau quặn lan xuống bẹn không?","response":"Hai ngày nay đau quặn hông lưng phải lan xuống bẹn, sau đó đau âm ỉ liên tục."},{"question":"Có sốt, rét run, tiểu buốt, tiểu đục không?","response":"Sốt rét run từ hôm qua, tiểu buốt, nước tiểu đục và ít."},{"question":"Có tiền sử sỏi thận hoặc nhiễm trùng tiểu không?","response":"Từng có sỏi thận phải cách đây 3 năm, chưa tán; hay bị viêm đường tiểu."},{"question":"Có tiểu đường hoặc dùng thuốc ức chế miễn dịch không?","response":"Tiểu đường típ 2 uống metformin."},{"question":"Có nôn, lơ mơ hoặc ngất không?","response":"Nôn một lần; người nhà thấy bà nói chậm, lơ mơ từ trưa."},{"question":"Có dị ứng thuốc, đang dùng thuốc gì khác?","response":"Không dị ứng thuốc."},{"question":"Có mang thai hoặc đang hành kinh không?","response":"Đã mãn kinh."},{"question":"Đã dùng kháng sinh gần đây chưa?","response":"Tự uống ciprofloxacin 2 ngày, đỡ ít."}],"examination":[{"group":"K","item":"Tri giác và tưới máu","finding":"Lơ mơ, GCS 13, chi lạnh, da nổi vân, làm đầy mao mạch 4 giây."},{"group":"K","item":"Vùng thận","finding":"Đau khi chạm vùng hông lưng phải, rung thận phải dương tính."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, đau nhẹ hạ sườn và hố chậu phải, không phản ứng phúc mạc."},{"group":"K","item":"Nước tiểu qua sonde","finding":"Ra rất ít nước tiểu đục, khoảng 20 mL trong giờ đầu."},{"group":"K","item":"Tim phổi","finding":"Tim nhanh đều, phổi thông khí đều."},{"group":"K","item":"Da","finding":"Không ban, không tổn thương da."}],"investigations":[{"name":"Công thức máu, CRP, procalcitonin, lactate, creatinin","duration_minutes":10,"result":"Bạch cầu 24 G/L; tiểu cầu 90 G/L; CRP 310 mg/L; procalcitonin tăng cao; lactate 4,6 mmol/L; creatinin 245 µmol/L."},{"name":"Cấy máu hai bộ và cấy nước tiểu trước kháng sinh","duration_minutes":10,"result":"Đã lấy mẫu; kết quả chờ."},{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Bạch cầu và nitrit dương tính, nhiều vi khuẩn, hồng cầu (+)."},{"name":"Siêu âm hệ tiết niệu tại giường","duration_minutes":15,"result":"Thận phải ứ nước độ III, sỏi bể thận phải khoảng 12 mm, thận trái bình thường."},{"name":"Khí máu động mạch","duration_minutes":10,"result":"pH 7,26; BE -10."},{"name":"CT bụng có tiêm cản quang tĩnh mạch ngay","duration_minutes":40,"result":"Không ưu tiên khi suy thận và sốc; nếu cần chỉ làm CT không cản quang sau ổn định, không làm chậm dẫn lưu."},{"name":"Chờ kết quả cấy mới quyết định kháng sinh và dẫn lưu","duration_minutes":10,"result":"Không phù hợp khi sốc nhiễm khuẩn."}],"choices":{"diagnosis":{"ydx":["Viêm đài bể thận cấp đơn thuần","Viêm ruột thừa cấp thể sau manh tràng","Cơn đau quặn thận không biến chứng","Sốc nhiễm khuẩn do viêm đài bể thận cấp trên thận ứ nước vì sỏi bể thận tắc nghẽn"]},"actions":["Tán sỏi ngoài cơ thể ngay khi thận đang nhiễm trùng ứ mủ","Siêu âm tiết niệu tại giường","Chờ kết quả cấy mới dùng kháng sinh","Cấy máu, cấy nước tiểu rồi dùng kháng sinh phổ rộng tĩnh mạch trong giờ đầu, chỉnh theo chức năng thận","Dùng noradrenaline khi MAP dưới 65 mmHg sau bù dịch","Chụp CT có tiêm cản quang tĩnh mạch liều cao ngay khi đang sốc và suy thận","Hội chẩn tiết niệu khẩn để giải áp đường tiết niệu (thông JJ hoặc dẫn lưu thận qua da)","Kiểm soát đường huyết bằng insulin, tạm ngừng metformin","Đặt sonde tiểu, theo dõi nước tiểu mỗi giờ, theo dõi lactate và khí máu","Chuyển hồi sức tích cực và theo dõi tri giác, hạ sốt","Thở oxy, hai đường truyền lớn, truyền tinh thể 30 mL/kg trong 3 giờ đầu và đánh giá lại","Chỉ dùng kháng sinh uống và hẹn tái khám"]}}'::jsonb,
  '363941eaf64c40c15965fcdeef7d200213e46b2e6ce516f12c265ebeab14c45d'
)
