venance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"essential"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm đài bể thận cấp đơn thuần","credit":"none"},{"text":"Cơn đau quặn thận không biến chứng","credit":"none"},{"text":"Sốc nhiễm khuẩn do viêm đài bể thận cấp trên thận ứ nước vì sỏi bể thận tắc nghẽn","credit":"full"},{"text":"Viêm ruột thừa cấp thể sau manh tràng","credit":"none"}]},"action_options":[{"text":"Thở oxy, hai đường truyền lớn, truyền tinh thể 30 mL/kg trong 3 giờ đầu và đánh giá lại","time_minutes":5,"grade":"critical","rationale":"Sốc nhiễm khuẩn cần hồi sức dịch sớm theo Surviving Sepsis."},{"text":"Cấy máu, cấy nước tiểu rồi dùng kháng sinh phổ rộng tĩnh mạch trong giờ đầu, chỉnh theo chức năng thận","time_minutes":5,"grade":"critical","rationale":"Mỗi giờ chậm kháng sinh làm tăng tử vong."},{"text":"Hội chẩn tiết niệu khẩn để giải áp đường tiết niệu (thông JJ hoặc dẫn lưu thận qua da)","time_minutes":10,"grade":"critical","rationale":"Nhiễm trùng trên tắc nghẽn cần kiểm soát nguồn nhiễm."},{"text":"Dùng noradrenaline khi MAP dưới 65 mmHg sau bù dịch","time_minutes":10,"grade":"critical","rationale":"Duy trì tưới máu cơ quan."},{"text":"Đặt sonde tiểu, theo dõi nước tiểu mỗi giờ, theo dõi lactate và khí máu","time_minutes":5,"grade":"critical","rationale":"Đánh giá đáp ứng hồi sức."},{"text":"Siêu âm tiết niệu tại giường","time_minutes":10,"grade":"recommended","rationale":"Xác định nhanh thận ứ nước do tắc nghẽn."},{"text":"Kiểm soát đường huyết bằng insulin, tạm ngừng metformin","time_minutes":10,"grade":"recommended","rationale":"Nhiễm toan lactate, suy thận làm tăng nguy cơ."},{"text":"Chuyển hồi sức tích cực và theo dõi tri giác, hạ sốt","time_minutes":10,"grade":"recommended","rationale":"Bệnh nặng có rối loạn tri giác."},{"text":"Chờ kết quả cấy mới dùng kháng sinh","time_minutes":60,"grade":"harmful","rationale":"Chậm kháng sinh làm tăng nguy cơ tử vong."},{"text":"Chỉ dùng kháng sinh uống và hẹn tái khám","time_minutes":5,"grade":"harmful","rationale":"Sốc nhiễm khuẩn không thể điều trị ngoại trú."},{"text":"Tán sỏi ngoài cơ thể ngay khi thận đang nhiễm trùng ứ mủ","time_minutes":60,"grade":"harmful","rationale":"Có thể làm vi khuẩn lan vào máu, nặng thêm sốc."},{"text":"Chụp CT có tiêm cản quang tĩnh mạch liều cao ngay khi đang sốc và suy thận","time_minutes":45,"grade":"harmful","rationale":"Làm chậm kiểm soát nguồn nhiễm, tăng nguy cơ tổn thương thận."}],"teaching_explanation":"Thận ứ nước kèm nhiễm khuẩn là cấp cứu tiết niệu: kháng sinh không đủ nếu không giải áp. Hồi sức, kháng sinh sớm trong giờ đầu và dẫn lưu khẩn (thông JJ hoặc mở thận ra da); sỏi xử lý sau khi hết nhiễm trùng."}'::jsonb,
